/// I riti propiziatori e le loro fonti, per raccolta e chiave
/// (`<raccolta>|<chiave>|<chiave>...`). Si leggono da
/// `IRitiPropiziatori`.
abstract final class IRitiPropiziatoriDati {
  static const Map<String, String> riti = {
    'contemplazione_dei_tarocchi|Asso di Bastoni|dritta': 'Tieni la carta davanti agli occhi e accendi quattro respiri vivi, rapidi all\'entrata e lenti all\'uscita. Guarda il bastone che spunta dalla mano fra le nuvole, con le sue foglie nuove. Ripeti tre volte: «Afferro la scintilla finché è viva». Poi apri le dita.',
    'contemplazione_dei_tarocchi|Asso di Bastoni|rovesciata': 'Respira sei volte con la carta davanti, lasciando che il fiato scaldi il petto. Osserva le foglie che spuntano dal legno, anche se il bastone è uno soltanto. Ripeti cinque volte, piano: «Ritrovo il desiderio prima di accendere». Lascia che la voce prenda calore a poco a poco.',
    'contemplazione_dei_tarocchi|Asso di Coppe|dritta': 'Lascia che la carta ti stia davanti per sette respiri fluidi, come acqua che scorre. Guarda la coppa traboccante che la mano offre dalle nuvole. Ripeti tre volte, con voce morbida: «Apro il cuore e lascio scorrere». Poi posa una mano sul petto e resta così.',
    'contemplazione_dei_tarocchi|Asso di Coppe|rovesciata': 'Per cinque respiri guarda lo schermo, lasciando che l\'aria arrivi sotto lo sterno. Segui con gli occhi il bordo della coppa, dove l\'acqua vorrebbe uscire. Ripeti sette volte, sottovoce: «Mi concedo di sentire». Ogni volta lascia andare un\'espirazione più lunga, come acqua che trabocca.',
    'contemplazione_dei_tarocchi|Asso di Denari|dritta': 'Con i piedi posati a terra, contempla la carta per quattro respiri pieni. Osserva il grande disco d\'oro offerto dalla mano, solido come un seme maturo. Ripeti sette volte: «Pianto il seme in terra buona». Poi senti il pavimento sotto di te, fermo e paziente come la terra.',
    'contemplazione_dei_tarocchi|Asso di Denari|rovesciata': 'Per sei respiri tieni gli occhi sulla carta, senza lasciarli andare altrove. Segui il bordo del disco d\'oro tutto intorno, finché lo vedi intero. Ripeti tre volte: «Guardo bene ciò che ho davanti». Poi alza gli occhi intorno a te, come per un primo sguardo.',
    'contemplazione_dei_tarocchi|Asso di Spade|dritta': 'Guarda la carta per quattro respiri limpidi, con la schiena eretta. Segui la spada che sale dalla mano verso la corona, diritta e sottile. Ripeti sette volte, con voce chiara: «Dico il vero con parole limpide». Poi lascia che lo sguardo resti netto, come la lama.',
    'contemplazione_dei_tarocchi|Asso di Spade|rovesciata': 'Per sei respiri guarda lo schermo, lasciando che la mente si posi come polvere. Fermati sulla punta della spada, il punto più sottile della figura. Ripeti cinque volte: «Rischiaro la mente prima di parlare». Poi lascia passare qualche istante di silenzio.',
    'contemplazione_dei_tarocchi|Cavaliere di Bastoni|dritta': 'Lascia scorrere cinque respiri ardenti davanti alla carta. Guarda il cavallo lanciato in avanti e il bastone tenuto alto dal cavaliere. Ripeti tre volte, con slancio: «Oso, con gli occhi sulla meta». Poi raccogli l\'ardore in un respiro lento, lungo, che scende fino ai piedi.',
    'contemplazione_dei_tarocchi|Cavaliere di Bastoni|rovesciata': 'Tieni la carta sullo schermo e conta sette respiri, ognuno un poco più calmo. Guarda le redini nella mano del cavaliere: sono loro a dare una rotta alla corsa. Ripeti cinque volte: «Do una meta al mio ardore». Lascia che il fiato rallenti come un cavallo al passo.',
    'contemplazione_dei_tarocchi|Cavaliere di Coppe|dritta': 'Tieni lo schermo davanti a te e lascia scorrere cinque respiri lenti, al passo di un cavallo. Guarda il cavaliere che porge la coppa davanti a sé. Ripeti tre volte: «Offro il mio cuore con grazia». Poi lascia che il gesto della figura resti negli occhi.',
    'contemplazione_dei_tarocchi|Cavaliere di Coppe|rovesciata': 'Concediti sette respiri davanti alla carta, lasciando che si facciano regolari. Guarda la coppa tesa del cavaliere e chiediti che cosa contiene davvero. Ripeti cinque volte: «Guardo se alle parole seguono i gesti». Poi respira ancora, con lo sguardo sulla coppa e sulla mano.',
    'contemplazione_dei_tarocchi|Cavaliere di Denari|dritta': 'Al passo di un cavallo da lavoro, conta nove respiri lenti e uguali davanti alla carta. Osserva il cavaliere che regge il disco con calma, senza correre. Ripeti cinque volte: «Avanzo con costanza, senza fermarmi». Poi lascia il respiro al suo ritmo di sempre.',
    'contemplazione_dei_tarocchi|Cavaliere di Denari|rovesciata': 'Per sei respiri tieni gli occhi sullo schermo, poi muovi appena le dita. Guarda il cavallo e immagina che sollevi uno zoccolo, il primo. Ripeti sette volte: «Muovo qualcosa, anche di piccolo». Lascia che quel piccolo movimento basti per oggi, senza chiedergli di più.',
    'contemplazione_dei_tarocchi|Cavaliere di Spade|dritta': 'Tieni lo schermo davanti a te e lascia scorrere cinque respiri rapidi, poi uno lento. Guarda il cavaliere lanciato in avanti con la spada levata. Ripeti sette volte: «Vado allo scopo senza travolgere nessuno». Poi lascia che il ritmo rallenti, come zoccoli che si posano.',
    'contemplazione_dei_tarocchi|Cavaliere di Spade|rovesciata': 'Respira sette volte davanti alla carta, allungando ogni pausa fra un respiro e l\'altro. Osserva le zampe del cavallo e immagina che si posino a terra. Ripeti cinque volte: «Un istante di pausa vale più della velocità». Poi resta in quiete ancora un poco.',
    'contemplazione_dei_tarocchi|Cinque di Bastoni|dritta': 'Accogli l\'energia della figura per sei respiri vivaci, senza trattenerla. Segui i cinque bastoni che si incrociano in ogni direzione, come in una gara di idee. Ripeti sette volte: «Uso la sfida per crescere, non per ferire». Poi lascia ricadere le braccia lungo i fianchi.',
    'contemplazione_dei_tarocchi|Cinque di Bastoni|rovesciata': 'Rallenta con quattro respiri davanti alla carta, uno per ogni pensiero di troppo. Cerca, fra i bastoni incrociati, quello che puoi lasciare cadere. Ripeti tre volte, sottovoce: «Scelgo le battaglie che contano». Lascia scivolare via le altre insieme all\'aria che esce.',
    'contemplazione_dei_tarocchi|Cinque di Coppe|dritta': 'Lascia scendere sei respiri lenti davanti alla carta, senza fretta di stare meglio. Guarda le coppe versate, poi cerca quelle ancora in piedi. Ripeti sette volte, a voce bassa: «Il dolore è vero ma non è tutto». Poi fermati sulle coppe intere, ancora un respiro.',
    'contemplazione_dei_tarocchi|Cinque di Coppe|rovesciata': 'Per cinque respiri guarda la carta, lasciando che il volto si sollevi appena. Porta gli occhi dalle coppe rovesciate alle coppe che restano. Ripeti tre volte: «Mi volto verso ciò che c\'è ancora». Lascia che la voce si apra un poco a ogni ripetizione, come una finestra.',
    'contemplazione_dei_tarocchi|Cinque di Denari|dritta': 'Guarda la carta per sei respiri caldi, come se scaldassi le mani a un fuoco. Fra i cinque dischi cerca quello più luminoso, come una finestra accesa nella notte. Ripeti cinque volte, piano: «Chiedo aiuto senza vergogna». Poi pensa a una porta a cui bussare.',
    'contemplazione_dei_tarocchi|Cinque di Denari|rovesciata': 'Respira sette volte davanti allo schermo, lasciando che ogni respiro scaldi un poco di più. Segui i cinque dischi dal più scuro al più chiaro. Ripeti tre volte: «Riaccolgo la fiducia, passo dopo passo». Poi lascia che il tepore resti, mentre torni alla tua giornata.',
    'contemplazione_dei_tarocchi|Cinque di Spade|dritta': 'Resta davanti alla figura per sei respiri, senza alzare la voce dentro di te. Guarda le cinque spade e chiediti quante ne servono davvero. Ripeti sette volte: «Mi chiedo se questa vittoria vale ciò che perdo». Poi lascia la domanda aperta.',
    'contemplazione_dei_tarocchi|Cinque di Spade|rovesciata': 'Respira cinque volte guardando lo schermo, lasciando scendere le spalle. Immagina di posare a terra una spada alla volta, fino all\'ultima. Ripeti tre volte: «Faccio il primo passo verso la pace». Poi lascia che il respiro si allarghi nello spazio delle armi posate.',
    'contemplazione_dei_tarocchi|Dieci di Bastoni|dritta': 'Raddrizza la schiena davanti allo schermo e respira sei volte, sentendo il peso sulle spalle. Guarda i dieci bastoni stretti tutti insieme in un fascio. Ripeti sette volte: «Porto ciò che è mio e poso il resto». A ogni ripetizione immagina di posarne uno, con delicatezza, a terra.',
    'contemplazione_dei_tarocchi|Dieci di Bastoni|rovesciata': 'Per cinque respiri guarda lo schermo, espirando come chi posa un carico. Conta i bastoni del fascio e scegline uno che non ti appartiene. Ripeti tre volte: «Alleggerirmi non tradisce nessuno». Poi respira a fondo, con le spalle sciolte e le mani vuote.',
    'contemplazione_dei_tarocchi|Dieci di Coppe|dritta': 'Lascia scorrere sei respiri ampi davanti alla carta. Segui l\'arco delle dieci coppe, come un arcobaleno sopra una casa abitata. Ripeti sette volte, con voce calda: «Ringrazio per i legami che ho». Poi pensa alle persone che ami, una alla volta, con il loro nome.',
    'contemplazione_dei_tarocchi|Dieci di Coppe|rovesciata': 'Per cinque respiri guarda lo schermo, lasciando le mani aperte sulle ginocchia. Cerca nell\'arco delle coppe il punto in cui sembra incrinarsi. Ripeti tre volte: «Ricucio con parole pazienti». Poi lascia che la frase prepari un gesto verso chi ti è vicino, una parola gentile.',
    'contemplazione_dei_tarocchi|Dieci di Denari|dritta': 'Lascia scorrere sei respiri profondi davanti alla carta, lenti come radici che crescono. Segui i dieci dischi disposti come i rami di un albero antico. Ripeti tre volte: «Pianto qualcosa che dura oltre me». Poi pensa alle tue radici, a chi c\'era prima di te.',
    'contemplazione_dei_tarocchi|Dieci di Denari|rovesciata': 'Guarda lo schermo per quattro respiri, sentendo il pavimento sotto i piedi. Fermati sul disco più in basso, quello che regge gli altri. Ripeti cinque volte: «Curo ciò che dura davvero». Poi lascia che lo sguardo risalga piano tutta la figura, disco dopo disco.',
    'contemplazione_dei_tarocchi|Dieci di Spade|dritta': 'Metti la figura al centro dello sguardo per sei respiri profondi, fino in fondo. Guarda le dieci spade, poi cerca nella figura il punto più chiaro. Ripeti sette volte: «Da qui si può soltanto risalire». Poi solleva piano lo sguardo verso quel punto chiaro.',
    'contemplazione_dei_tarocchi|Dieci di Spade|rovesciata': 'Lascia salire cinque respiri, uno sopra l\'altro, come gradini. Guarda le spade dall\'alto verso il basso, poi risali con lo sguardo fino al bordo superiore. Ripeti tre volte: «Mi rialzo con dolcezza e senza fretta». Poi lascia che lo sguardo resti in alto.',
    'contemplazione_dei_tarocchi|Due di Bastoni|dritta': 'Allarga lo sguardo sulla carta e lascia scorrere cinque respiri ampi. Guarda i due bastoni e lo spazio che lasciano aperto fra loro, come una via verso il largo. Ripeti sette volte: «Scelgo la rotta e guardo lontano». Poi chiudi gli occhi un istante.',
    'contemplazione_dei_tarocchi|Due di Bastoni|rovesciata': 'Prima di ogni altra cosa, tre respiri lenti con gli occhi sulla carta. Poi guarda il vuoto fra i due bastoni, come una porta da attraversare. Ripeti cinque volte, sottovoce: «Chiarisco ciò che voglio, poi faccio un passo». Respira ancora due volte prima di alzare lo sguardo.',
    'contemplazione_dei_tarocchi|Due di Coppe|dritta': 'Distendi il viso e concedi alla carta sei respiri tranquilli. Osserva le due coppe che si avvicinano, una di fronte all\'altra, come due mani che si cercano. Ripeti tre volte: «Coltivo con cura questo legame». Poi resta ancora un respiro sulla figura.',
    'contemplazione_dei_tarocchi|Due di Coppe|rovesciata': 'Respira quattro volte davanti alla carta, lentamente, con le mani aperte. Guarda lo spazio fra le due coppe e immagina che si accorci a ogni respiro. Ripeti cinque volte, piano: «Ascolto davvero prima di rispondere». Lascia che la frase prepari la prossima parola che dici.',
    'contemplazione_dei_tarocchi|Due di Denari|dritta': 'Lascia andare cinque respiri leggeri, quasi danzati, davanti alla carta. Guarda i due dischi e il nastro che li avvolge in un unico movimento. Ripeti sette volte, con leggerezza: «Tengo il ritmo senza irrigidirmi». Poi lascia oscillare piano le spalle, come un giocoliere.',
    'contemplazione_dei_tarocchi|Due di Denari|rovesciata': 'Respira quattro volte con gli occhi sullo schermo, lasciando cadere un pensiero a ogni uscita. Guarda il nastro che lega i due dischi e scegli quale tenere per primo. Ripeti cinque volte: «Scelgo le priorità e tengo bene poche cose». Poi riposa lo sguardo.',
    'contemplazione_dei_tarocchi|Due di Spade|dritta': 'Distendi le braccia e respira cinque volte, lentamente, guardando la carta. Guarda le due spade incrociate e il punto in cui si toccano. Ripeti tre volte: «Guardo ciò che sto evitando». Poi apri bene gli occhi sulla carta, senza abbassarli.',
    'contemplazione_dei_tarocchi|Due di Spade|rovesciata': 'Respira sette volte davanti alla carta, sciogliendo le braccia a ogni uscita. Guarda le spade incrociate e immagina di separarle con calma, una a destra e una a sinistra. Ripeti cinque volte: «Affronto adesso la scelta che rimandavo». Lascia l\'ultima parola nell\'aria.',
    'contemplazione_dei_tarocchi|Fante di Bastoni|dritta': 'Guarda la carta per quattro respiri curiosi, come chi apre una lettera. Osserva il giovane che tiene il bastone e lo guarda con meraviglia, come una cosa appena trovata. Ripeti sette volte, con voce viva: «Seguo l\'idea nuova che bussa». Poi sorridi alla figura.',
    'contemplazione_dei_tarocchi|Fante di Bastoni|rovesciata': 'Respira sei volte con gli occhi sulla carta, lasciando che l\'impazienza si posi. Fermati sulle mani del giovane intorno al bastone: tengono, non lanciano. Ripeti cinque volte: «Do forma al mio slancio prima che svanisca». Poi scegli un gesto, uno soltanto, da compiere oggi.',
    'contemplazione_dei_tarocchi|Fante di Coppe|dritta': 'Guarda la carta per quattro respiri leggeri, come si guarda l\'acqua in un bicchiere. Osserva il giovane che tiene la coppa e la osserva con stupore. Ripeti sette volte, piano: «Do spazio all\'emozione che nasce». Poi accogli ciò che senti, senza dargli subito un nome.',
    'contemplazione_dei_tarocchi|Fante di Coppe|rovesciata': 'Respira sei volte davanti alla carta, con le spalle morbide. Fermati sulle mani del giovane che tengono la coppa con delicatezza, senza stringerla. Ripeti cinque volte: «Custodisco la mia sensibilità senza murarla». Lascia che l\'ultima volta sia la più tenera, quasi una carezza.',
    'contemplazione_dei_tarocchi|Fante di Denari|dritta': 'Tieni la carta davanti e lascia andare cinque respiri attenti, come chi studia. Guarda il giovane che regge il disco e lo osserva con cura, senza fretta. Ripeti sette volte: «Coltivo l\'idea nuova con pazienza». Poi scegli il primo passo da studiare oggi.',
    'contemplazione_dei_tarocchi|Fante di Denari|rovesciata': 'Respira sei volte con gli occhi sulla carta, riportando lo sguardo ogni volta che scappa. Osserva le mani del giovane intorno al disco, ancora immobili. Ripeti tre volte: «Riprendo il lavoro con un piccolo gesto». Poi muovi le mani, come per cominciare adesso.',
    'contemplazione_dei_tarocchi|Fante di Spade|dritta': 'Come chi osserva il vento, resta sulla carta per quattro respiri attenti. Osserva il giovane con la spada levata e lo sguardo rivolto lontano. Ripeti cinque volte: «Osservo con cura e scelgo le parole». Poi resta un istante in ascolto dei suoni intorno.',
    'contemplazione_dei_tarocchi|Fante di Spade|rovesciata': 'Per sei respiri tieni gli occhi sullo schermo, con le labbra chiuse. Fermati sulla lama del giovane e immagina di abbassarla piano. Ripeti tre volte, sottovoce: «Verifico prima di parlare». Poi lascia passare un respiro intero prima di ogni parola che dici oggi.',
    'contemplazione_dei_tarocchi|Gli Amanti|dritta': 'Lascia la carta davanti agli occhi per sette respiri tranquilli. Guarda le due figure sotto la presenza alata che le sovrasta, poi lo spazio che le separa e insieme le unisce. Ripeti tre volte, con voce calda: «Scelgo con la testa e col cuore insieme». Respira ancora.',
    'contemplazione_dei_tarocchi|Gli Amanti|rovesciata': 'Volgi lo sguardo allo schermo e respira cinque volte, lentamente. Cerca il punto della figura in cui il desiderio chiede verità, là dove gli sguardi non si incontrano. Ripeti sette volte, a mezza voce: «Prima di scegliere, mi dico la verità». Poi lascia riposare il respiro.',
    'contemplazione_dei_tarocchi|Il Carro|dritta': 'Tieni lo schermo ben fermo e lascia scorrere sei respiri decisi. Guarda le due creature del traino, diverse fra loro, che tirano verso la stessa meta. Pronuncia sette volte, con voce salda: «Tengo la direzione, le forze mi seguono». Poi lascia riposare lo sguardo sul conducente.',
    'contemplazione_dei_tarocchi|Il Carro|rovesciata': 'Per quattro respiri resta sulla figura, lasciando che il fiato si allunghi. Guarda il conducente al centro del carro: la sua forza viene dallo stare nel mezzo, senza strattoni. Ripeti cinque volte: «Torno al centro, poi riprendo la strada». Senti il peso posarsi sul sedile.',
    'contemplazione_dei_tarocchi|Il Diavolo|dritta': 'Mettiti di fronte alla figura dipinta per sei respiri, senza distogliere lo sguardo. Guarda i legami al collo delle due piccole figure: sono larghi, potrebbero sfilarsi. Ripeti tre volte, con voce chiara: «Nomino ciò che mi lega e lo guardo». Poi espira lentamente, fino in fondo.',
    'contemplazione_dei_tarocchi|Il Diavolo|rovesciata': 'Concedi cinque respiri alla carta sullo schermo, lasciando che il petto si apra. Cerca il punto in cui il legame passa intorno al collo e immagina di allentarlo con due dita. Ripeti sette volte: «Sciolgo con dolcezza il nodo che vedo». Lascia scendere le spalle.',
    'contemplazione_dei_tarocchi|Il Giudizio|dritta': 'Porta la figura all\'altezza degli occhi e lascia salire sette respiri, uno dopo l\'altro. Guarda l\'angelo con la tromba e le figure che si alzano a rispondere. Ripeti tre volte, con voce limpida: «Rispondo alla chiamata di una vita più vera». Poi lascia risuonare il silenzio.',
    'contemplazione_dei_tarocchi|Il Giudizio|rovesciata': 'Guarda lo schermo per cinque respiri, senza giudicare nemmeno il respiro. Fermati sulle braccia aperte delle figure che ascoltano il suono della tromba. Ripeti sette volte, con voce bassa e lenta: «Mi ascolto prima di giudicarmi». Lascia che la voce si addolcisca a ogni ripetizione.',
    'contemplazione_dei_tarocchi|Il Mago|dritta': 'Fissa la carta sullo schermo e respira sei volte, lasciando che l\'aria arrivi fino in fondo. Segui la mano alzata verso il cielo, poi l\'altra che indica la terra sopra gli strumenti del tavolo. Ripeti sette volte, con voce piena: «Ciò che penso diventa gesto adesso».',
    'contemplazione_dei_tarocchi|Il Mago|rovesciata': 'Resta con gli occhi sulla figura per cinque respiri lunghi. Guarda gli strumenti posati sul tavolo, uno per uno, come attrezzi che aspettano una mano. Poi, a voce bassa, ripeti tre volte: «Le mie parole e le mie mani vanno insieme». Chiudi con un respiro più lento.',
    'contemplazione_dei_tarocchi|Il Matto|dritta': 'Tieni la carta davanti agli occhi sullo schermo e lascia scendere cinque respiri lenti. Guarda il fagotto sulla spalla, poi il piede sospeso sull\'orlo del dirupo. Quando lo sguardo si fa quieto, ripeti tre volte a voce bassa: «Faccio il primo passo con fiducia».',
    'contemplazione_dei_tarocchi|Il Matto|rovesciata': 'Porta lo schermo all\'altezza dello sguardo e conta quattro respiri, senza fretta. Osserva il cane che abbaia accanto ai piedi: è il richiamo che avverte prima del salto. Pronuncia cinque volte, piano: «Guardo dove metto il piede, poi scelgo». Lascia che la frase rallenti il passo.',
    'contemplazione_dei_tarocchi|Il Mondo|dritta': 'Lascia che la carta ti riempia lo sguardo per nove respiri ampi. Segui la ghirlanda che racchiude la figura danzante, poi le quattro creature agli angoli. Ripeti tre volte: «Accolgo ciò che si è compiuto». Poi resta un momento dentro quel cerchio, senza uscirne subito.',
    'contemplazione_dei_tarocchi|Il Mondo|rovesciata': 'Per sei respiri tieni gli occhi sulla carta, lentamente. Cerca il punto in cui la ghirlanda si chiude: lì manca soltanto un nodo da stringere. Ripeti cinque volte, con voce calma: «Porto a termine l\'ultimo tratto». Lascia che l\'ultima volta suoni come un punto fermo.',
    'contemplazione_dei_tarocchi|Il Papa|dritta': 'Con la carta davanti agli occhi, conta quattro respiri come si contano i grani di una corona. Guarda la mano alzata a benedire e le due figure raccolte ai piedi del trono. Ripeti tre volte, piano: «Accolgo la guida che viene da lontano». Poi resta in ascolto.',
    'contemplazione_dei_tarocchi|Il Papa|rovesciata': 'Prenditi sei respiri davanti allo schermo, senza cercare risposte. Guarda le due figure inginocchiate e chiediti quale insegnamento ricevuto senti ancora tuo. Mormora cinque volte: «Tengo ciò che mi fa respirare, il resto lo rivedo». Lascia che l\'ultima volta sia la più lenta.',
    'contemplazione_dei_tarocchi|Il Sole|dritta': 'Lascia entrare quattro respiri ampi davanti alla carta, come aria in una mattina d\'estate. Guarda i raggi che scendono sulla figura giovane e la scaldano tutta. Ripeti tre volte, sorridendo se ti viene: «Lascio splendere ciò che sono». Poi resta un momento in quella luce.',
    'contemplazione_dei_tarocchi|Il Sole|rovesciata': 'Concediti sei respiri davanti allo schermo, con il viso rilassato. Guarda il muro basso dietro la figura giovane: copre poco, la luce lo supera. Ripeti cinque volte, piano: «Lascio cadere la nube e sento il calore». Lascia che la frase scaldi la voce mentre la pronunci.',
    'contemplazione_dei_tarocchi|L\'Appeso|dritta': 'Rimani con gli occhi sulla figura capovolta per sette respiri lenti. Osserva il volto quieto nonostante la posizione, le gambe incrociate, le mani dietro la schiena. Ripeti tre volte, quasi in un soffio: «Fermarmi mi mostra ciò che prima non vedevo». Poi lascia la carta ancora un momento.',
    'contemplazione_dei_tarocchi|L\'Appeso|rovesciata': 'Guarda lo schermo per quattro respiri, sentendo i piedi ben posati a terra. Poi segui la corda che lega la figura al legno e chiediti se quell\'attesa ti insegna ancora qualcosa. Ripeti cinque volte: «Scelgo se aspettare ancora o tornare ad agire». Respira con calma.',
    'contemplazione_dei_tarocchi|L\'Eremita|dritta': 'Abbassa le luci se puoi e tieni la carta davanti agli occhi per nove respiri. Segui la lanterna alzata e la piccola luce che brilla dentro. Ripeti tre volte, a voce bassissima: «Un passo alla volta, la mia luce basta». Poi resta ancora nel silenzio.',
    'contemplazione_dei_tarocchi|L\'Eremita|rovesciata': 'Guarda lo schermo per sei respiri, lasciando che l\'aria entri piano. Osserva il bastone a cui la figura si appoggia: aiuta a camminare, anche verso gli altri. Pronuncia cinque volte: «La mia lanterna illumina anche la strada del ritorno». Chiudi aprendo lo sguardo intorno a te.',
    'contemplazione_dei_tarocchi|L\'Imperatore|dritta': 'Siedi con la schiena eretta e guarda la carta per sei respiri pieni. Osserva il trono di pietra squadrata, le teste d\'ariete scolpite, il globo nella mano. Pronuncia tre volte, con voce ferma: «Do forma salda a ciò che costruisco». Poi lascia andare le spalle.',
    'contemplazione_dei_tarocchi|L\'Imperatore|rovesciata': 'Davanti allo schermo lascia passare cinque respiri, più lunghi nell\'uscita che nell\'entrata. Fermati sull\'armatura sotto il mantello: chiediti dove l\'ordine ti tiene in piedi e dove ti stringe. Ripeti sette volte: «Scelgo l\'ordine che protegge, non quello che chiude». Poi lascia andare la stretta.',
    'contemplazione_dei_tarocchi|L\'Imperatrice|dritta': 'Accomoda lo schermo davanti a te e concediti cinque respiri morbidi. Lascia scorrere gli occhi sul grano maturo ai piedi del trono, poi sullo scettro che la figura regge con calma. Ripeti sette volte, con voce piana: «Nutro ciò che cresce e rispetto i suoi tempi».',
    'contemplazione_dei_tarocchi|L\'Imperatrice|rovesciata': 'Per quattro respiri tieni gli occhi sulla figura, lasciando che le spalle si abbassino. Guarda lo scudo appoggiato accanto al trono, col suo segno inciso. Poi, a voce bassa, ripeti cinque volte: «Anche io ricevo la cura che do». Senti la frase tornare verso di te, come un\'onda.',
    'contemplazione_dei_tarocchi|La Forza|dritta': 'Davanti alla carta, prenditi sei respiri dolci e profondi. Posa lo sguardo sulle mani della figura che chiudono piano le fauci del leone, senza stringere. Ripeti sette volte, con tenerezza: «Tengo l\'istinto con mano gentile e ferma». Senti le tue mani ammorbidirsi in grembo.',
    'contemplazione_dei_tarocchi|La Forza|rovesciata': 'Senza alcuno sforzo, lascia la carta davanti a te per cinque respiri lunghi. Guarda la curva dell\'infinito sopra il capo della figura, poi il muso del leone che si placa. Ripeti cinque volte: «Torno a trattarmi con mitezza». Lascia andare ogni stretta.',
    'contemplazione_dei_tarocchi|La Giustizia|dritta': 'Porta gli occhi sulla carta e misura cinque respiri uguali, come due piatti in pari. Guarda la bilancia in una mano e la spada diritta nell\'altra. Ripeti tre volte, chiaramente: «Agisco con onestà e accolgo ciò che ho seminato». Poi lascia il respiro in equilibrio.',
    'contemplazione_dei_tarocchi|La Giustizia|rovesciata': 'Respira sette volte davanti allo schermo, con calma, finché il fiato si fa regolare. Fermati sullo sguardo diritto della figura: non accusa, guarda. Poi ripeti cinque volte, sottovoce: «Guardo in faccia ciò che rimando». Lascia che la frase trovi il suo peso dentro di te.',
    'contemplazione_dei_tarocchi|La Luna|dritta': 'Abbassa la luce intorno a te e guarda la carta per sei respiri lenti. Segui il sentiero che sale dall\'acqua fra le due torri, sotto il volto pallido nel cielo. Ripeti tre volte, in un sussurro: «Procedo con intuito anche dove non vedo». Poi lascia che gli occhi si abituino.',
    'contemplazione_dei_tarocchi|La Luna|rovesciata': 'Tieni gli occhi sullo schermo per cinque respiri, lasciandoli allungare. Guarda la creatura che esce dall\'acqua e i due cani che ululano: alla luce sono più piccoli di quanto sembrano. Ripeti sette volte: «Guardo con occhi nuovi ciò che temevo». Poi apri piano lo sguardo.',
    'contemplazione_dei_tarocchi|La Morte|dritta': 'Posa gli occhi sulla figura dipinta e lascia andare sei respiri, uno dopo l\'altro. Osserva il passo lento della figura scura: avanza senza voltarsi indietro. Ripeti sette volte, lentamente: «Lascio finire ciò che ha finito, accolgo il nuovo». Poi lascia uscire un respiro lungo.',
    'contemplazione_dei_tarocchi|La Morte|rovesciata': 'Per cinque respiri tieni gli occhi sullo schermo, aprendo piano le mani in grembo. Guarda ciò che sta ai piedi della figura: tutto quello che cade fa spazio. Ripeti tre volte, con voce quieta: «Apro la mano e lascio passare il cambiamento». Lascia che la mano resti aperta.',
    'contemplazione_dei_tarocchi|La Papessa|dritta': 'Fai silenzio intorno e lascia la carta davanti agli occhi per sette respiri. Posa lo sguardo sul rotolo stretto in grembo, poi sul velo teso fra le due colonne. Senza muovere quasi le labbra, ripeti tre volte: «Ascolto nel silenzio ciò che so già». Lascia il resto fuori.',
    'contemplazione_dei_tarocchi|La Papessa|rovesciata': 'Abbassa il rumore che hai intorno, poi guarda lo schermo per sei respiri quieti. Cerca la falce di luna ai piedi della figura, quasi nascosta dal mantello. Sussurra cinque volte: «Do spazio alla voce che sa». Ogni ripetizione più lenta della precedente, finché la voce diventa un soffio.',
    'contemplazione_dei_tarocchi|La Ruota della Fortuna|dritta': 'Lascia girare cinque respiri, come giri lenti di una ruota, davanti alla carta. Segui il cerchio da una figura all\'altra, senza fermarti su nessuna. Ripeti sette volte, con voce leggera: «Mi muovo con la ruota, non contro». L\'ultima volta lascia che la voce si spenga.',
    'contemplazione_dei_tarocchi|La Ruota della Fortuna|rovesciata': 'Lascia la carta sullo schermo e conta quattro respiri, sostando un istante dopo ognuno. Guarda il mozzo della ruota, l\'unico punto che resta immobile mentre tutto gira. Ripeti tre volte: «Nella sosta raccolgo le forze per il prossimo giro». Poi riprendi a respirare come viene.',
    'contemplazione_dei_tarocchi|La Stella|dritta': 'Lascia che la carta ti stia davanti per nove respiri morbidi, come in una notte limpida. Guarda l\'acqua che scorre dalle due brocche e la grande stella sopra il capo. Ripeti sette volte, con voce lieve: «Mi affido a questa luce quieta». Poi resta a guardarla.',
    'contemplazione_dei_tarocchi|La Stella|rovesciata': 'Per sette respiri guarda lo schermo, lasciando che l\'aria scenda piano. Conta le piccole stelle intorno alla grande, una per una, fino all\'ultima. Ripeti cinque volte: «La luce c\'è anche quando è velata». Lascia che ogni volta la voce si faccia un poco più chiara.',
    'contemplazione_dei_tarocchi|La Temperanza|dritta': 'Davanti alla carta, fai scorrere sette respiri regolari, come acqua da un vaso all\'altro. Guarda il getto sottile fra le due coppe, che non si interrompe mai. Ripeti tre volte: «Unisco con pazienza ciò che sembrava diviso». Poi resta nella misura del respiro, senza contarlo.',
    'contemplazione_dei_tarocchi|La Temperanza|rovesciata': 'Rallenta prima di tutto, poi guarda lo schermo per cinque respiri. Fermati sulle due coppe tenute ad altezze diverse e sul filo d\'acqua che le lega. Ripeti sette volte, piano: «Rallento e ritrovo la mia misura». Fra una ripetizione e l\'altra lascia passare un respiro intero.',
    'contemplazione_dei_tarocchi|La Torre|dritta': 'Davanti alla carta, concediti quattro respiri profondi, restando con i piedi a terra. Segui il lampo che colpisce la cima, poi le pietre che cadono nell\'aria. Ripeti cinque volte: «Ciò che è vero resta in piedi». Ascolta il silenzio che viene dopo l\'ultima ripetizione, senza riempirlo.',
    'contemplazione_dei_tarocchi|La Torre|rovesciata': 'Tieni lo schermo davanti agli occhi e concediti sei respiri, uno per ogni pensiero che lasci cadere. Guarda la costruzione ancora in piedi sotto il fulmine. Ripeti tre volte, sottovoce: «Lascio cadere ciò che regge soltanto in apparenza». Poi respira ancora, adagio, guardando la base.',
    'contemplazione_dei_tarocchi|Nove di Bastoni|dritta': 'Raccogli le forze a ogni entrata, per sei respiri, con gli occhi sulla carta. Osserva i nove bastoni allineati come una palizzata che regge ancora. Ripeti tre volte, con voce salda: «Manca l\'ultimo tratto, lo percorro». Poi lascia riposare le mani, aperte sulle ginocchia.',
    'contemplazione_dei_tarocchi|Nove di Bastoni|rovesciata': 'Lascia che quattro respiri lenti ti portino davanti alla carta. Cerca fra i nove bastoni uno spiraglio da cui passa la luce. Ripeti cinque volte, piano: «Abbasso lo scudo per chi vuole avvicinarsi». A ogni ripetizione allarga un poco le spalle, come una porta che si socchiude.',
    'contemplazione_dei_tarocchi|Nove di Coppe|dritta': 'Volgi gli occhi alla figura dipinta e lascia andare quattro respiri contenti. Guarda le nove coppe disposte in ordine, come sopra una mensola in festa. Ripeti tre volte, con gratitudine: «Mi concedo di godere ciò che ho ottenuto». Poi lascia distendere il volto in un sorriso.',
    'contemplazione_dei_tarocchi|Nove di Coppe|rovesciata': 'Respira sette volte con gli occhi sulla carta, lasciando scendere l\'aria fino in fondo. Conta le coppe e chiediti quali sono piene davvero. Ripeti cinque volte: «Cerco la gioia che tocca il profondo». Lascia che la domanda resti aperta anche dopo l\'ultima volta.',
    'contemplazione_dei_tarocchi|Nove di Denari|dritta': 'Accogli la figura dentro lo sguardo per sette respiri ampi, come in un giardino. Guarda i nove dischi raccolti fra i tralci, frutti del tuo lavoro. Ripeti tre volte, con gioia quieta: «Abito con piacere lo spazio che ho costruito». Poi lascia lo sguardo disteso sulla figura.',
    'contemplazione_dei_tarocchi|Nove di Denari|rovesciata': 'Per cinque respiri guarda lo schermo, con una mano posata sul petto. Osserva i dischi, poi distogli lo sguardo e portalo dentro di te. Ripeti sette volte: «Valgo più di ciò che possiedo». Lascia che la frase resti con te mentre respiri ancora, adagio.',
    'contemplazione_dei_tarocchi|Nove di Spade|dritta': 'Se è buio accendi una luce e guarda la carta per sette respiri lunghi. Osserva le nove spade una sopra l\'altra, sul fondo scuro. Ripeti tre volte, piano: «Alla luce del giorno guardo i miei pensieri». Poi lascia uscire un respiro più lungo degli altri.',
    'contemplazione_dei_tarocchi|Nove di Spade|rovesciata': 'Respira quattro volte davanti allo schermo, lasciando che il petto si allenti. Guarda le spade e immagina di raccontarne una a voce, a qualcuno di caro. Ripeti cinque volte: «Ciò che dico a voce pesa meno». Poi pensa a chi potresti chiamare, anche soltanto per parlare.',
    'contemplazione_dei_tarocchi|Otto di Bastoni|dritta': 'Tieni lo schermo davanti e lascia passare cinque respiri svelti e puliti. Segui gli otto bastoni che volano paralleli nella stessa direzione. Ripeti sette volte, con ritmo: «Mi muovo con ciò che accelera». Poi rallenta il respiro fino a quietarlo, come una freccia che arriva.',
    'contemplazione_dei_tarocchi|Otto di Bastoni|rovesciata': 'Respira sette volte con gli occhi sulla carta, ciascuna più lunga della precedente. Guarda i bastoni in volo e immagina di metterli in fila, uno alla volta. Ripeti cinque volte: «Rallento quanto basta per ritrovare l\'ordine». Poi riprendi con calma ciò che stavi facendo.',
    'contemplazione_dei_tarocchi|Otto di Coppe|dritta': 'Concediti sei respiri silenziosi davanti alla carta. Guarda le otto coppe in fila e lo spazio che resta sopra di loro, come una strada che sale. Ripeti tre volte, sussurrando: «Lascio ciò che non mi nutre più». Poi resta in silenzio ancora un poco, guardando quella strada.',
    'contemplazione_dei_tarocchi|Otto di Coppe|rovesciata': 'Guarda lo schermo per cinque respiri, ascoltando dove il respiro vuole andare. Osserva la fila delle coppe e il vuoto che la interrompe: è la soglia fra restare e partire. Ripeti sette volte: «Mi ascolto con sincerità prima di scegliere». Poi lascia la soglia aperta.',
    'contemplazione_dei_tarocchi|Otto di Denari|dritta': 'Concediti sei respiri attenti davanti alla carta, uno per ogni dettaglio. Segui gli otto dischi uno dopo l\'altro, come opere finite su un banco di lavoro. Ripeti cinque volte: «Affino con cura, un dettaglio alla volta». Poi guarda le tue mani, con rispetto.',
    'contemplazione_dei_tarocchi|Otto di Denari|rovesciata': 'Respira quattro volte con gli occhi sulla carta, lasciando cadere l\'abitudine. Guarda i dischi in fila e chiediti quale hai fatto con amore. Ripeti tre volte: «Ritrovo il senso di ciò che faccio». Poi resta un respiro in più sulla domanda, prima di tornare al lavoro.',
    'contemplazione_dei_tarocchi|Otto di Spade|dritta': 'Con respiri lenti e larghi, cinque in tutto, resta davanti alla carta. Guarda le otto spade intorno alla figura e lo spazio che lasciano aperto. Ripeti sette volte: «Le corde sono più larghe di quanto credo». Poi muovi le braccia, piano, nello spazio intorno.',
    'contemplazione_dei_tarocchi|Otto di Spade|rovesciata': 'Per sei respiri guarda la carta, aprendo un poco di più il petto a ogni entrata. Cerca il varco fra le spade, quello da cui si passa. Ripeti cinque volte: «Riconosco la mia forza e faccio un passo fuori». Poi lascia lo sguardo oltre il varco.',
    'contemplazione_dei_tarocchi|Quattro di Bastoni|dritta': 'Concediti quattro respiri gioiosi davanti alla carta, con le spalle aperte. Guarda i quattro bastoni, uno per ogni lato di una casa che regge. Ripeti tre volte, con un sorriso nella voce: «Riconosco il bello che ho costruito». Lascia che la gioia resti un momento, senza correre oltre.',
    'contemplazione_dei_tarocchi|Quattro di Bastoni|rovesciata': 'Respira cinque volte guardando lo schermo, sentendo il peso posarsi sul sedile. Segui ogni bastone fino alla base, là dove tocca terra. Ripeti cinque volte: «Curo le fondamenta prima di festeggiare». Ogni volta lascia che la voce scenda un poco più in basso, verso le radici.',
    'contemplazione_dei_tarocchi|Quattro di Coppe|dritta': 'Tieni la carta davanti agli occhi per quattro respiri, poi solleva piano lo sguardo. Guarda le quattro coppe e cerca quella che prima non avevi notato. Ripeti cinque volte: «Alzo lo sguardo verso ciò che mi viene offerto». Poi lascia gli occhi aperti su ciò che hai intorno.',
    'contemplazione_dei_tarocchi|Quattro di Coppe|rovesciata': 'Respira sette volte con gli occhi sullo schermo, lasciando che lo sguardo si ridesti. Segui le coppe da sinistra a destra, come chi si accorge di qualcosa per la prima volta. Ripeti tre volte: «Seguo la curiosità che si risveglia». Poi lascia che lo sguardo si apra.',
    'contemplazione_dei_tarocchi|Quattro di Denari|dritta': 'Concediti cinque respiri solidi davanti alla carta, con le mani in grembo. Guarda i quattro dischi saldi ai quattro angoli, come le mura di una casa. Ripeti sette volte: «Proteggo ciò che ho e lascio la mano aperta». Poi apri le dita, una per una.',
    'contemplazione_dei_tarocchi|Quattro di Denari|rovesciata': 'Per quattro respiri guarda la carta, stringendo piano i pugni e poi lasciandoli andare. Osserva i dischi e immagina di allentare la presa su uno di loro. Ripeti tre volte, sottovoce: «Allento la presa e lascio scorrere». Lascia le mani aperte sulle ginocchia.',
    'contemplazione_dei_tarocchi|Quattro di Spade|dritta': 'Abbassa le palpebre a metà e guarda la carta per nove respiri lentissimi. Osserva le quattro spade posate, senza nessuna mano a stringerle. Ripeti tre volte, quasi in silenzio: «Mi fermo e lascio tornare le forze». Poi resta immobile ancora un poco.',
    'contemplazione_dei_tarocchi|Quattro di Spade|rovesciata': 'Guarda la carta per quattro respiri, ognuno un poco più vivo. Fermati sulle quattro spade e immagina la prima che si alza dal suo riposo. Ripeti cinque volte: «Torno all\'azione con passo calmo». Poi muovi piano le spalle e il collo, come al risveglio.',
    'contemplazione_dei_tarocchi|Re di Bastoni|dritta': 'Apri lo sguardo sulla figura dipinta e lascia salire cinque respiri profondi. Guarda il re che stringe il bastone e volge lo sguardo lontano, oltre il bordo. Ripeti sette volte, con voce piena di calore: «Guido con l\'esempio, con generosità». Poi resta un istante in quel silenzio.',
    'contemplazione_dei_tarocchi|Re di Bastoni|rovesciata': 'Respira sei volte davanti alla carta, lasciando parlare prima l\'uscita del fiato. Osserva il re seduto: anche chi guida si siede, a volte, per ascoltare. Ripeti cinque volte: «Ascolto prima di spingere». Lascia che la frase ammorbidisca il passo che stavi per fare.',
    'contemplazione_dei_tarocchi|Re di Coppe|dritta': 'Tieni la carta davanti agli occhi e respira cinque volte, profondo come il mare. Guarda il re che tiene la coppa con mano calma, mentre tutto intorno si muove. Ripeti sette volte: «Guido le mie emozioni con calma profonda». Poi lascia il respiro tornare al suo passo.',
    'contemplazione_dei_tarocchi|Re di Coppe|rovesciata': 'Respira sei volte davanti alla carta, lasciando che l\'onda del fiato salga e scenda. Osserva la coppa nella mano del re, tenuta senza stringere. Ripeti cinque volte, a voce chiara: «Do voce a ciò che sento». Lascia che la voce trovi il suo volume, né troppo né poco.',
    'contemplazione_dei_tarocchi|Re di Denari|dritta': 'Con lo schermo davanti agli occhi, concediti sei respiri larghi. Guarda il re che tiene il disco con mano aperta, seduto fra ciò che ha fatto crescere. Ripeti sette volte: «Condivido con misura ciò che ho costruito». Poi lascia il respiro tornare lento.',
    'contemplazione_dei_tarocchi|Re di Denari|rovesciata': 'Per sette respiri resta sulla carta, sciogliendo la mascella a ogni uscita. Guarda la mano del re sul disco e immagina che si apra. Ripeti tre volte: «Ciò che possiedo non mi possiede». Poi apri le tue mani e lasciale aperte per un respiro intero.',
    'contemplazione_dei_tarocchi|Re di Spade|dritta': 'Tieni la carta davanti agli occhi per cinque respiri pieni e misurati. Guarda il re seduto con la spada in mano, lo sguardo dritto verso di te. Ripeti sette volte: «Metto la ragione al servizio del cuore». Poi lascia riposare la mente, come una lama nel fodero.',
    'contemplazione_dei_tarocchi|Re di Spade|rovesciata': 'Respira sei volte con gli occhi sulla carta, sentendo il respiro arrivare fino al petto. Osserva il volto del re e cerca, dietro la fermezza, un segno di calore. Ripeti tre volte: «Unisco alla logica la compassione». Poi lascia la mano aperta sul cuore.',
    'contemplazione_dei_tarocchi|Regina di Bastoni|dritta': 'Solleva appena il mento e guarda la figura per sei respiri caldi. Osserva la regina sul trono col bastone fiorito in mano, presente senza sforzo. Ripeti sette volte: «Brillo così come sono, senza togliere spazio a nessuno». Poi lascia che il calore resti nel petto.',
    'contemplazione_dei_tarocchi|Regina di Bastoni|rovesciata': 'Per quattro respiri resta sulla carta, portando l\'attenzione al centro del petto. Guarda il bastone che la regina tiene vicino a sé, diritto e saldo. Ripeti tre volte: «La mia fiamma non ha rivali da temere». Respira ancora, finché senti di nuovo il tuo centro.',
    'contemplazione_dei_tarocchi|Regina di Coppe|dritta': 'Lascia che la carta ti stia davanti per sei respiri profondi e quieti. Guarda la regina che fissa la coppa chiusa fra le mani, raccolta in ascolto. Ripeti sette volte, con voce tenera: «Accolgo gli altri e accolgo anche me». Poi lascia la mano sul cuore.',
    'contemplazione_dei_tarocchi|Regina di Coppe|rovesciata': 'Per quattro respiri guarda lo schermo, sentendo dove finisci tu e dove comincia l\'aria intorno. Osserva il bordo della coppa che la regina tiene: separa e contiene. Ripeti tre volte: «Posso amare senza annegare». Poi riporta l\'attenzione al tuo respiro, soltanto al tuo.',
    'contemplazione_dei_tarocchi|Regina di Denari|dritta': 'Lascia che la carta ti stia davanti per cinque respiri caldi e pieni. Guarda la regina che tiene il disco in grembo, con tutte e due le mani. Ripeti tre volte: «Unisco il cuore e la concretezza». Poi lascia le mani in grembo come le sue, raccolte.',
    'contemplazione_dei_tarocchi|Regina di Denari|rovesciata': 'Respira quattro volte guardando la carta, ricevendo l\'aria come un dono. Osserva il disco nel grembo della regina e immagina che sia per te. Ripeti cinque volte: «Annaffio anche il mio giardino». Poi lascia che la frase ti ricordi di te, in mezzo a tutto il resto.',
    'contemplazione_dei_tarocchi|Regina di Spade|dritta': 'Lascia che la carta ti stia davanti per sei respiri limpidi e regolari. Guarda la regina con la spada diritta e la mano tesa in avanti. Ripeti tre volte, con voce netta: «Penso con chiarezza e dico ciò che è». Poi lascia lo sguardo nitido sulla carta.',
    'contemplazione_dei_tarocchi|Regina di Spade|rovesciata': 'Per quattro respiri guarda lo schermo, ammorbidendo il viso a ogni uscita. Fermati sulla lama della regina: è rivolta verso l\'alto, non contro chi la porta. Ripeti cinque volte: «Ammorbidisco il giudizio, a partire da me». Poi lascia distendere la fronte.',
    'contemplazione_dei_tarocchi|Sei di Bastoni|dritta': 'Avvicina lo schermo al viso e lascia salire cinque respiri ampi. Guarda i sei bastoni levati insieme, come in un corteo che attraversa la piazza. Ripeti tre volte: «Accolgo il riconoscimento con misura». Poi respira ancora, con la testa alta e lo sguardo morbido.',
    'contemplazione_dei_tarocchi|Sei di Bastoni|rovesciata': 'Per sette respiri resta davanti allo schermo, in silenzio. Guarda i bastoni levati e chiediti chi li regge quando nessuno applaude. Ripeti cinque volte: «Il mio valore resta anche senza applauso». Lascia che l\'ultima ripetizione sia la più piana, quasi detta a un amico.',
    'contemplazione_dei_tarocchi|Sei di Coppe|dritta': 'Con la figura davanti, lascia scorrere quattro respiri dolci. Guarda le sei coppe come un piccolo giardino di ricordi, una accanto all\'altra. Ripeti sette volte: «Lascio che la tenerezza del passato mi nutra». Poi torna con lo sguardo al presente, alla stanza dove sei.',
    'contemplazione_dei_tarocchi|Sei di Coppe|rovesciata': 'Respira sei volte con la carta davanti agli occhi, sentendo i piedi qui e adesso. Guarda le coppe e scegline una da lasciare al passato. Ripeti cinque volte, con dolcezza: «Onoro ciò che è stato e torno a oggi». Poi muovi piano le dita, come per salutare.',
    'contemplazione_dei_tarocchi|Sei di Denari|dritta': 'Tieni la carta davanti agli occhi e lascia scorrere cinque respiri uguali, uno per dare e uno per ricevere. Guarda i sei dischi e cerca il loro equilibrio, metà da una parte e metà dall\'altra. Ripeti sette volte: «Do e ricevo nella giusta misura».',
    'contemplazione_dei_tarocchi|Sei di Denari|rovesciata': 'Per sei respiri resta con gli occhi sulla carta, contando l\'entrata e l\'uscita. Guarda i dischi e chiediti da che parte pende lo scambio. Ripeti cinque volte: «Verifico che il dare torni in entrambe le direzioni». Poi lascia riposare la domanda, senza forzare la risposta.',
    'contemplazione_dei_tarocchi|Sei di Spade|dritta': 'Lascia scorrere sette respiri regolari, come remi nell\'acqua, davanti alla carta. Guarda le sei spade allineate come i remi di una barca. Ripeti cinque volte: «Vado un passo alla volta verso la riva quieta». Poi resta un respiro sull\'acqua, a guardare avanti.',
    'contemplazione_dei_tarocchi|Sei di Spade|rovesciata': 'Per quattro respiri guarda la carta, sentendo il peso di ciò che porti con te. Osserva le spade come un bagaglio che si può portare anche così, un poco pesante. Ripeti tre volte: «Parto anche col cuore un po\' indietro». Lascia che la frase ti accompagni.',
    'contemplazione_dei_tarocchi|Sette di Bastoni|dritta': 'Guarda la carta per quattro respiri decisi, con i piedi ben piantati. Osserva il bastone che sta più in alto, mentre gli altri salgono a incontrarlo. Ripeti sette volte, con voce ferma: «Tengo il punto su ciò in cui credo». Poi espira a lungo, lasciando la guardia.',
    'contemplazione_dei_tarocchi|Sette di Bastoni|rovesciata': 'Concediti sei respiri davanti alla carta, abbassando le spalle a ogni uscita. Conta i bastoni uno per uno e chiediti quali vale la pena fronteggiare. Ripeti tre volte: «Non devo difendere ogni collina». Lascia che la frase sciolga la guardia, una ripetizione dopo l\'altra.',
    'contemplazione_dei_tarocchi|Sette di Coppe|dritta': 'Guarda la carta per sette respiri, lasciando che l\'immaginazione si muova come vuole. Osserva le sette coppe una per una, come porte diverse. Ripeti tre volte: «Sogno in grande, poi scelgo con i piedi a terra». Infine posa bene i piedi sul pavimento.',
    'contemplazione_dei_tarocchi|Sette di Coppe|rovesciata': 'Per quattro respiri resta sullo schermo, lasciando che la vista si schiarisca. Fra le sette coppe fermati su una soltanto e tienila nello sguardo. Ripeti cinque volte: «Metto a fuoco ciò che desidero davvero». Lascia sfumare le altre al bordo degli occhi, senza rimpianto.',
    'contemplazione_dei_tarocchi|Sette di Denari|dritta': 'Lascia che la carta ti stia davanti per nove respiri lenti, come stagioni che passano. Osserva i sette dischi fra le foglie, come frutti ancora sul ramo. Ripeti tre volte: «Aspetto il tempo giusto del raccolto». Poi lascia andare la fretta con l\'ultimo respiro.',
    'contemplazione_dei_tarocchi|Sette di Denari|rovesciata': 'Guarda lo schermo per cinque respiri, senza chiedere niente al tempo. Fermati su un disco per volta e chiediti dove metti la tua energia. Ripeti sette volte: «Rivedo con calma dove semino». Poi lascia ricadere le mani, come chi ha finito di zappare.',
    'contemplazione_dei_tarocchi|Sette di Spade|dritta': 'Fissa la figura dipinta sullo schermo e respira sei volte, in silenzio, come chi pensa. Osserva le sette spade e la loro disposizione, come una mossa studiata. Ripeti cinque volte: «Uso l\'ingegno e resto nella verità». Poi lascia che la mente torni chiara.',
    'contemplazione_dei_tarocchi|Sette di Spade|rovesciata': 'Lascia uscire tutta l\'aria, fino in fondo, per sette respiri davanti allo schermo. Fermati su una spada e immagina di posarla alla luce. Ripeti tre volte: «Torno alla trasparenza, libero la coscienza». Poi respira con più leggerezza, sentendo il petto alleggerirsi.',
    'contemplazione_dei_tarocchi|Tre di Bastoni|dritta': 'Tieni lo schermo davanti a te e lascia andare sei respiri, lunghi come onde. Guarda i tre bastoni piantati a terra, saldi come alberi di una nave. Ripeti tre volte, con fiducia: «Ciò che ho avviato è in viaggio». Poi lascia lo sguardo all\'orizzonte della figura.',
    'contemplazione_dei_tarocchi|Tre di Bastoni|rovesciata': 'Per cinque respiri guarda la carta, lasciando che ogni uscita duri un poco di più. Fermati sul bastone che sta nel mezzo, quello che regge gli altri due. Ripeti sette volte: «Un ritardo è un tempo diverso, non un no». Poi decidi se aspettare o correggere la rotta.',
    'contemplazione_dei_tarocchi|Tre di Coppe|dritta': 'Concediti cinque respiri allegri con la carta davanti agli occhi. Guarda le tre coppe sollevate insieme, come in un brindisi fra amici. Ripeti sette volte, con voce lieta: «Festeggio con chi mi vuole bene». Poi pensa a un volto caro e sorridigli, anche da lontano.',
    'contemplazione_dei_tarocchi|Tre di Coppe|rovesciata': 'Guarda lo schermo per sei respiri, lasciando quietare il brusio intorno. Fermati su una coppa delle tre, quella che senti più vicina. Ripeti tre volte: «Scelgo i legami sinceri che mi nutrono». Lascia sfumare il resto nel respiro, come voci di una festa che si allontana.',
    'contemplazione_dei_tarocchi|Tre di Denari|dritta': 'Concentra lo sguardo sulla figura per sei respiri regolari, come colpi di scalpello. Osserva i tre dischi disposti come le pietre di un arco ben costruito. Ripeti tre volte: «Costruisco insieme agli altri, con cura». Poi pensa a chi lavora accanto a te, ogni giorno.',
    'contemplazione_dei_tarocchi|Tre di Denari|rovesciata': 'Per sette respiri resta sullo schermo, lasciando che si accordino fra loro. Fermati sullo spazio fra un disco e l\'altro: ognuno ha il suo posto. Ripeti cinque volte: «Chiarisco i compiti e l\'opera riparte». Lascia che la frase metta ordine, una ripetizione alla volta.',
    'contemplazione_dei_tarocchi|Tre di Spade|dritta': 'Anche se pesano, concediti sei respiri lenti con la carta davanti agli occhi. Guarda le tre spade dipinte, senza distogliere gli occhi. Ripeti tre volte, a voce bassa: «Lascio scorrere il dolore perché passi». Poi lascia uscire un sospiro, lungo quanto serve.',
    'contemplazione_dei_tarocchi|Tre di Spade|rovesciata': 'Per cinque respiri guarda lo schermo, lasciando l\'aria più a lungo nel petto. Segui le tre spade e cerca lo spazio fra una lama e l\'altra. Ripeti sette volte: «Il cuore torna a respirare». Poi lascia la mano sul petto un momento, a sentire il ritmo.',
    'galdr_delle_rune|Algiz|dritta': 'Alza le braccia aperte verso l\'alto, come i rami della runa: tienile così per un respiro. Canta sottovoce «Algiz, algiz, algiz» per tre giri, poi abbassa le braccia lentamente. Il pensiero va allo scudo del sacro, al riparo che c\'è e al legame con l\'alto.',
    'galdr_delle_rune|Algiz|in ombra': 'Porta le mani accanto alle orecchie senza coprirle, come per ascoltare meglio. Sussurra «Algiz, algiz, algiz» tre volte, sentendo il suono vicino a te nella stanza silenziosa. Il canto sostiene l\'attenzione verso una difesa allentata o un istinto ignorato, da riascoltare con calma, senza fretta.',
    'galdr_delle_rune|Ansuz|dritta': 'Siedi in un luogo silenzioso, porta due dita alle labbra e poi abbassale piano. Canta a voce bassa «Ansuz, ansuz, ansuz» per tre giri, ascoltando come il suono vibra nella bocca. Rivolgi il pensiero al soffio della parola, al messaggio che arriva e chiede ascolto.',
    'galdr_delle_rune|Ansuz|in ombra': 'Spegni ciò che fa rumore intorno a te e chiudi gli occhi per qualche respiro. Mormora «Ansuz, ansuz, ansuz» tre volte, sempre più piano, fino a sentirne solo il fiato. Lascia che il canto accompagni l\'attenzione a una parola fraintesa, da ascoltare meglio prima di darle peso.',
    'galdr_delle_rune|Berkano|dritta': 'Posa le mani sul ventre, una sopra l\'altra: senti il respiro sotto i palmi. Poi intona a voce bassa «Berkano, berkano, berkano» tre volte, dolcemente. Tieni il pensiero sulla betulla che genera, su ciò che di nuovo germoglia e chiede la tua cura paziente.',
    'galdr_delle_rune|Berkano|in ombra': 'Tocca la terra di un vaso o il pavimento con la punta delle dita. Sussurra «Berkano, berkano, berkano» tre volte, lentamente, come se parlassi a una radice. Il canto accompagna l\'attenzione a un germoglio che stenta e a una cura da riprendere con costanza, giorno per giorno.',
    'galdr_delle_rune|Dagaz|dritta': 'Al mattino o in un momento di luce, apri le braccia lentamente come un\'alba che si allarga. Dagli voce piano, «Dagaz, dagaz, dagaz», per tre volte, allargando il respiro a ogni ripetizione. Rivolgi il pensiero alla svolta luminosa, al nuovo giorno che risveglia.',
    'galdr_delle_rune|Ehwaz|dritta': 'Pensa a una persona di cui ti fidi e immagina di camminare al suo fianco. Pronuncia sottovoce «Ehwaz, ehwaz, ehwaz» in tre giri, accordando il respiro a un passo immaginato in due. Rivolgi il pensiero ai due cavalli, alla fiducia che porta lontano in armonia.',
    'galdr_delle_rune|Ehwaz|in ombra': 'Batti piano un ritmo regolare con la mano sul tavolo, sempre uguale. Mormora «Ehwaz, ehwaz, ehwaz» tre volte, seguendo quel battito senza anticiparlo. Con il canto guarda un\'alleanza che ha perso il passo, per ritrovare il ritmo comune prima di riprendere la corsa.',
    'galdr_delle_rune|Eihwaz|dritta': 'Appoggia la schiena a un muro o a un albero e senti che ti sostiene. Canta piano «Eihwaz, eihwaz, eihwaz» per tre giri, con la voce che sale dal petto e poi ridiscende. Tieni il pensiero sull\'asse tra i mondi, sul tasso che regge le tempeste senza spezzarsi.',
    'galdr_delle_rune|Fehu|dritta': 'Siedi vicino a una finestra aperta, con le mani sulle ginocchia e i palmi rivolti verso l\'alto. Canta a voce bassa «Fehu, fehu, fehu» per tre respiri lenti, lasciando uscire l\'aria piano. Pensa a ciò che hai e che può circolare, come un bene che scorre e porta frutto.',
    'galdr_delle_rune|Fehu|in ombra': 'Prendi in mano un piccolo oggetto a cui tieni e stringilo nel pugno. Mormora «Fehu, fehu, fehu» tre volte, poi apri lentamente le dita mentre espiri. Lascia che il canto accompagni lo sguardo su ciò che trattieni troppo, quello che chiede di tornare a muoversi.',
    'galdr_delle_rune|Gebo|dritta': 'Porta le mani davanti al petto e incrociale ai polsi, come il segno della runa. Canta piano «Gebo, gebo, gebo» per tre giri, inspirando a fondo e restituendo l\'aria lentamente. Rivolgi il pensiero al dono e al patto, all\'equilibrio fra ciò che dai e ciò che ricevi.',
    'galdr_delle_rune|Hagalaz|dritta': 'Apri una finestra e ascolta per un momento i suoni di fuori, il vento o la pioggia. Intona a voce bassa «Hagalaz, hagalaz, hagalaz», tre volte di seguito, lasciando scendere il respiro fino al ventre. Il pensiero va alla grandine che scuote: ciò che crolla lascia spazio al nuovo.',
    'galdr_delle_rune|Ingwaz|dritta': 'Chiudi le mani una dentro l\'altra, come per custodire un seme. Canta sottovoce «Ingwaz, ingwaz, ingwaz» per tre volte, a voce bassissima, quasi solo dentro di te. Tieni il pensiero sul seme in attesa, sul lavoro interiore che si compie prima di mostrarsi.',
    'galdr_delle_rune|Isa|dritta': 'Resta immobile per qualche respiro, le mani aperte sulle cosce e lo sguardo basso. Lascia uscire piano «Isa, isa, isa» tre volte, tenendo il suono lungo e uniforme, quasi una nota sola. Il pensiero va al ghiaccio che ferma: tempo di attesa e di chiarezza.',
    'galdr_delle_rune|Jera|dritta': 'Disegna con un dito un cerchio sul tavolo o sul palmo. Canta sottovoce «Jera, jera, jera» per tre volte, un giro di canto per ogni giro del dito. Rivolgi il pensiero al raccolto del tempo, a ciò che hai seminato con pazienza e matura a suo tempo.',
    'galdr_delle_rune|Kenaz|dritta': 'Accendi una candela, se puoi, oppure guarda una luce accesa nella stanza. Canta con voce bassa «Kenaz, kenaz, kenaz» per tre volte, a ogni giro tenendo lo sguardo sulla fiamma. Pensa alla torcia che rivela, alla luce che si accende dove prima era buio.',
    'galdr_delle_rune|Kenaz|in ombra': 'Siedi in penombra e copri gli occhi con il palmo delle mani per un momento. Sussurra «Kenaz, kenaz, kenaz» tre volte, poi scopri gli occhi con calma. Il canto accompagna lo sguardo su un\'idea ancora al buio: la fiamma c\'è, ha solo bisogno di tempo per prendere.',
    'galdr_delle_rune|Laguz|dritta': 'Versa dell\'acqua in un bicchiere e guardala finché la superficie torna quieta. Canta piano «Laguz, laguz, laguz» per tre giri, con una voce fluida, senza spezzare il suono. Il pensiero va all\'acqua che intuisce, alla corrente e a ciò che senti sotto la superficie.',
    'galdr_delle_rune|Laguz|in ombra': 'Agita appena un bicchiere d\'acqua e posalo sul tavolo davanti a te. Mormora «Laguz, laguz, laguz» tre volte, mentre l\'acqua si posa. Con il canto guarda un\'emozione confusa e un intuito da schiarire: lascia posare la corrente finché il fondo si vede.',
    'galdr_delle_rune|Mannaz|dritta': 'Guardati in uno specchio, oppure osserva le tue mani aperte davanti agli occhi. Sostenendo lo sguardo, ripeti a voce bassa «Mannaz, mannaz, mannaz» in tre giri lenti. Pensa all\'essere umano in mezzo agli altri, al sé e alla comunità: ti conosci meglio attraverso chi ti sta accanto.',
    'galdr_delle_rune|Mannaz|in ombra': 'Appanna con il fiato uno specchio o un vetro e osserva l\'alone che svanisce piano. Sussurra «Mannaz, mannaz, mannaz» tre volte, appannando di nuovo il vetro prima di ogni giro. Mentre canti, considera con pazienza una distanza dagli altri o un giudizio severo verso di te.',
    'galdr_delle_rune|Nauthiz|dritta': 'Strofina lentamente i palmi delle mani finché senti il calore dell\'attrito. Canta piano «Nauthiz, nauthiz, nauthiz» per tre volte, senza fretta, lasciando che ogni giro finisca prima del successivo. Pensa al bisogno che insegna, all\'attrito che accende il fuoco: qui la pazienza diventa forza.',
    'galdr_delle_rune|Nauthiz|in ombra': 'Siedi e intreccia le dita in grembo, senza stringerle troppo forte. Sussurra «Nauthiz, nauthiz, nauthiz» tre volte, allungando a poco a poco l\'espirazione a ogni ripetizione. Lascia che il canto accompagni l\'attenzione al vincolo che pesa e all\'impazienza davanti alla prova, dove la chiave resta la pazienza.',
    'galdr_delle_rune|Othala|dritta': 'Tieni in mano un oggetto che viene dalla tua famiglia o dalla tua storia. Canta piano «Othala, othala, othala» per tre volte, con una voce raccolta e grave. Pensa all\'eredità e alla casa, alle radici e al valore che viene da lontano e ti sostiene.',
    'galdr_delle_rune|Othala|in ombra': 'Tieni davanti a te un ricordo di casa e respira lentamente per qualche istante. Sussurra «Othala, othala, othala» tre volte, poi posa il ricordo con delicatezza. Il canto accompagna l\'attenzione a un legame col passato: tieni ciò che sostiene e lascia ciò che trattiene.',
    'galdr_delle_rune|Perthro|dritta': 'Unisci le mani a coppa davanti a te, come per raccogliere qualcosa. Mentre guardi dentro le mani vuote, canta piano «Perthro, perthro, perthro» per tre volte. Pensa al mistero della coppa, alla sorte ancora nascosta, a ciò che si muove sotto e non è ancora visibile.',
    'galdr_delle_rune|Perthro|in ombra': 'Rovescia le mani a coppa, con i palmi verso il basso e lasciale ricadere sulle ginocchia. Mormora «Perthro, perthro, perthro» tre volte, senza cercare un ritmo preciso. Con il canto guarda il mistero che resiste e non si svela: non forzare la sorte, lasciala maturare.',
    'galdr_delle_rune|Raidho|dritta': 'Cammina lentamente nella stanza o lungo un corridoio, un passo per ogni sillaba. Canta sottovoce «Raidho, raidho, raidho» per tre giri, accordando il passo al respiro. Il pensiero va al cammino giusto e alla cadenza che ti è propria, dentro e fuori di te.',
    'galdr_delle_rune|Raidho|in ombra': 'Fermati dove sei e senti il peso che passa da un piede all\'altro. Poi canta piano «Raidho, raidho, raidho» tre volte, più lentamente di quanto ti verrebbe spontaneo. Con il canto guarda il ritmo che si è perso a scatti, per ritrovare la tua cadenza e la strada piana.',
    'galdr_delle_rune|Sowilo|dritta': 'Volgi il viso verso la luce del giorno o verso la finestra più luminosa. Canta a voce bassa «Sowilo, sowilo, sowilo» per tre volte, con un respiro ampio che apre il petto. Rivolgi il pensiero al sole che guida, alla volontà che tiene la rotta che hai scelto.',
    'galdr_delle_rune|Thurisaz|dritta': 'Siedi con la schiena dritta e posa una mano sul petto, l\'altra sul ginocchio. Canta con voce bassa e ferma «Thurisaz, thurisaz, thurisaz» per tre volte, ogni volta su un\'unica espirazione. Tieni il pensiero sulla spina che difende: una forza aspra da dirigere con misura.',
    'galdr_delle_rune|Thurisaz|in ombra': 'Prima di cantare fermati un istante e lascia scendere le spalle. Poi sussurra «Thurisaz, thurisaz, thurisaz» tre volte, con una pausa lunga tra un giro e l\'altro. Con il canto guarda la reazione impulsiva che finisce per pungere te e lascia che la fretta si sciolga.',
    'galdr_delle_rune|Tiwaz|dritta': 'Stai in piedi con la schiena eretta e il braccio destro teso in avanti, come una lancia. Canta piano «Tiwaz, tiwaz, tiwaz» per tre giri, con voce bassa e decisa. Il pensiero va alla lancia della giustizia, al coraggio che cerca l\'esito meritato e non quello strappato.',
    'galdr_delle_rune|Tiwaz|in ombra': 'Fissa un punto lontano davanti a te e tienilo con lo sguardo per qualche respiro. Mormora «Tiwaz, tiwaz, tiwaz» tre volte, riportando gli occhi su quel punto a ogni ripetizione. Con il canto guarda un coraggio incerto, per ritrovare il tuo giusto finché la mira torna ferma.',
    'galdr_delle_rune|Uruz|dritta': 'Alzati in piedi con i piedi ben piantati a terra, alla larghezza delle spalle. Inspira dal ventre e canta piano «Uruz, uruz, uruz», sentendo la voce partire dal basso. Ripeti per tre giri, con il pensiero rivolto alla forza grezza che ti rimette in piedi.',
    'galdr_delle_rune|Uruz|in ombra': 'Resta in piedi senza muoverti e conta quattro respiri prima di cominciare. Poi canta sottovoce «Uruz, uruz, uruz» tre volte, con un ritmo lento e regolare. Il canto ti aiuta a guardare dove la tua forza si è spesa di slancio e a ritrovare la cadenza giusta.',
    'galdr_delle_rune|Wunjo|dritta': 'Siedi in un posto che ti è caro e lascia che il volto si distenda. Canta sottovoce «Wunjo, wunjo, wunjo» per tre volte, con un tono morbido e quasi cullato. Tieni il pensiero sulla gioia che corona uno sforzo, su un momento di pienezza vera da accogliere.',
    'galdr_delle_rune|Wunjo|in ombra': 'Pensa a una persona con cui il legame si è incrinato e tieni a mente il suo nome. Mormora «Wunjo, wunjo, wunjo» tre volte, lasciando tra un giro e l\'altro un respiro intero. Con il canto guarda il legame che chiede cura, perché l\'armonia possa ricomporsi.',
    'gesti_tong_shu|Bi|Amore|anno': 'Chiudere con dolcezza è il gesto che Bi, sotto cui è nato a Capodanno il tuo anno cinese, chiede agli affetti. Porta adesso a compimento una questione sospesa, una scusa o un chiarimento, con chi ami o con chi ha contato per te, senza riaprire ferite.',
    'gesti_tong_shu|Bi|Amore|giorno': 'Oggi governa Bi, il giorno che chiude, poco adatto alle promesse nuove secondo l\'almanacco. In amore custodisci invece di cercare: se hai un legame, passa la sera con chi ami, telefoni spenti e porta chiusa; se sei senza legame, concediti una sera quieta, senza rincorrere nessuno.',
    'gesti_tong_shu|Bi|Amore|mese': 'Con Bi, che chiude, partono oggi trenta giorni per proteggere ciò che conta negli affetti. Ogni settimana riserva una sera senza telefoni né impegni a chi ami o, se sei senza legame, a te e alle amicizie più fedeli. Fissa adesso la prima.',
    'gesti_tong_shu|Bi|Amore|settimana': 'Bi, l\'ufficiale che sigilla, dà oggi agli affetti una settimana per chiudere con dolcezza una questione in sospeso. Un chiarimento promesso, una scusa mai detta, con chi ami, in famiglia o con chi frequenti: fallo adesso, così i sette giorni ripartono leggeri.',
    'gesti_tong_shu|Bi|Carriera|anno': 'Arginare è il gesto di Bi, sotto cui il tuo anno cinese è nato a Capodanno. Nel lavoro chiudi adesso la falla da cui fugge più tempo, come un\'interruzione continua: alza un argine con una regola chiara e comunicala a chi lavora con te.',
    'gesti_tong_shu|Bi|Carriera|giorno': 'Oggi l\'almanacco indica Bi, il giorno che chiude, sfavorevole all\'avvio di attività. Al lavoro completa invece di aprire: chiudi le pratiche finite, archivia le cartelle, rispondi agli ultimi messaggi rimasti sospesi. Lascia la scrivania sgombra prima di andare via, pronta per il prossimo inizio.',
    'gesti_tong_shu|Bi|Carriera|mese': 'Il lavoro e lo studio dei trenta giorni che cominciano oggi seguono Bi, sfavorevole all\'avvio di attività. Usa il mese per completare invece di aprire: ogni settimana chiudi una pratica finita e archivia le cartelle. Comincia adesso rispondendo ai messaggi rimasti sospesi.',
    'gesti_tong_shu|Bi|Carriera|settimana': 'Bi, che la tradizione lega a chiudere le falle e alzare argini, segna oggi la tua settimana di lavoro. Individua il punto dove si disperde più tempo e mettici un argine adesso: una regola, un orario, un limite. Proteggi così le energie dei sette giorni.',
    'gesti_tong_shu|Bi|Fortuna|anno': 'Una porta chiusa bene prepara la prossima: è il segno di Bi, sotto cui l\'anno cinese è nato a Capodanno. Per le occasioni sigilla adesso ciò che hai ottenuto: metti al sicuro un documento importante, conferma un impegno preso, custodisci un contatto prezioso.',
    'gesti_tong_shu|Bi|Fortuna|giorno': 'Oggi è Bi, il giorno che sigilla, in cui l\'almanacco sconsiglia di inseguire novità. Per le occasioni conserva ciò che hai: rileggi una proposta già accettata e porta a termine l\'ultimo passaggio. Una porta chiusa bene aiuta a preparare la prossima apertura.',
    'gesti_tong_shu|Bi|Fortuna|mese': 'Conservare ciò che hai è il gesto del mese che si apre oggi con Bi, il giorno che sigilla. Per le occasioni completa ogni settimana un impegno già preso, invece di cercarne di nuovi. Comincia adesso da quello più vicino alla fine.',
    'gesti_tong_shu|Bi|Fortuna|settimana': 'Bi, l\'ultimo dei dodici ufficiali, regge oggi una settimana per chiudere un capitolo: dopo di lui la serie torna a Jian, che stabilisce. Per le occasioni saluta un progetto finito e ringrazia chi ha fatto la strada con te. Così prepari spazio.',
    'gesti_tong_shu|Bi|Generale|anno': 'Sotto Bi, che chiude e sigilla, il tuo anno cinese ha preso vita a Capodanno. Solo chi sa chiudere torna a stabilire, dice l\'almanacco antico: porta adesso a compimento una faccenda trascinata da tempo e sigillala con un gesto definitivo: un ultimo passaggio, un messaggio di chiusura.',
    'gesti_tong_shu|Bi|Generale|giorno': 'Oggi è il giorno di Bi, l\'ufficiale che chiude: l\'almanacco lo sconsiglia per aprire o partire e lo lascia al sigillare. Chiudi una cosa rimasta aperta: un barattolo, una porta che sbatte, una faccenda sospesa. Poi riponi quello che hai usato.',
    'gesti_tong_shu|Bi|Generale|mese': 'Chiudere e sigillare: è il compito del mese che parte oggi con Bi, ultimo dei dodici ufficiali. Ogni settimana porta a compimento una questione rimasta aperta e riponi ciò che hai usato. Comincia adesso chiudendo la più piccola, senza aprirne di nuove.',
    'gesti_tong_shu|Bi|Generale|settimana': 'Bi, che chiude e custodisce, regge oggi la tua settimana. La tradizione spiega che senza chiusura il nuovo non può nascere: fai la lista delle questioni aperte e chiudine una adesso, con un gesto definitivo. Le altre trovano posto nei sette giorni.',
    'gesti_tong_shu|Cheng|Amore|anno': 'Cheng, l\'ufficiale che compie e unisce, ha segnato a Capodanno il tuo anno cinese. Negli affetti il gesto è completare: pronuncia adesso la parola che trattieni da tempo a chi ami o, se sei senza legame, accetta l\'invito che continui a rimandare.',
    'gesti_tong_shu|Cheng|Amore|giorno': 'Oggi governa Cheng, il giorno del compimento, che la tradizione lega anche alle unioni. Negli affetti completa un gesto rimasto a metà: la sorpresa progettata e mai fatta, la parola gentile trattenuta. Dedicalo adesso a chi ami o a chi desideri avvicinare, senza aspettare un\'occasione speciale.',
    'gesti_tong_shu|Cheng|Amore|mese': 'Gli affetti dei trenta giorni che cominciano oggi seguono Cheng, che la tradizione lega alle unioni. Scegli una cosa da portare a compimento, un chiarimento con chi ami o un incontro che rimandi da tempo se sei senza legame: fissane adesso la data.',
    'gesti_tong_shu|Cheng|Amore|settimana': 'Cheng, che compie e unisce, dà oggi il suo segno alla settimana degli affetti. Se vivi una relazione, realizzate un progetto di cui parlate da tempo, anche piccolo; se sei senza legame, porta a termine un passo che rimandi, come accettare un invito. Stabilisci adesso il primo gesto concreto.',
    'gesti_tong_shu|Cheng|Carriera|anno': 'Il lavoro dell\'anno cinese che stai vivendo porta il segno di Cheng, sotto cui è nato a Capodanno. Il suo gesto è portare a termine: scegli adesso il compito che resta aperto da più tempo e consegnalo, anche imperfetto, con una nota su ciò che manca.',
    'gesti_tong_shu|Cheng|Carriera|giorno': 'Oggi l\'almanacco segna Cheng, il giorno adatto ad aprire e a concludere. Al lavoro porta a termine il compito più vicino alla fine e consegnalo prima di sera. Poi segnalo come chiuso: vedere una cosa completata può dare slancio a quelle che seguono.',
    'gesti_tong_shu|Cheng|Carriera|mese': 'Cheng, l\'ufficiale che compie, governa il primo dei trenta giorni di lavoro e di studio che hai davanti. Fai l\'elenco dei compiti vicini alla fine e assegna a ciascuno una data di consegna dentro il mese. Chiudi adesso il primo e spuntalo dall\'elenco.',
    'gesti_tong_shu|Cheng|Carriera|settimana': 'Sotto Cheng, che compie, la settimana di lavoro chiede traguardi più che partenze. Scegli il progetto più maturo e fissa adesso il passo che lo chiude entro i sette giorni. Coinvolgi chi deve approvarlo così il compimento non resta in sospeso.',
    'gesti_tong_shu|Cheng|Fortuna|anno': 'A Capodanno il tuo anno cinese è nato sotto Cheng, che compie le cose e accompagna chi parte. Per le occasioni il gesto è arrivare in fondo: riprendi adesso una possibilità lasciata a metà e fai il passo che mancava, di persona se puoi.',
    'gesti_tong_shu|Cheng|Fortuna|giorno': 'Oggi è Cheng, il giorno che l\'almanacco dedica a partire e a trasferirsi. Per le occasioni muoviti: vai di persona dove finora hai solo scritto, partecipa a un incontro, visita un luogo che ti incuriosisce. Spesso le cose si compiono quando ci si mette in strada.',
    'gesti_tong_shu|Cheng|Fortuna|mese': 'Mettiti in strada: il mese che comincia oggi è di Cheng, che l\'almanacco dedica a partire e a trasferirsi. Per le occasioni scegli un luogo dove finora hai solo scritto o telefonato e vacci di persona nei trenta giorni. Fissa adesso la data.',
    'gesti_tong_shu|Cheng|Fortuna|settimana': 'Cheng, l\'ufficiale del compimento e delle partenze, regge oggi una settimana in cui le occasioni chiedono di arrivare in fondo. Riprendi una possibilità lasciata cadere a metà strada e completa adesso il passaggio che mancava: una risposta, una richiesta, una visita.',
    'gesti_tong_shu|Cheng|Generale|anno': 'Il segno che Cheng ha posto a Capodanno sul tuo anno cinese è il compimento. Il gesto vale in qualunque giorno dell\'anno: scegli adesso una cosa lasciata a metà e portala a termine, anche se è piccola, poi cancellala dall\'elenco delle cose sospese.',
    'gesti_tong_shu|Cheng|Generale|giorno': 'Oggi è il giorno di Cheng, l\'ufficiale che compie: l\'almanacco lo considera fra i più adatti a portare a termine. Scegli una cosa lasciata a metà e finiscila adesso, anche se è piccola. Un libro da chiudere, una lettera da spedire, un armadio da completare.',
    'gesti_tong_shu|Cheng|Generale|mese': 'Sotto Cheng, fra i giorni più adatti a portare a termine, si apre oggi il tuo mese. Scegli tre cose lasciate a metà e assegna a ciascuna una settimana per finirla. Completa adesso la più piccola: una lettera, un armadio, un libro da chiudere.',
    'gesti_tong_shu|Cheng|Generale|settimana': 'Cheng, che porta le cose a compimento, regge oggi il primo dei sette giorni. Chiudi adesso una faccenda in sospeso da troppo tempo. Poi scegli l\'impresa che vuoi vedere compiuta prima che la settimana si chiuda e scrivila su un foglio.',
    'gesti_tong_shu|Chu|Amore|anno': 'Il cuore, in quest\'anno cinese nato sotto Chu a Capodanno, chiede spazio libero più che cose nuove. Togli adesso un peso dagli affetti: un oggetto legato a un amore finito, una gelosia, una pretesa verso chi ami o chi cerchi. Lascia andare quel peso con un gesto.',
    'gesti_tong_shu|Chu|Amore|giorno': 'Oggi l\'almanacco indica Chu, il giorno che toglie. Negli affetti lascia andare un piccolo rancore che porti da tempo verso chi ami o chi hai amato, oppure verso un familiare. Diglielo con parole semplici oppure scrivilo su un foglio e poi strappalo. Fai spazio a ciò che conta.',
    'gesti_tong_shu|Chu|Amore|mese': 'Con Chu, che leva il vecchio, cominciano oggi trenta giorni per fare pulizia nel cuore. Rileggi i messaggi che ancora ti pesano, di un amore finito o di una lite recente: cancella quelli che non vuoi più portare con te. Tieni soltanto le parole che fanno bene.',
    'gesti_tong_shu|Chu|Amore|settimana': 'La settimana che parte oggi con Chu, l\'ufficiale che toglie, chiede di sgombrare negli affetti le abitudini che allontanano. Se vivi una relazione, scegli con l\'altra persona una cosa sola da lasciare indietro; se sei senza legame, lascia andare un\'attesa che ti blocca. Comincia adesso.',
    'gesti_tong_shu|Chu|Carriera|anno': 'Sotto Chu è nato a Capodanno il tuo anno cinese: nel lavoro e nello studio chiede di levare ciò che ingombra. Scegli adesso un compito che porti avanti per abitudine, senza frutto: restituiscilo o chiudilo con una comunicazione chiara a chi di dovere.',
    'gesti_tong_shu|Chu|Carriera|giorno': 'Oggi è Chu, il giorno che leva il vecchio. Al lavoro libera la scrivania e la casella di posta: archivia ciò che è chiuso, cancella i promemoria superati, butta le carte inutili. Uno spazio sgombro aiuta a vedere quale compito viene davvero prima degli altri.',
    'gesti_tong_shu|Chu|Carriera|mese': 'Il mese di lavoro e di studio che si apre oggi porta il segno di Chu, che toglie il vecchio. Dedica i trenta giorni a sfoltire: cartelle doppie, procedure superate, abbonamenti a notiziari mai letti. Adesso comincia dalla casella di posta e svuota una sola cartella.',
    'gesti_tong_shu|Chu|Carriera|settimana': 'Con Chu, l\'ufficiale che toglie, la settimana di lavoro comincia togliendo invece di aggiungere. Rileggi gli impegni presi e scegli quello che non ha più senso portare avanti. Chiudilo adesso con garbo così i sette giorni che seguono trovano spazio per ciò che conta.',
    'gesti_tong_shu|Chu|Fortuna|anno': 'A Capodanno l\'anno cinese è nato sotto Chu, l\'ufficiale che fa posto al nuovo togliendo il vecchio. Per le occasioni il gesto vale in qualunque giorno: libera adesso un angolo della casa da ciò che non usi e lascialo vuoto, pronto ad accogliere.',
    'gesti_tong_shu|Chu|Fortuna|giorno': 'Oggi governa Chu, il giorno che toglie per fare posto. Le occasioni arrivano dove c\'è spazio: riordina l\'ingresso di casa, apri le finestre, porta via una cosa che non usi più da mesi. Lascia libero un angolo della stanza per ciò che deve ancora venire.',
    'gesti_tong_shu|Chu|Fortuna|mese': 'Trenta giorni sotto il segno di Chu partono oggi: per le occasioni, fai posto. Ogni sera di questo mese porta via di casa un oggetto che non usi, da regalare o da riciclare. Comincia adesso con il primo e lascia libero l\'angolo dove stava.',
    'gesti_tong_shu|Chu|Fortuna|settimana': 'In questa settimana segnata da Chu, che leva il vecchio, le occasioni chiedono tempo libero prima ancora delle cose nuove. Togli dall\'agenda dei sette giorni un impegno che non ti somiglia più. In quello spazio vuoto lascia entrare una possibilità diversa, anche solo una passeggiata senza meta.',
    'gesti_tong_shu|Chu|Generale|anno': 'Quest\'anno cinese ha visto la luce a Capodanno sotto Chu, che toglie il vecchio e dispone il nuovo. Il suo gesto vale in ogni momento: scegli adesso un oggetto, un impegno o un\'abitudine che tieni per inerzia e lascialo andare con un atto preciso, senza rimpianti.',
    'gesti_tong_shu|Chu|Generale|giorno': 'Oggi è il giorno di Chu, l\'ufficiale che toglie: l\'almanacco antico lo spiega come il giorno che leva il vecchio per far posto al nuovo. Scegli un cassetto, una mensola o il piano della scrivania e sgombralo adesso. Tieni solo ciò che usi davvero.',
    'gesti_tong_shu|Chu|Generale|mese': 'Chu, l\'ufficiale che leva il vecchio per far posto al nuovo, segna il giorno da cui parte il tuo mese. Scegli una stanza della casa e dedica i trenta giorni a sgombrarla un poco alla volta. Comincia adesso da un solo ripiano e porta via ciò che non serve.',
    'gesti_tong_shu|Chu|Generale|settimana': 'Oggi Chu, che toglie il vecchio e prepara il nuovo, apre una settimana di sgombero. Fai una lista di tre cose che occupano spazio senza servire più e liberatene una oggi stesso. Le altre due possono aspettare con calma i sette giorni che seguono.',
    'gesti_tong_shu|Ding|Amore|anno': 'Il segno di Ding, l\'ufficiale che fissa, accompagna gli affetti del tuo anno cinese, nato sotto di lui a Capodanno. Trasforma adesso un\'intenzione in un impegno: un tempo fisso per chi ami o, se sei senza legame, un appuntamento fisso con ciò che ti fa incontrare gli altri.',
    'gesti_tong_shu|Ding|Amore|giorno': 'Oggi governa Ding, il giorno che fissa e consolida. Negli affetti trasforma un\'intenzione in un appuntamento: con chi ami, un giorno e un\'ora senza distrazioni; o con chi desideri conoscere, un invito preciso. La tradizione sconsiglia le discussioni accese: rimanda ogni polemica a un momento più calmo.',
    'gesti_tong_shu|Ding|Amore|mese': 'Ding, che rende saldo ciò che è incerto, segna l\'avvio di un mese adatto alle promesse che si mantengono. Negli affetti scegli adesso un impegno chiaro verso chi ami o verso chi vorresti incontrare: scrivilo nell\'agenda con una data precisa e tienilo fermo.',
    'gesti_tong_shu|Ding|Amore|settimana': 'Con Ding, l\'ufficiale che stabilizza, oggi parte una settimana di promesse piccole e mantenibili. Concorda con chi ami un gesto da ripetere ogni sera dei sette giorni, oppure, se sei senza legame, promettiti un\'uscita in cui incontrare persone nuove. Fissalo adesso.',
    'gesti_tong_shu|Ding|Carriera|anno': 'Per il lavoro e lo studio, l\'anno cinese nato sotto Ding a Capodanno chiede piani chiari. Siediti adesso con il progetto che ti sta più a cuore e fissane le tappe, con un nome e una data per ciascuna. Evita le liti: la tradizione le sconsiglia sotto Ding.',
    'gesti_tong_shu|Ding|Carriera|giorno': 'Oggi l\'almanacco segna Ding, adatto a chi deve pianificare. Al lavoro prendi un progetto confuso e scrivine la scaletta: le fasi, chi fa cosa, quando finisce ciascun passaggio. Un piano messo nero su bianco libera la mente per il resto della giornata.',
    'gesti_tong_shu|Ding|Carriera|mese': 'Ding, che l\'almanacco antico indica per i piani e i calcoli, governa il primo giorno del tuo mese di lavoro. Scrivi adesso la scaletta dei trenta giorni: le tappe, i nomi di chi se ne occupa, le date di consegna. Rileggila all\'inizio di ogni settimana.',
    'gesti_tong_shu|Ding|Carriera|settimana': 'In questa settimana di lavoro, aperta oggi da Ding, l\'ufficiale che fissa, stabilisci subito le regole: orari, priorità, momenti senza interruzioni. Scrivile in un posto visibile e condividile con chi lavora accanto a te, così i sette giorni partono con chiarezza.',
    'gesti_tong_shu|Ding|Fortuna|anno': 'Ding ha fissato a Capodanno il segno del tuo anno cinese: per le occasioni vale la sua arte dei piani. Disegna adesso una mappa di ciò che speri: dove vuoi arrivare, chi può aiutarti, quale passo è alla tua portata. Tienila dove la vedi e aggiornala quando cambia.',
    'gesti_tong_shu|Ding|Fortuna|giorno': 'Oggi è Ding, il giorno che rende saldo ciò che è incerto. Per le occasioni fissa un appuntamento con qualcuno che può aprirti una porta: un incontro, una telefonata, una lettera. Metti data e ora nero su bianco così l\'occasione prende forma.',
    'gesti_tong_shu|Ding|Fortuna|mese': 'Le occasioni del mese che comincia oggi con Ding chiedono appuntamenti fissati, non attese. Scegli tre persone che possono aprirti una porta e fissa con ciascuna un incontro o una telefonata nei trenta giorni. Scrivi adesso la prima data nell\'agenda, con l\'ora.',
    'gesti_tong_shu|Ding|Fortuna|settimana': 'Ding, che la tradizione dedica ai progetti ben pensati, regge oggi una settimana in cui le occasioni si riconoscono meglio con una mappa. Scrivi dove vuoi arrivare nei sette giorni e quali persone potrebbero aiutarti. Tieni la mappa a portata di mano e fissa adesso il primo contatto.',
    'gesti_tong_shu|Ding|Generale|anno': 'A Capodanno Ding, l\'ufficiale che fissa, ha dato il suo segno al tuo anno cinese. Il gesto dell\'almanacco è fare piani: siediti adesso con un foglio, scrivi le tre cose che vuoi rendere stabili e accanto a ciascuna il passo che le avvicina.',
    'gesti_tong_shu|Ding|Generale|giorno': 'Oggi è il giorno di Ding, l\'ufficiale che fissa: l\'almanacco antico lo indica per i piani e per i calcoli. Siediti per dieci minuti con un foglio e disegna il piano della giornata. Decidi una priorità sola e scrivila in alto.',
    'gesti_tong_shu|Ding|Generale|mese': 'Sotto Ding, l\'ufficiale dei piani e dei calcoli, comincia oggi il tuo mese. Prendi un foglio grande e disegna i trenta giorni in quattro colonne, una per settimana: scrivi in ciascuna una cosa sola da fissare. Fallo adesso e appendi il foglio dove lo vedi.',
    'gesti_tong_shu|Ding|Generale|settimana': 'Ding, che rende stabili le cose, governa oggi l\'avvio della settimana. È il momento di fare il piano dei sette giorni: fissa tre obiettivi chiari e per ciascuno un giorno. Evita di disperdere le forze in imprese improvvise e rimanda le partenze non necessarie.',
    'gesti_tong_shu|Jian|Amore|anno': 'Negli affetti il tuo anno cinese porta il segno di Jian, l\'ufficiale che stabilisce, sotto cui è nato a Capodanno. Fonda adesso qualcosa che duri: un\'abitudine condivisa con chi ami o, se sei senza legame, un luogo da frequentare con costanza dove conoscere persone. Scegli oggi quale.',
    'gesti_tong_shu|Jian|Amore|giorno': 'Oggi l\'almanacco segna Jian, il giorno che stabilisce e dà inizio. Negli affetti vuol dire fare il primo passo: manda tu il messaggio che aspetti di ricevere, a chi ami o a chi desideri conoscere meglio. Proponi una cosa nuova da fare insieme e comincia con poche parole semplici.',
    'gesti_tong_shu|Jian|Amore|mese': 'Jian apre la serie degli ufficiali e governa il primo dei trenta giorni che hai davanti. Negli affetti è il tempo di fondare: scegli un gesto da ripetere ogni settimana: un tempo dedicato a chi ami oppure, se sei senza legame, un luogo dove incontrare persone nuove. Scrivilo subito nell\'agenda.',
    'gesti_tong_shu|Jian|Amore|settimana': 'Con Jian, che stabilisce, si apre oggi una settimana adatta a fondare un\'abitudine degli affetti. Se hai un legame, scegli con chi ami un piccolo rito comune, una passeggiata o una cena senza telefoni; se sei senza legame, scegline uno per incontrare persone nuove. Fissalo adesso.',
    'gesti_tong_shu|Jian|Carriera|anno': 'Il lavoro di quest\'anno cinese, nato a Capodanno sotto Jian, porta il segno dell\'ufficiale che assegna gli incarichi. Prendi adesso in mano un compito che nessuno ha ancora avviato, o una materia che vuoi studiare: scrivi il primo passo e fallo oggi stesso.',
    'gesti_tong_shu|Jian|Carriera|giorno': 'Oggi governa Jian, l\'ufficiale che stabilisce: la tradizione gli affida chi assume un incarico o comincia uno studio. Al lavoro apri adesso il compito che continui a spostare e completa soltanto il primo passaggio. Annota dove ti fermi così sai da dove riprendere.',
    'gesti_tong_shu|Jian|Carriera|mese': 'Al lavoro e nello studio questi trenta giorni partono da Jian, che l\'almanacco affida a chi assume un incarico o entra in una scuola. Iscriviti adesso al corso che rimandi, oppure prendi in carico un compito nuovo e fissa nell\'agenda la prima ora da dedicargli.',
    'gesti_tong_shu|Jian|Carriera|settimana': 'Sotto Jian, il giorno degli inizi, comincia oggi la tua settimana di lavoro e di studio. Scrivi su un foglio il progetto che vuoi avviare, dividilo in tre passi e compi adesso il primo. Tieni il foglio dove lo vedi ogni mattina di questi sette giorni.',
    'gesti_tong_shu|Jian|Fortuna|anno': 'Le occasioni del tuo anno cinese seguono Jian, sotto cui l\'anno è nato a Capodanno: l\'almanacco lo dà a chi si mette in cammino o entra in una scuola. Adesso scegli una cosa da imparare che ti avvicini a ciò che speri e cerca chi può insegnartela.',
    'gesti_tong_shu|Jian|Fortuna|giorno': 'Oggi è Jian, il giorno che stabilisce: l\'almanacco lo consiglia a chi si mette in cammino o entra in una scuola. Per le occasioni cerca un inizio: iscriviti a un corso, prendi una strada mai fatta, chiedi a qualcuno di insegnarti una cosa che non sai.',
    'gesti_tong_shu|Jian|Fortuna|mese': 'Per le occasioni dei trenta giorni che cominciano oggi con Jian, mettiti in cammino. Scegli una meta raggiungibile che non hai mai visitato (un quartiere, un museo, un sentiero) e segna nell\'agenda il giorno in cui andarci. La tradizione affida a Jian chi parte.',
    'gesti_tong_shu|Jian|Fortuna|settimana': 'Questa settimana di Jian, l\'ufficiale che apre la serie dei dodici, offre alle occasioni un punto di partenza. Scegli un luogo nuovo da frequentare nei sette giorni o una competenza da imparare. Fai adesso la prima mossa concreta per avvicinarti: una telefonata, un\'iscrizione, una strada diversa.',
    'gesti_tong_shu|Jian|Generale|anno': 'Il tuo anno cinese è nato a Capodanno sotto Jian, l\'ufficiale che stabilisce le fondamenta. Il suo gesto vale adesso come allora: scegli una cosa ferma da troppo tempo e mettila in cammino con un atto concreto. Scrivi una riga, fai una telefonata, sposta la prima pietra.',
    'gesti_tong_shu|Jian|Generale|giorno': 'Oggi è il giorno di Jian, l\'ufficiale che stabilisce: l\'almanacco lo lega agli inizi. Scegli una cosa che rimandi da tempo e dalle adesso il primo passo concreto. Scrivi la prima riga, apri il primo quaderno, segna la data in cima alla pagina. Il resto può aspettare.',
    'gesti_tong_shu|Jian|Generale|mese': 'Jian, l\'ufficiale che stabilisce, governa il giorno da cui partono questi trenta giorni. Scegli un progetto che vuoi vedere in piedi entro il mese e scrivi su un foglio i passi che servono. Compi adesso il primo, anche minimo: poi tieni il foglio in vista ogni mattina.',
    'gesti_tong_shu|Jian|Generale|settimana': 'La settimana nasce oggi sotto Jian, l\'ufficiale che stabilisce le fondamenta. Il suo gesto vale per i sette giorni: decidi adesso che cosa vuoi avviare e mettilo per iscritto in una frase sola. Poi compi il primo passo, anche piccolo, perché l\'almanacco affida a Jian gli inizi.',
    'gesti_tong_shu|Kai|Amore|anno': 'Aperto da Kai a Capodanno, il tuo anno cinese invita gli affetti all\'incontro. Il gesto è aprire il cuore: rivolgi adesso una parola sincera a chi ami o, se sei senza legame, accetta di conoscere qualcuno di nuovo, anche solo per un caffè.',
    'gesti_tong_shu|Kai|Amore|giorno': 'Oggi governa Kai, il giorno che apre, che l\'almanacco antico dedica alle unioni e ai conviti. Negli affetti apri il cuore con una frase sincera, di quelle che di solito tieni per te: dilla a chi ami o a chi desideri conoscere, guardando negli occhi oppure scrivendo a mano.',
    'gesti_tong_shu|Kai|Amore|mese': 'Sotto Kai, che l\'almanacco antico dedica alle unioni e ai conviti, cominciano oggi trenta giorni aperti agli incontri. Ogni settimana fai un invito: una cena con chi ami, un\'uscita con amici dove conoscere persone nuove se sei senza legame. Manda adesso il primo.',
    'gesti_tong_shu|Kai|Amore|settimana': 'Allargare il cerchio degli affetti è il gesto della settimana che Kai, l\'ufficiale dell\'apertura, governa da oggi. Accetta un invito o fanne uno: una cena a casa con persone care e qualcuno di nuovo, insieme a chi ami se hai un legame. Organizza adesso il primo incontro.',
    'gesti_tong_shu|Kai|Carriera|anno': 'Nel lavoro, il tuo anno cinese porta il soffio di Kai, sotto cui è nato a Capodanno. Il gesto è aprire un canale: scrivi adesso a una persona che stimi e non conosci ancora, o proponi in riunione l\'idea che tieni nel cassetto.',
    'gesti_tong_shu|Kai|Carriera|giorno': 'Oggi l\'almanacco segna Kai, il giorno propizio ad aprire un\'attività. Al lavoro apri un canale nuovo: scrivi a una persona che stimi e che non conosci ancora, proponi un\'idea in riunione, inaugura un fascicolo per un progetto. Un\'apertura piccola basta.',
    'gesti_tong_shu|Kai|Carriera|mese': 'Kai, propizio ad aprire un\'attività, segna l\'avvio del tuo mese di lavoro e di studio. Ogni settimana apri un canale nuovo: scrivi a una persona che stimi e non conosci ancora, proponi un\'idea, frequenta un incontro di settore. Comincia adesso col primo messaggio.',
    'gesti_tong_shu|Kai|Carriera|settimana': 'Sotto Kai, che apre, la settimana di lavoro e di studio comincia con una presentazione. Racconta a chi lavora con te il progetto che vuoi aprire e chiedi chi vuole partecipare nei sette giorni. Fallo adesso, finché il soffio dell\'inizio è fresco.',
    'gesti_tong_shu|Kai|Fortuna|anno': 'Kai, fra gli ufficiali più graditi alla tradizione, ha segnato a Capodanno il tuo anno cinese. Per le occasioni il gesto è uscire incontro agli altri: entra adesso in un luogo nuovo del quartiere, accetta un invito, saluta chi incroci ogni giorno.',
    'gesti_tong_shu|Kai|Fortuna|giorno': 'Oggi è Kai, il giorno dell\'apertura, fra i più graditi alla tradizione. Per le occasioni esci e incontra persone: accetta un invito, parla con qualcuno che vedi spesso senza mai salutare, entra in un luogo nuovo del quartiere. Un saluto può aprire una porta.',
    'gesti_tong_shu|Kai|Fortuna|mese': 'Esci e incontra persone: il mese che comincia oggi è di Kai, fra i giorni più graditi alla tradizione. Per le occasioni accetta ogni settimana almeno un invito e saluta qualcuno che vedi spesso senza conoscerlo. Comincia adesso con il primo saluto.',
    'gesti_tong_shu|Kai|Fortuna|settimana': 'Kai, l\'ufficiale che apre le porte, segna oggi una settimana in cui le occasioni passano dagli incontri. Scegli un gruppo, un corso o un\'associazione da frequentare nei sette giorni e fai adesso la prima telefonata. Aprire la porta è il gesto.',
    'gesti_tong_shu|Kai|Generale|anno': 'Kai, l\'ufficiale dell\'apertura, ha visto nascere a Capodanno il tuo anno cinese. Il gesto vale oggi come in ogni altro giorno: apri adesso una porta rimasta chiusa: riprendi un\'amicizia interrotta, torna in un luogo amato, rispondi a un invito lasciato cadere.',
    'gesti_tong_shu|Kai|Generale|giorno': 'Oggi è il giorno di Kai, l\'ufficiale che apre: l\'almanacco antico lo chiama il soffio vitale che comincia. Spalanca porte e finestre per qualche minuto, lascia entrare luce e aria. Poi apri anche l\'agenda e fai spazio a un incontro che desideri.',
    'gesti_tong_shu|Kai|Generale|mese': 'Kai, il soffio vitale che comincia, dà il segno al mese che parte oggi. Nei trenta giorni apri una porta nuova ogni settimana: un luogo, una persona, un\'attività mai provata. Scegli adesso la prima e scrivila nell\'agenda. Poi spalanca le finestre e lascia entrare aria.',
    'gesti_tong_shu|Kai|Generale|settimana': 'Kai, che la tradizione lega ai banchetti e alle feste, regge oggi la tua settimana. Apri la casa nei sette giorni: invita amici o vicini per un pasto semplice. Scegli adesso la data e manda gli inviti. Una tavola aperta è il gesto di Kai.',
    'gesti_tong_shu|Man|Amore|anno': 'Nato a Capodanno sotto Man, l\'ufficiale del pieno, il tuo anno cinese lega gli affetti ai voti e alla famiglia. Esprimi adesso un voto per la tua vita sentimentale, per l\'amore che hai o per quello che desideri: scrivilo su un biglietto e conservalo.',
    'gesti_tong_shu|Man|Amore|giorno': 'Oggi l\'almanacco segna Man, il giorno pieno, adatto a stringere i legami di famiglia. Chiama un parente che non senti da tempo oppure invita chi ami, o un\'amicizia cara se sei senza legame, a condividere un pasto preparato con cura. Riempi la tavola con poche cose buone.',
    'gesti_tong_shu|Man|Amore|mese': 'Per trenta giorni, da oggi, Man porta negli affetti il segno del pieno e dei legami stretti. Scegli una persona cara, chi ami o chi ti piacerebbe conoscere meglio: dedicale un gesto di cura ogni settimana. Comincia adesso con un messaggio affettuoso.',
    'gesti_tong_shu|Man|Amore|settimana': 'Sotto Man, che la tradizione affida ai legami familiari, la settimana degli affetti chiede una tavola piena. Organizza nei sette giorni un incontro che riunisca le persone care, la famiglia o gli amici più stretti, anche solo un caffè a casa tua. Manda adesso il primo invito.',
    'gesti_tong_shu|Man|Carriera|anno': 'Nel lavoro di quest\'anno cinese, nato sotto Man a Capodanno, vale l\'avvertenza dell\'almanacco: ciò che è pieno trabocca. Prima di accettare un nuovo incarico, guarda adesso ciò che già porti e lascia un impegno a chi può prenderlo con più respiro.',
    'gesti_tong_shu|Man|Carriera|giorno': 'Oggi governa Man, il giorno del pieno: ciò che è colmo chiede misura. Al lavoro guarda quello che hai già raccolto, una pratica finita o un risultato ottenuto: riconoscilo con una riga di bilancio. Ringrazia un collega che ti ha dato una mano in questi giorni.',
    'gesti_tong_shu|Man|Carriera|mese': 'Il pieno di Man governa il giorno da cui partono i tuoi trenta giorni di lavoro e di studio. Guarda i risultati già raccolti e scrivine il bilancio in una pagina. Poi ringrazia adesso, con un messaggio, chi ti ha aiutato a ottenerli.',
    'gesti_tong_shu|Man|Carriera|settimana': 'Con Man, il pieno, si apre una settimana in cui al lavoro conviene non caricarsi di impegni nuovi. Fai adesso l\'elenco di ciò che già porti e scegli dove mettere la tua cura migliore nei sette giorni. Ciò che è colmo trabocca, avverte l\'almanacco antico.',
    'gesti_tong_shu|Man|Fortuna|anno': 'Le occasioni di quest\'anno cinese, nato a Capodanno sotto Man, passano dai voti espressi con misura. Esprimi adesso un desiderio solo e preciso, scrivilo su un foglio e conservalo fra le pagine di un libro caro. Ringrazia poi per un\'occasione che hai già ricevuto.',
    'gesti_tong_shu|Man|Fortuna|giorno': 'Oggi è Man, il giorno del pieno, che la tradizione lega ai desideri espressi. Per le occasioni dai forma a ciò che speri: scrivilo in una frase chiara e leggila ad alta voce davanti alla finestra. Un desiderio detto con precisione diventa più facile da riconoscere.',
    'gesti_tong_shu|Man|Fortuna|mese': 'Nel mese che parte oggi con Man, l\'ufficiale dei voti, le occasioni chiedono un desiderio detto con chiarezza. Scrivilo adesso in una frase sola, appendila dove passi ogni giorno e leggila a voce alta ogni volta che la vedi nei trenta giorni.',
    'gesti_tong_shu|Man|Fortuna|settimana': 'Man, il giorno del pieno, regge oggi una settimana in cui le occasioni amano chi sa accogliere. Prepara adesso un piccolo spazio in casa con un oggetto che per te significa gioia. Guardalo ogni mattina dei sette giorni come un augurio.',
    'gesti_tong_shu|Man|Generale|anno': 'Man, il pieno, ha accolto a Capodanno la nascita del tuo anno cinese: l\'almanacco lo lega ai voti e alla gratitudine. Il gesto vale in qualunque punto dell\'anno: accendi adesso una candela, nomina a voce bassa tre doni ricevuti e un desiderio per chi ti è caro.',
    'gesti_tong_shu|Man|Generale|giorno': 'Oggi è il giorno di Man, l\'ufficiale del pieno: l\'almanacco lo dedica alle offerte e ai desideri espressi. Accendi una candela oppure metti un fiore sul tavolo e pronuncia a voce bassa un desiderio per chi ami. Poi ringrazia per una cosa che oggi c\'è già.',
    'gesti_tong_shu|Man|Generale|mese': 'Il mese che comincia oggi è di Man, il pieno: l\'almanacco antico avverte che ciò che è colmo trabocca. Per i trenta giorni scegli una misura semplice, un impegno in meno o una sera libera alla settimana. Fissala adesso e ringrazia per ciò che hai già.',
    'gesti_tong_shu|Man|Generale|settimana': 'Man, l\'ufficiale del pieno che la tradizione lega ai voti e ai ringraziamenti, governa oggi il primo dei sette giorni. Scrivi su un foglio tre cose di cui senti gratitudine e un desiderio solo. Conserva il foglio e rileggilo quando la settimana si chiude.',
    'gesti_tong_shu|Ping|Amore|anno': 'Per gli affetti, il tuo anno cinese porta il segno di Ping, l\'ufficiale che mette in pari, sotto cui è nato a Capodanno. Rendi più pari ciò che dai e ciò che ricevi, con chi ami o con chi ti sta vicino: fai adesso un passo concreto.',
    'gesti_tong_shu|Ping|Amore|giorno': 'Oggi governa Ping, il giorno che spiana e mette in pari. In amore appiana un piccolo attrito: se hai un legame, ascolta la versione di chi ami fino in fondo prima di rispondere; se sei senza legame, chiarisci con garbo un malinteso nato in una conoscenza recente.',
    'gesti_tong_shu|Ping|Amore|mese': 'I trenta giorni che cominciano oggi con Ping chiedono agli affetti di spianare il terreno. Ripensa a un attrito rimasto aperto, con chi ami o con chi hai lasciato andare, oppure in famiglia: scegli adesso la frase con cui appianarlo e trova il momento giusto per dirla.',
    'gesti_tong_shu|Ping|Amore|settimana': 'Ping, che livella, dà oggi il tono a una settimana di equilibrio negli affetti. Se vivi una relazione, guarda se uno dei due dà più dell\'altro e proponi un piccolo scambio di compiti; se sei senza legame, chiediti se dai agli altri più di quanto ricevi.',
    'gesti_tong_shu|Ping|Carriera|anno': 'Ping, sotto cui il tuo anno cinese è nato a Capodanno, chiede al lavoro rifinitura più che slancio. Prendi adesso il compito che fai ogni giorno e trova il passaggio che zoppica: correggilo, semplificalo, rendilo più pulito. Rifinire è il gesto dell\'ufficiale che livella.',
    'gesti_tong_shu|Ping|Carriera|giorno': 'Oggi l\'almanacco indica Ping, il giorno piano, adatto ad aggiustare. Al lavoro rimetti in sesto ciò che zoppica: correggi un documento pieno di errori, aggiorna una cartella disordinata, sistema uno strumento che usi ogni giorno. Rifinire vale quanto creare, a volte anche di più.',
    'gesti_tong_shu|Ping|Carriera|mese': 'Trenta giorni di lavoro e di studio partono oggi da Ping, l\'ufficiale che livella e aggiusta. Scegli il documento, il metodo o lo strumento che usi di più e miglioralo un poco ogni settimana. Adesso correggi la prima cosa che zoppica.',
    'gesti_tong_shu|Ping|Carriera|settimana': 'Nel lavoro, la settimana che nasce sotto Ping chiede di distribuire il carico in modo più uniforme, come fa l\'ufficiale che livella. Guarda i sette giorni che hai davanti e sposta gli impegni dove sono troppo fitti. Comincia adesso riordinando con calma l\'agenda di domani.',
    'gesti_tong_shu|Ping|Fortuna|anno': 'Quest\'anno cinese è nato a Capodanno sotto Ping, che spiana la strada: per le occasioni il gesto è togliere un intralcio. Scegli adesso una pratica ferma o una risposta che rimandi da tempo e portala a termine, così la via resta piana.',
    'gesti_tong_shu|Ping|Fortuna|giorno': 'Oggi è Ping, il giorno che rende piano il terreno. Per le occasioni abbellisci il luogo dove passi più tempo: un fiore, una luce migliore, una superficie lucidata. La tradizione lega questo giorno ai lavori di rifinitura che preparano l\'accoglienza.',
    'gesti_tong_shu|Ping|Fortuna|mese': 'Il mese di Ping, che rende piano il terreno, comincia oggi: per le occasioni prepara l\'accoglienza. Nei trenta giorni abbellisci l\'ingresso di casa, il luogo dove si arriva: una pianta, una luce calda, una soglia pulita. Comincia adesso con un solo dettaglio.',
    'gesti_tong_shu|Ping|Fortuna|settimana': 'Le occasioni dei sette giorni che oggi apre Ping, l\'ufficiale che mette in pari, passano più volentieri su una strada liscia. Individua un ostacolo pratico che ti frena, come una pratica in sospeso o una risposta da dare: rimuovilo adesso.',
    'gesti_tong_shu|Ping|Generale|anno': 'Il tuo anno cinese è venuto al mondo a Capodanno sotto Ping, l\'ufficiale che mette in pari. Il suo gesto è aggiustare: ripara adesso una cosa guasta da tempo, in casa o in un\'abitudine, poi rendila un poco più bella da guardare.',
    'gesti_tong_shu|Ping|Generale|giorno': 'Oggi è il giorno di Ping, l\'ufficiale che livella: l\'almanacco lo trova adatto ad aggiustare e abbellire. Ripara una piccola cosa rimasta guasta in casa, un bottone o una maniglia che cigola. Poi sistema un angolo perché sia più bello da guardare.',
    'gesti_tong_shu|Ping|Generale|mese': 'Ping, che livella e abbellisce, segna l\'avvio del tuo mese. Scegli una stanza o un angolo trascurato e rendilo più bello nei trenta giorni, un poco alla volta: un quadro raddrizzato, una luce nuova, una superficie pulita. Comincia adesso dal dettaglio più piccolo.',
    'gesti_tong_shu|Ping|Generale|settimana': 'La settimana che oggi apre Ping, l\'ufficiale che porta le cose al pari, chiede le riparazioni rimandate. Scrivi l\'elenco delle piccole cose da aggiustare in casa e risolvine una adesso. Le altre trovano con calma il loro giorno nei sette che seguono.',
    'gesti_tong_shu|Po|Amore|anno': 'Sotto Po, l\'ufficiale che rompe, il tuo anno cinese è nato a Capodanno: negli affetti chiede di spezzare ciò che ferisce. Elimina adesso un ricordo che ti fa ancora male, una foto o un messaggio: il vuoto che resta fa spazio agli affetti di oggi.',
    'gesti_tong_shu|Po|Amore|giorno': 'Oggi governa Po, il giorno che rompe, poco adatto agli affetti nuovi secondo l\'almanacco. Non forzare dichiarazioni né decisioni importanti. Fai piuttosto ordine nei ricordi: elimina una vecchia foto o un messaggio che ti ferisce ancora quando lo rileggi. Il vuoto che resta è spazio.',
    'gesti_tong_shu|Po|Amore|mese': 'Po, l\'ufficiale che spezza, regge il giorno da cui partono trenta giorni di pulizia negli affetti. Non progettare dichiarazioni: scegli un rancore vecchio o una speranza che ti fa solo male e lascia andare quel peso con un gesto preciso. Fallo adesso, senza clamore.',
    'gesti_tong_shu|Po|Amore|settimana': 'La settimana degli affetti che oggi comincia con Po, l\'ufficiale della rottura, non è fatta per le grandi svolte. Rompi invece uno schema che si ripete, la stessa discussione con chi ami o la stessa scelta sbagliata se sei senza legame: cambiane adesso il copione.',
    'gesti_tong_shu|Po|Carriera|anno': 'Po, l\'ufficiale che rompe, ha segnato a Capodanno la nascita del tuo anno cinese. Nel lavoro e nello studio il suo gesto è smontare ciò che non regge: abbandona adesso un metodo che ti rallenta, scrivi perché e con che cosa lo sostituisci.',
    'gesti_tong_shu|Po|Carriera|giorno': 'Oggi l\'almanacco segna Po, il giorno che rompe, sfavorevole agli inizi e alle intese. Al lavoro non lanciare progetti nuovi. Smantella piuttosto una procedura inutile: una riunione che nessuno vuole, un passaggio doppio, un modulo superato. Togliere ciò che è guasto è il suo compito.',
    'gesti_tong_shu|Po|Carriera|mese': 'Nel lavoro e nello studio, il mese che oggi apre Po è adatto a smantellare, non a lanciare. Scegli una procedura inutile o un passaggio doppio: nei trenta giorni toglilo di mezzo. Scrivi adesso a chi ne decide una proposta chiara per eliminarlo.',
    'gesti_tong_shu|Po|Carriera|settimana': 'Sotto Po, che la tradizione dedica soltanto al demolire, la settimana di lavoro comincia smontando. Guarda un metodo che ti rallenta da tempo e decidi adesso di abbandonarlo. I progetti nuovi possono partire nei giorni che seguono, quando la strada è sgombra.',
    'gesti_tong_shu|Po|Fortuna|anno': 'Per le occasioni, l\'anno cinese nato sotto Po a Capodanno chiede di sgombrare prima di cercare. Rompi adesso un\'abitudine che ti chiude le porte: la scusa che ripeti, il rifiuto automatico. Togli di mezzo anche un impegno che ti svuota.',
    'gesti_tong_shu|Po|Fortuna|giorno': 'Oggi è Po, il giorno della rottura, in cui l\'almanacco consiglia di non intraprendere nulla di propizio. Per le occasioni il gesto è sgomberare la strada: rompi un\'abitudine che ti blocca, come rimandare sempre la stessa risposta. Così la via resta più libera.',
    'gesti_tong_shu|Po|Fortuna|mese': 'Le occasioni dei trenta giorni che partono oggi con Po, l\'ufficiale che rompe, chiedono strada sgombra. Individua l\'abitudine che ti blocca più spesso, come dire di sì a tutto: spezzala adesso con un no gentile, poi ripeti quel gesto ogni settimana.',
    'gesti_tong_shu|Po|Fortuna|settimana': 'Po, l\'ufficiale che spezza, apre oggi una settimana in cui le occasioni non si inseguono: la tradizione lo lascia al demolire. Elimina adesso un impegno che ti pesa senza portarti nulla e rimanda ai giorni seguenti della settimana ogni passo nuovo.',
    'gesti_tong_shu|Po|Generale|anno': 'L\'anno cinese ha ricevuto a Capodanno il segno di Po, l\'ufficiale che rompe. Il suo gesto è demolire: spezza adesso un\'abitudine che ti trattiene, con un atto netto. Poi getta un oggetto guasto tenuto per inerzia e non riempire subito quel vuoto.',
    'gesti_tong_shu|Po|Generale|giorno': 'Oggi è il giorno di Po, l\'ufficiale che rompe: l\'almanacco lo sconsiglia per quasi ogni impresa e lo lascia soltanto al demolire. Non cominciare nulla di importante. Butta via invece un oggetto rotto che conservi senza motivo e lascia quel vuoto com\'è.',
    'gesti_tong_shu|Po|Generale|mese': 'Il primo dei trenta giorni appartiene a Po, che la tradizione lascia soltanto al demolire. Usa il mese per smontare ciò che non regge più: ogni settimana togli un\'abitudine, un oggetto o un impegno che pesa senza servire. Oggi comincia buttando via una cosa rotta.',
    'gesti_tong_shu|Po|Generale|settimana': 'Po, il giorno della rottura, regge oggi l\'avvio della tua settimana: la tradizione lo trova adatto solo a smontare. Non avviare nulla oggi: individua una cattiva abitudine e spezzala con un gesto preciso. Rimanda le partenze ai giorni successivi della settimana.',
    'gesti_tong_shu|Shou|Amore|anno': 'Dal Capodanno lunare il tuo anno cinese porta il segno di Shou, che raccoglie. Negli affetti il gesto è custodire i frutti: metti adesso in una scatola un ricordo felice di un amore o di un\'amicizia, un biglietto o una foto. Riaprila quando ne senti il bisogno.',
    'gesti_tong_shu|Shou|Amore|giorno': 'Oggi governa Shou, il giorno del raccolto. Negli affetti raccogli i momenti belli: ripensa a un ricordo felice vissuto con chi ami o con chi ti vuole bene: raccontalo a quella persona oppure mettilo per iscritto. Stampa una foto di quel giorno e appendila.',
    'gesti_tong_shu|Shou|Amore|mese': 'Trenta giorni di raccolto per gli affetti partono oggi con Shou, l\'ufficiale che raccoglie. Ogni settimana scegli un ricordo bello vissuto con chi ami o con chi ti è caro: scrivilo in un quaderno dedicato. Comincia adesso dal più recente e rileggilo con calma.',
    'gesti_tong_shu|Shou|Amore|settimana': 'Shou, l\'ufficiale che raccoglie, invita oggi gli affetti a riconoscere ciò che hanno già dato. Scrivi su un biglietto tre cose belle ricevute in questo ultimo tratto da chi ami o, se sei senza legame, da un\'amicizia cara. Consegnalo adesso, oppure rileggilo ogni sera della settimana.',
    'gesti_tong_shu|Shou|Carriera|anno': 'Il tuo anno cinese, venuto al mondo a Capodanno sotto Shou, lega il lavoro al raccolto e allo studio. Raccogli adesso ciò che hai imparato nel lavoro: scrivi in una pagina tre lezioni, un errore che non ripeti e una competenza da coltivare ancora.',
    'gesti_tong_shu|Shou|Carriera|giorno': 'Oggi l\'almanacco indica Shou, adatto a chi entra in una scuola e a chi raccoglie. Al lavoro raccogli ciò che hai imparato: annota in una pagina le lezioni dell\'ultimo progetto, gli errori e le soluzioni. Tienila a portata di mano per il prossimo inizio.',
    'gesti_tong_shu|Shou|Carriera|mese': 'Lo studio e il lavoro dei trenta giorni che cominciano oggi seguono Shou, l\'ufficiale del raccolto. Ogni settimana raccogli in una pagina ciò che hai imparato: errori, soluzioni, idee. Adesso apri la pagina e scrivi con calma la prima lezione dell\'ultimo progetto.',
    'gesti_tong_shu|Shou|Carriera|settimana': 'Shou, che la tradizione lega allo studio, segna oggi la tua settimana di lavoro e di studio. Scegli una competenza da coltivare nei sette giorni e dedica adesso mezz\'ora alla prima lezione. Raccogli materiali, appunti e domande in una cartella dedicata.',
    'gesti_tong_shu|Shou|Fortuna|anno': 'Nel tuo anno cinese, nato sotto Shou a Capodanno, le occasioni sono spesso già sulla soglia. Raccogli adesso ciò che hai seminato: rispondi a una proposta rimasta in attesa, riprendi un contatto promettente, accetta ciò che merita. Restare nei paraggi è il gesto di Shou.',
    'gesti_tong_shu|Shou|Fortuna|giorno': 'Oggi è Shou, il giorno del raccolto, che l\'almanacco sconsiglia per i viaggi lunghi. Per le occasioni resta nei paraggi e raccogli: rispondi alle proposte arrivate, rileggi gli inviti ricevuti, segna quali meritano un sì. Spesso l\'occasione è già sulla soglia.',
    'gesti_tong_shu|Shou|Fortuna|mese': 'Il mese che oggi apre Shou, l\'ufficiale del raccolto, invita a raccogliere le occasioni già vicine. Ogni settimana rileggi gli inviti e le proposte arrivate e scegli quale merita un sì. Comincia adesso dalla più vecchia, senza allontanarti per viaggi lunghi.',
    'gesti_tong_shu|Shou|Fortuna|settimana': 'In questa settimana di raccolto, aperta oggi da Shou, le occasioni possono nascere da ciò che hai seminato prima. Ripercorri gli incontri recenti e scegli quello da far maturare. Fai adesso un passo per riprenderlo, restando nei paraggi: la tradizione sconsiglia i viaggi lunghi.',
    'gesti_tong_shu|Shou|Generale|anno': 'L\'anno cinese che stai vivendo è nato a Capodanno sotto Shou, l\'ufficiale che raccoglie. Dopo il compimento viene il raccolto, dice l\'almanacco antico: raccogli adesso in una pagina i frutti già colti e rileggili ad alta voce. Riconoscere ciò che c\'è è il gesto di Shou.',
    'gesti_tong_shu|Shou|Generale|giorno': 'Oggi è il giorno di Shou, l\'ufficiale che raccoglie: l\'almanacco antico dice che dopo il compimento viene il raccolto. Fermati a mettere insieme ciò che hai ottenuto in questo tempo e scrivilo in un elenco. Leggilo con calma e riconosci il cammino fatto.',
    'gesti_tong_shu|Shou|Generale|mese': 'Il raccolto di Shou dà il segno al mese che comincia oggi. Ogni settimana dei trenta giorni metti per iscritto ciò che hai ottenuto, anche le piccole cose. Comincia adesso con un elenco di ciò che hai raccolto finora e leggilo con calma.',
    'gesti_tong_shu|Shou|Generale|settimana': 'Shou, che raccoglie i frutti, governa oggi la settimana che hai davanti. Riordina quello che hai già: foto, appunti, idee sparse in tanti posti. Riuniscile adesso in un unico luogo e scegli quale coltivare nei sette giorni. Il raccolto viene prima di ogni nuova semina.',
    'gesti_tong_shu|Wei|Amore|anno': 'Nella vita sentimentale, l\'anno cinese nato a Capodanno sotto Wei chiede vigilanza e cura. Prima di una parola difficile, con chi ami, in famiglia o con chi stai conoscendo, concediti adesso un momento di silenzio e un voto sincero per quella persona.',
    'gesti_tong_shu|Wei|Amore|giorno': 'Oggi governa Wei, il giorno che chiede attenzione. Negli affetti non affrontare le questioni delicate di fretta. Raccogliti un momento e pensa con affetto a chi ami o a chi desideri incontrare, poi esprimi un augurio sincero. La tradizione lega questo giorno ai voti più che alle imprese.',
    'gesti_tong_shu|Wei|Amore|mese': 'Il mese degli affetti che nasce oggi sotto Wei chiede delicatezza più che slancio. Ogni settimana dedica un momento di raccoglimento a chi ami o a chi desideri, con un pensiero gentile o un augurio scritto, senza pretese. Comincia adesso con il primo.',
    'gesti_tong_shu|Wei|Amore|settimana': 'La prudenza di Wei accompagna la settimana degli affetti che comincia oggi. Osserva ciò che è fragile nella tua vita sentimentale, con o senza legame: proteggilo invece di metterlo alla prova. Esprimi adesso un voto sincero per chi ami o per chi speri di incontrare.',
    'gesti_tong_shu|Wei|Carriera|anno': 'Il tuo anno cinese, nato a Capodanno sotto Wei, chiede al lavoro passi controllati. Scegli adesso il progetto più fragile e mettilo in sicurezza: una copia dei dati, un parere chiesto, una scadenza resa più realistica. La vigilanza è il gesto dell\'ufficiale.',
    'gesti_tong_shu|Wei|Carriera|giorno': 'Oggi l\'almanacco indica Wei, il giorno del pericolo, poco adatto ai salti nel vuoto. Al lavoro controlla due volte prima di inviare: rileggi una comunicazione importante, verifica i dati, chiedi un parere. La cautela di oggi può evitare correzioni nei giorni seguenti.',
    'gesti_tong_shu|Wei|Carriera|mese': 'Wei, poco adatto ai salti nel vuoto, governa il primo dei tuoi trenta giorni di lavoro. Prima di ogni decisione importante del mese chiedi un parere e rileggi i dati. Comincia adesso: scegli il progetto più esposto e scrivi tre precauzioni per metterlo al sicuro.',
    'gesti_tong_shu|Wei|Carriera|settimana': 'Sotto Wei, che invita alla vigilanza, la settimana di lavoro comincia senza cambi bruschi. Annota i punti deboli dei progetti in corso e scegli quale mettere in sicurezza per primo. Fallo adesso con calma e ricontrolla due volte ogni comunicazione importante dei sette giorni.',
    'gesti_tong_shu|Wei|Fortuna|anno': 'Wei ha dato a Capodanno il suo segno all\'anno cinese che stai vivendo. Per le occasioni vale la sua prudenza: davanti a una proposta, fermati adesso e scrivi un rischio e una precauzione, poi dedica un momento di raccoglimento a ciò che speri.',
    'gesti_tong_shu|Wei|Fortuna|giorno': 'Oggi è Wei, il giorno in cui la tradizione sconsiglia viaggi per mare e salite in alto. Per le occasioni resta con i piedi per terra: valuta con lucidità una proposta che ti è arrivata e chiedi tempo prima di rispondere. Una pausa ponderata è un gesto saggio.',
    'gesti_tong_shu|Wei|Fortuna|mese': 'Per trenta giorni, a partire da oggi, Wei invita le occasioni alla prudenza. Quando arriva una proposta, chiedi tempo prima di rispondere e valutala con lucidità. Comincia adesso con quella che hai sul tavolo e rimanda viaggi e salite che non servono.',
    'gesti_tong_shu|Wei|Fortuna|settimana': 'Wei, l\'ufficiale del pericolo, segna oggi una settimana in cui le occasioni chiedono discernimento. Scrivi adesso accanto a ogni possibilità che vedi un rischio e una precauzione. Dedica poi con calma un momento di raccoglimento a ciò che speri nei sette giorni.',
    'gesti_tong_shu|Wei|Generale|anno': 'Wei, l\'ufficiale della vigilanza, ha visto nascere a Capodanno il tuo anno cinese. Il suo gesto è il raccoglimento: fermati adesso cinque minuti in silenzio, pensa a chi vuoi proteggere e prima di ogni passo rischioso concediti una pausa per ricontrollare.',
    'gesti_tong_shu|Wei|Generale|giorno': 'Oggi è il giorno di Wei, l\'ufficiale del pericolo: l\'almanacco lo consiglia per il raccoglimento e sconsiglia di salire in alto o di cambiare casa. Prenditi cinque minuti di silenzio in un luogo tranquillo. Pensa a chi vuoi proteggere e dedicagli un pensiero.',
    'gesti_tong_shu|Wei|Generale|mese': 'Trenta giorni sotto Wei, l\'ufficiale della vigilanza, cominciano oggi: chiedono passi misurati e raccoglimento. Scegli un momento fisso della sera per qualche minuto di silenzio e dedicalo a chi vuoi proteggere. Comincia adesso, in un luogo tranquillo. Rimanda i traslochi e le salite rischiose.',
    'gesti_tong_shu|Wei|Generale|settimana': 'Wei, il giorno della vigilanza, governa oggi la tua settimana: la tradizione lo affida alle preghiere e ai voti, non agli spostamenti. Ricontrolla con calma i piani dei sette giorni prima di muoverti e dedica adesso un momento di silenzio a ciò che desideri custodire.',
    'gesti_tong_shu|Zhi|Amore|anno': 'Gli affetti del tuo anno cinese, nato a Capodanno sotto Zhi, chiedono di custodire ciò che c\'è. Proteggi adesso un legame prezioso, con chi ami o con chi ti vuole bene da sempre: mantieni una promessa rimasta in sospeso o rinnova un gesto che avevate perso.',
    'gesti_tong_shu|Zhi|Amore|giorno': 'Oggi governa Zhi, il giorno che tiene e protegge. In amore mantieni oggi stesso una piccola promessa: a chi ami, se hai un legame; a te, se sei senza legame, come l\'impegno di accettare un invito e incontrare persone nuove. Una parola tenuta vale più di dieci dette.',
    'gesti_tong_shu|Zhi|Amore|mese': 'Zhi, l\'ufficiale che tiene, apre oggi trenta giorni in cui gli affetti si rafforzano custodendo. Scegli un legame che conta per te (un amore, un\'amicizia, un familiare) e dagli ogni settimana un tempo fisso, protetto con cura. Segna adesso nell\'agenda il primo appuntamento.',
    'gesti_tong_shu|Zhi|Amore|settimana': 'Affidata a Zhi, che custodisce ciò che esiste già, la settimana in amore non chiede novità. Se hai un legame, scegli con chi ami una consuetudine che vi fa bene e proteggetela dagli impegni; se sei senza legame, tieni ferma ogni settimana un\'ora per ciò che ti accende. Fissala adesso.',
    'gesti_tong_shu|Zhi|Carriera|anno': 'L\'anno cinese, nato a Capodanno sotto Zhi, chiede al lavoro e allo studio di tenere saldo ciò che è stato costruito. Scegli adesso un risultato già ottenuto e proteggilo: documentalo, salvane una copia, insegnalo a chi lavora con te. Mantenere conta quanto costruire.',
    'gesti_tong_shu|Zhi|Carriera|giorno': 'Oggi l\'almanacco indica Zhi, il giorno che tiene fermo. Al lavoro consolida un risultato già ottenuto: salva le versioni definitive, documenta come hai risolto un problema, metti al sicuro i file importanti. Ciò che è custodito con cura resta a disposizione quando serve.',
    'gesti_tong_shu|Zhi|Carriera|mese': 'Trenta giorni di costanza cominciano oggi con Zhi, che custodisce il compiuto. Nel lavoro e nello studio metti al sicuro ciò che hai costruito: scrivi una guida di come svolgi il compito più importante, una pagina a settimana. Comincia adesso dalla prima.',
    'gesti_tong_shu|Zhi|Carriera|settimana': 'Sotto Zhi, che tiene, la settimana di lavoro chiede costanza più che novità. La tradizione sconsiglia di aprire attività nuove in questo giorno: porta avanti ciò che hai già avviato. Scegli il progetto principale dei sette giorni e dedicagli adesso la prima ora.',
    'gesti_tong_shu|Zhi|Fortuna|anno': 'Le buone occasioni dell\'anno cinese, nato sotto Zhi a Capodanno, restano vicine a chi sa tenerle. Custodisci adesso un contatto prezioso che rischi di perdere: scrivigli due righe, ricorda un favore ricevuto, proponi di rivedervi. Tenere è il gesto dell\'ufficiale che custodisce.',
    'gesti_tong_shu|Zhi|Fortuna|giorno': 'Oggi è Zhi, il giorno che trattiene e conserva. Per le occasioni non lasciar cadere un contatto prezioso: rispondi a quel messaggio rimasto aperto, ringrazia chi ti ha dato un\'indicazione utile. Le occasioni restano vicine a chi sa tenerle con garbo.',
    'gesti_tong_shu|Zhi|Fortuna|mese': 'Per le occasioni, il mese che si apre oggi sotto Zhi chiede di tenere vicino ciò che è prezioso. Ogni settimana dei trenta giorni rispondi a un messaggio rimasto aperto o ringrazia chi ti ha dato un\'indicazione utile. Fallo adesso per la prima volta.',
    'gesti_tong_shu|Zhi|Fortuna|settimana': 'Zhi, l\'ufficiale che custodisce, segna oggi una settimana in cui le occasioni vengono spesso da ciò che hai già. Scorri i tuoi contatti e scegli tre persone con cui riallacciare un filo nei sette giorni. Comincia adesso con la prima, con un messaggio semplice.',
    'gesti_tong_shu|Zhi|Generale|anno': 'Sotto Zhi, che custodisce ciò che è stato compiuto, il tuo anno cinese è nato a Capodanno. Il gesto della tradizione è costruire e piantare: metti a dimora adesso una pianta che possa crescere a lungo e affidale ciò che vuoi tenere saldo.',
    'gesti_tong_shu|Zhi|Generale|giorno': 'Oggi è il giorno di Zhi, l\'ufficiale che tiene: l\'almanacco antico dice che custodisce ciò che è stato compiuto. Scegli una buona abitudine che hai già e rinforzala adesso, ripetendola con più attenzione del solito. Mantenere conta quanto cominciare, dice questo giorno.',
    'gesti_tong_shu|Zhi|Generale|mese': 'Il mese che parte oggi porta il segno di Zhi, che custodisce ciò che è compiuto. Scegli una buona abitudine che hai già e tienila viva per tutti i trenta giorni, segnando su un calendario ogni volta che la ripeti. Fai adesso il primo segno.',
    'gesti_tong_shu|Zhi|Generale|settimana': 'Zhi, che tiene saldo il raggiunto, governa oggi la tua settimana. La tradizione lo lega al costruire e al piantare: metti a dimora una piantina o un seme in un vaso e curalo per tutti i sette giorni. Ogni volta che lo annaffi ricorda ciò che vuoi custodire.',
    'inni_orfici|Giove|Amore|anno': 'Sotto Giove, dal compleanno, il tuo anno chiede agli affetti fiducia e spazio. Adesso scrivi su un foglio tre qualità che offri a chi ami o a chi desideri incontrare. Sussurra «Zeus molto onorato, Zeus immortale» due volte e conserva il foglio in un luogo caro.',
    'inni_orfici|Giove|Amore|giorno': 'Giove, generoso con chi sa dare senza misurare, regge questa giornata. Pensa a un gesto buono ricevuto da chi ami o da un\'amicizia, se sei senza legame. Sussurra «Zeus molto onorato, Zeus immortale» e ricambia oggi con una parola di gratitudine sincera.',
    'inni_orfici|Giove|Amore|mese': 'Giove apre oggi un mese in cui gli affetti chiedono spazio e generosità. Metti in casa un vaso con un ramo verde e pensa a chi ami o a chi desideri accogliere. Sussurra «Zeus molto onorato, Zeus immortale» due volte e ogni giovedì offri un piccolo gesto d\'affetto.',
    'inni_orfici|Giove|Amore|settimana': 'Questa settimana comincia oggi, giovedì di Giove: chiede agli affetti spazio e fiducia. Prepara la tavola con un piatto in più, anche solo come simbolo. A mente ripeti due volte «Zeus molto onorato, Zeus immortale» pensando a chi ami o a chi vorresti accanto.',
    'inni_orfici|Giove|Carriera|anno': 'Nel segno di Giove è nato il tuo anno, dal compleanno: nel lavoro chiede visione e giustizia. Adesso guarda un punto alto fuori dalla finestra, poi scrivi il progetto più ampio a cui tieni. Pronuncia sottovoce «Zeus molto onorato, Zeus immortale» tre volte e fai subito un passo.',
    'inni_orfici|Giove|Carriera|giorno': 'Nel giorno di Giove, che guarda lontano e ama la misura, il lavoro chiede visione. Prima del lavoro alza lo sguardo verso un punto alto, un albero o un tetto. Pronuncia sottovoce «Zeus molto onorato, Zeus immortale», poi dedica qualche minuto al progetto più ampio che hai.',
    'inni_orfici|Giove|Carriera|mese': 'Con il giovedì di Giove nasce oggi un mese per pensare in grande nel lavoro e nello studio. Disegna su un foglio tre cerchi concentrici e scrivi al centro l\'obiettivo principale. Pronuncia sottovoce «Zeus molto onorato, Zeus immortale» tre volte, poi appendi il foglio dove lavori.',
    'inni_orfici|Giove|Carriera|settimana': 'Comincia oggi, giovedì, una settimana di Giove in cui il lavoro invita a pensare in grande con giustizia. Scrivi l\'obiettivo dei sette giorni in cima a una pagina nuova. Recita tre volte «Zeus molto onorato, Zeus immortale» e sottolinea la parola che lo riassume meglio.',
    'inni_orfici|Giove|Fortuna|anno': 'Il tuo anno, nato di giovedì dal compleanno, cammina sotto Giove: le occasioni amano chi le accoglie con fiducia. Adesso apri la porta per un istante e lascia entrare l\'aria. Ripeti a voce bassa «Zeus molto onorato, Zeus immortale», poi rispondi con un sì a una proposta che rimandi.',
    'inni_orfici|Giove|Fortuna|giorno': 'Sotto Giove, oggi, le occasioni amano chi le accoglie con larghezza. Esci all\'aperto e guarda per un momento l\'orizzonte più lontano che vedi. Ripeti a voce bassa «Zeus molto onorato, Zeus immortale» e rispondi di sì a un invito inatteso, anche piccolo.',
    'inni_orfici|Giove|Fortuna|mese': 'Oggi, giovedì di Giove, prende slancio un mese di occasioni ampie. Scrivi su un foglietto un desiderio che faccia bene anche ad altri e mettilo sotto un vaso fiorito. Ripeti a voce bassa «Zeus molto onorato, Zeus immortale» due volte, poi accogli gli inviti di questi trenta giorni.',
    'inni_orfici|Giove|Fortuna|settimana': 'Da oggi, giovedì, Giove apre sette giorni sotto un cielo ampio. Annaffia una pianta di casa e scegli una foglia nuova da guardare ogni giorno. Sussurra «Zeus molto onorato, Zeus immortale» due volte e accogli in questi giorni le occasioni che germogliano piano.',
    'inni_orfici|Giove|Generale|anno': 'Giove regge il tuo anno, nato di giovedì dal compleanno: un anno che chiede larghezza. Adesso appoggia su un davanzale una foglia o un fiore come offerta. Recita tre volte «Zeus molto onorato, Zeus immortale», poi scegli un modo per dare qualcosa agli altri lungo l\'anno.',
    'inni_orfici|Giove|Generale|giorno': 'Oggi è il giorno di Giove, il pianeta della larghezza e della fiducia. Apri le braccia, inspira a fondo e lascia entrare spazio nel petto. Recita tre volte, con voce calma, «Zeus molto onorato, Zeus immortale», poi offri un piccolo gesto di generosità a qualcuno che ti sta accanto.',
    'inni_orfici|Giove|Generale|mese': 'Il mese che nasce oggi, giovedì, porta la larghezza di Giove. Scegli un gesto di generosità da ripetere ogni giovedì per trenta giorni e scrivilo su un foglio. Recita tre volte «Zeus molto onorato, Zeus immortale», poi compi il primo gesto subito.',
    'inni_orfici|Giove|Generale|settimana': 'Sotto Giove, oggi giovedì, si apre una settimana dal respiro ampio. Metti su un davanzale una foglia, un fiore o un ramo verde. Ripeti a voce bassa «Zeus molto onorato, Zeus immortale» per tre volte, guardando il cielo sopra le case, poi lascia lì l\'offerta per sette giorni.',
    'inni_orfici|Luna|Amore|anno': 'La Luna regge il tuo anno, nato di lunedì dal compleanno: chiede ascolto negli affetti. Adesso scrivi su un foglietto una parola dolce per chi ami o per chi desideri incontrare. Mettilo sotto il cuscino e sussurra una volta «Ascolta, dea regina, portatrice di luce, divina Selene».',
    'inni_orfici|Luna|Amore|giorno': 'La Luna, custode di ciò che si sente prima di dirlo, governa questa giornata. Prima di dormire pensa a chi ami, o a chi speri di incontrare. Sussurra «Ascolta, dea regina, portatrice di luce, divina Selene» tre volte, piano, come una ninna nanna.',
    'inni_orfici|Luna|Amore|mese': 'Sotto la Luna di questo lunedì nasce un mese per gli affetti. Metti accanto al letto un oggetto d\'argento. Per trenta notti, prima di dormire, sussurra «Ascolta, dea regina, portatrice di luce, divina Selene» pensando a chi ami o, se sei senza legame, a chi potresti incontrare.',
    'inni_orfici|Luna|Amore|settimana': 'Da oggi, lunedì, la Luna guida una settimana che invita gli affetti a parlarsi con dolcezza. Metti accanto al letto una pietra chiara. Ogni sera della settimana ripeti a mente «Ascolta, dea regina, portatrice di luce, divina Selene» pensando a chi ami, o a chi desideri accanto.',
    'inni_orfici|Luna|Carriera|anno': 'Nel segno della Luna è nato il tuo anno, dal compleanno: il lavoro e lo studio crescono per fasi. Adesso apri il quaderno del lavoro e segna con una luna il punto raggiunto. Recita sottovoce «Ascolta, dea regina, portatrice di luce, divina Selene», poi fai un passo avanti.',
    'inni_orfici|Luna|Carriera|giorno': 'Nel giorno della Luna il lavoro va ascoltato più che forzato. Prima di una decisione, fermati e guarda l\'acqua che scorre da un rubinetto. Recita sottovoce «Ascolta, dea regina, portatrice di luce, divina Selene», poi lascia che l\'intuizione suggerisca il passo seguente.',
    'inni_orfici|Luna|Carriera|mese': 'Un mese di lavoro e di studio parte oggi nel giorno della Luna, che procede per fasi. Dividi su un foglio il progetto principale in quattro parti, una per ogni fase lunare. Recita sottovoce «Ascolta, dea regina, portatrice di luce, divina Selene» e comincia dalla parte più piccola.',
    'inni_orfici|Luna|Carriera|settimana': 'Comincia oggi, lunedì, sotto la Luna, una settimana in cui i progetti chiedono pazienza e ritmo. Sul quaderno degli impegni traccia una piccola falce di luna. Pronuncia due volte, a voce bassa, «Ascolta, dea regina, portatrice di luce, divina Selene» e affida il lavoro al ritmo di questi giorni.',
    'inni_orfici|Luna|Fortuna|anno': 'Dal compleanno il tuo anno cammina sotto la Luna: le occasioni vanno e vengono come le sue fasi. Adesso tieni in mano un sasso chiaro e sussurra «Ascolta, dea regina, portatrice di luce, divina Selene». Poi mettilo dove lo vedi spesso, per ricordarti di accogliere ciò che torna.',
    'inni_orfici|Luna|Fortuna|giorno': 'Sotto la Luna di oggi, che cresce e cala senza fretta, le occasioni arrivano piano. Esci un momento dopo il tramonto, o affacciati alla finestra. Ripeti a mente tre volte «Ascolta, dea regina, portatrice di luce, divina Selene» e accogli ciò che si avvicina, senza inseguirlo.',
    'inni_orfici|Luna|Fortuna|mese': 'Oggi, lunedì della Luna, prende il via un mese di occasioni che arrivano a onde. Versa un po\' d\'acqua ai piedi di una pianta e sussurra «Ascolta, dea regina, portatrice di luce, divina Selene». Per trenta giorni, ogni lunedì, annota un\'occasione intravista o colta.',
    'inni_orfici|Luna|Fortuna|settimana': 'Questa settimana nasce di lunedì, oggi, nel giorno della Luna, sotto un cielo che cambia di notte in notte. Tieni in tasca un sassolino bianco raccolto da te. Toccalo e sussurra «Ascolta, dea regina, portatrice di luce, divina Selene», ricordando che anche le occasioni hanno le loro fasi.',
    'inni_orfici|Luna|Generale|anno': 'Di lunedì, nel giorno della Luna, è nato il tuo anno dal compleanno. Adesso guarda la luce riflessa su un vetro o su uno specchio. Mormora due volte «Ascolta, dea regina, portatrice di luce, divina Selene» e lascia che l\'anno trovi il suo ritmo.',
    'inni_orfici|Luna|Generale|giorno': 'Oggi è il giorno della Luna, che misura il tempo con le sue fasi. Questa sera, se puoi, guarda il cielo da una finestra, oppure chiudi gli occhi e immaginalo. Mormora due volte «Ascolta, dea regina, portatrice di luce, divina Selene» e lascia andare la giornata.',
    'inni_orfici|Luna|Generale|mese': 'Il mese si apre oggi, lunedì, sotto la Luna che cresce e cala. Questa sera lascia un bicchiere d\'acqua vicino alla finestra e mormora due volte «Ascolta, dea regina, portatrice di luce, divina Selene». Al risveglio bevine un sorso, come un saluto ai trenta giorni che hai davanti.',
    'inni_orfici|Luna|Generale|settimana': 'La settimana si apre oggi, lunedì, nel giorno della Luna, sotto la sua luce mutevole. Versa dell\'acqua in una ciotola chiara e guardaci dentro per un istante. Recita a mezza voce «Ascolta, dea regina, portatrice di luce, divina Selene», poi versa l\'acqua in una pianta.',
    'inni_orfici|Marte|Amore|anno': 'Il tuo anno porta, dal compleanno, il segno di Marte: un desiderio che chiede gioia più che conflitto. Adesso metti una musica che ti piace e pensa a chi ami, o a chi vorresti incontrare. Pronuncia sottovoce le parole dell\'inno, «Volgiti al desiderio di Cipride e alle feste di Lieo».',
    'inni_orfici|Marte|Amore|giorno': 'Marte, che accende il desiderio, governa questa giornata degli affetti. Pensa a chi ami o a chi desideri incontrare. Sussurra due volte le parole dell\'inno, «Volgiti al desiderio di Cipride e alle feste di Lieo», poi concediti un piccolo piacere da condividere: un frutto, una musica, un brindisi.',
    'inni_orfici|Marte|Amore|mese': 'Sotto Marte nasce oggi un mese per gli affetti, caldo di desiderio. Prepara una tavola con un frutto e una bevanda da condividere con chi ami o, se sei senza legame, con gli amici cari. Pronuncia allora le parole dell\'inno, «Volgiti al desiderio di Cipride e alle feste di Lieo».',
    'inni_orfici|Marte|Amore|settimana': 'Da oggi, martedì, Marte guida una settimana di desiderio vivo e pazienza corta. Ogni volta che senti salire una parola dura, respira a fondo e ripeti a mente «Volgiti al desiderio di Cipride e alle feste di Lieo», pensando a chi ami o a chi vorresti accanto.',
    'inni_orfici|Marte|Carriera|anno': 'Nel martedì di Marte è nato il tuo anno, dal compleanno: una forza da portare nel lavoro e nello studio. Adesso scegli un attrito che ti toglie energia e trasformalo in un compito da svolgere. Recita a mente le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra».',
    'inni_orfici|Marte|Carriera|giorno': 'Nel giorno di Marte conviene affrontare ciò che rimandi. Prima di cominciare il lavoro, alzati in piedi e raddrizza le spalle. Pronuncia sottovoce le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi metti la tua forza in un solo compito, il più temuto.',
    'inni_orfici|Marte|Carriera|mese': 'Trenta giorni di lavoro partono oggi, nel martedì di Marte. Scrivi su un foglio dove vuoi mettere la forza che spendi nei contrasti. Pronuncia le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi appendi il foglio dove lavori e ogni martedì segna un passo.',
    'inni_orfici|Marte|Carriera|settimana': 'Comincia oggi, martedì, una settimana di Marte: il lavoro chiede coraggio più che fretta. Scrivi su un foglio il compito che ti pesa di più, poi piegalo in quattro. Recita tre volte le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi tienilo con te.',
    'inni_orfici|Marte|Fortuna|anno': 'Dal compleanno Marte accompagna il tuo anno e chiede di cogliere le occasioni con mano ferma. Adesso annaffia una pianta o tocca la terra di un vaso. Pronuncia le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi fai un passo concreto verso un\'occasione rimasta in attesa.',
    'inni_orfici|Marte|Fortuna|giorno': 'Sotto Marte, oggi, le occasioni chiedono un gesto pronto. Cammina con passo deciso fino a un giardino o a un\'aiuola del quartiere. Lì, a voce bassa, pronuncia le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra». Poi tocca la terra con la mano, come chi semina.',
    'inni_orfici|Marte|Fortuna|mese': 'Oggi, martedì di Marte, prende avvio un mese in cui le occasioni chiedono mano ferma. Riempi un vaso di terra e interra tre semi. Pronuncia le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi annaffiali e guardali crescere in questi trenta giorni.',
    'inni_orfici|Marte|Fortuna|settimana': 'Questa settimana nasce oggi, nel martedì di Marte, che invita a cogliere le occasioni con mano ferma. Tieni adesso nel palmo un chicco di grano o di riso. Sussurra una volta le parole dell\'inno, «mutando la forza delle armi nelle opere di Demetra», poi riponilo in tasca per sette giorni.',
    'inni_orfici|Marte|Generale|anno': 'Marte ha dato al tuo anno, dal compleanno, una forza che cerca pace. Adesso siediti, appoggia i piedi a terra e lascia scendere le spalle. Recita tre volte «Ferma la contesa furiosa, allenta il travaglio che addolora l\'animo», poi scegli una contesa da lasciar cadere, anche piccola.',
    'inni_orfici|Marte|Generale|giorno': 'Oggi è il giorno di Marte, il giorno della forza che si muove. Stringi le mani a pugno e poi aprile lentamente, sentendo la tensione che scivola via. Recita a voce bassa «Ferma la contesa furiosa, allenta il travaglio che addolora l\'animo» e scegli una sola battaglia.',
    'inni_orfici|Marte|Generale|mese': 'Il mese che parte oggi, martedì, porta l\'energia di Marte. Prendi un nastro rosso e annodalo al polso o alla maniglia di una porta. Recita tre volte «Ferma la contesa furiosa, allenta il travaglio che addolora l\'animo», poi scegli il conflitto da sciogliere in questi trenta giorni.',
    'inni_orfici|Marte|Generale|settimana': 'La settimana si apre oggi, martedì, nel giorno di Marte, con un\'energia che chiede una direzione. Accendi una candela rossa e guarda la fiamma per un istante. Ripeti tre volte «Ferma la contesa furiosa, allenta il travaglio che addolora l\'animo», poi spegnila con un soffio deciso.',
    'inni_orfici|Mercurio|Amore|anno': 'Sotto Mercurio, dal compleanno, cammina il tuo anno: negli affetti contano le parole dette bene. Adesso manda un messaggio gentile a chi ami o, se sei senza legame, scrivi due righe per chi desideri incontrare. Sussurra una volta «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia».',
    'inni_orfici|Mercurio|Amore|giorno': 'Mercurio, il messaggero, governa questa giornata e negli affetti contano le parole giuste. Pensa a un messaggio gentile per chi ami o per chi desideri conoscere. Sussurra «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi scrivilo con calma, anche senza inviarlo subito.',
    'inni_orfici|Mercurio|Amore|mese': 'Sotto Mercurio nasce oggi un mese di parole per gli affetti. Ogni mercoledì, per trenta giorni, scrivi una riga gentile per chi ami o per chi speri di incontrare. Conserva le righe in una busta e sussurra ogni volta «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia».',
    'inni_orfici|Mercurio|Amore|settimana': 'Da oggi, mercoledì, Mercurio guida sette giorni in cui gli affetti chiedono ascolto. Ogni sera rileggi l\'ultima conversazione con chi ami o con chi vorresti conoscere. A mente, una volta, ripeti «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia»; poi cerca la frase che merita una risposta più gentile.',
    'inni_orfici|Mercurio|Carriera|anno': 'Il compleanno ha messo il tuo anno sotto Mercurio: nel lavoro e nello studio contano parole chiare e accordi giusti. Adesso riordina i messaggi di lavoro e togli il superfluo. Pronuncia sottovoce «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi rispondi al messaggio che aspetta da più tempo.',
    'inni_orfici|Mercurio|Carriera|giorno': 'Il mercoledì di Mercurio è adatto alle parole scritte e agli accordi. Prima di aprire la posta di lavoro, togli dalla scrivania un oggetto inutile. Pronuncia sottovoce «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e rispondi prima di tutto al messaggio più chiaro.',
    'inni_orfici|Mercurio|Carriera|mese': 'Il mercoledì di oggi, sotto Mercurio, apre un mese adatto a studiare, scrivere e trattare. Scegli una cosa da imparare in questi trenta giorni e scrivila sulla prima pagina di un quaderno. Pronuncia due volte sottovoce «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» prima di chiudere il quaderno.',
    'inni_orfici|Mercurio|Carriera|settimana': 'Comincia oggi, mercoledì, la settimana di Mercurio: il lavoro passa attraverso parole, viaggi e incontri. Sul tuo calendario segna con un piccolo cerchio il primo appuntamento. Recita due volte «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e prepara con cura ciò che vuoi dire.',
    'inni_orfici|Mercurio|Fortuna|anno': 'Dal compleanno il tuo anno viaggia con Mercurio, signore degli incontri casuali. Adesso scegli un percorso nuovo per una commissione qualunque. Mentre vai, ripeti a mente «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e saluta chi incontri: le occasioni passano spesso dagli altri.',
    'inni_orfici|Mercurio|Fortuna|giorno': 'Mercurio, signore degli incroci e degli incontri casuali, regge la giornata di oggi. Scegli una strada diversa dal solito per un breve tratto. Mentre cammini, ripeti a mente «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e fai caso alle occasioni che ti chiamano da vicino.',
    'inni_orfici|Mercurio|Fortuna|mese': 'Oggi, mercoledì di Mercurio, prende forma un mese di incontri e di occasioni. Lascia nella borsa o in tasca un foglietto con la domanda che porti dentro. Ripeti a mente «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia»; per trenta giorni rileggila quando prendi una strada nuova.',
    'inni_orfici|Mercurio|Fortuna|settimana': 'Questa settimana nasce oggi nel mercoledì di Mercurio, quando le occasioni viaggiano veloci come i messaggi. Lascia sul tavolo d\'ingresso un foglietto con una domanda aperta. Sussurra tre volte «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi lascia che questi giorni suggeriscano la risposta.',
    'inni_orfici|Mercurio|Generale|anno': 'Il tuo anno è nato di mercoledì, dal compleanno, sotto Mercurio che collega le cose. Adesso scrivi su un foglietto la parola che vuoi tenere accanto lungo l\'anno. Recita a voce bassa «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» e conserva il foglietto nel libro che stai leggendo.',
    'inni_orfici|Mercurio|Generale|giorno': 'Oggi è il giorno di Mercurio, il messaggero che collega le cose. Apri una finestra per far passare l\'aria e resta lì qualche respiro. Recita a voce bassa «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia» due volte, poi scrivi una parola che vuoi portare con te.',
    'inni_orfici|Mercurio|Generale|mese': 'Trenta giorni di scambi partono oggi, mercoledì, sotto Mercurio. Scrivi su un foglio tre nomi di persone a cui vuoi dire qualcosa. Recita a mezza voce «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi fai oggi la prima telefonata e tieni il foglio con te.',
    'inni_orfici|Mercurio|Generale|settimana': 'La settimana si apre oggi, mercoledì, nel giorno di Mercurio, sotto il segno degli scambi e delle strade. Prendi una penna e tienila in mano un istante. Ripeti tre volte «Ascoltami, Hermes, messaggero di Zeus, figlio di Maia», poi annota tre cose da dire in questi sette giorni.',
    'inni_orfici|Saturno|Amore|anno': 'Saturno custodisce il tuo anno dal compleanno: negli affetti conta ciò che dura. Adesso tieni un oggetto che ti ricorda chi ami o, se sei senza legame, una persona fedele. Sussurra «Sempre fiorente, padre degli dèi beati e degli uomini» e ringrazia per ciò che resiste al tempo.',
    'inni_orfici|Saturno|Amore|giorno': 'Saturno, che tiene insieme ciò che dura, regge questa giornata. Pensa a chi ami o, se sei senza legame, a un\'amicizia antica che ti sostiene. Sussurra «Sempre fiorente, padre degli dèi beati e degli uomini» e ringrazia in silenzio per la fedeltà che quel legame custodisce.',
    'inni_orfici|Saturno|Amore|mese': 'Saturno apre oggi un mese in cui gli affetti crescono con pazienza. Scegli una pianta e curala ogni sabato per trenta giorni, pensando a chi ami o a chi desideri incontrare. Sussurra «Sempre fiorente, padre degli dèi beati e degli uomini» mentre la annaffi.',
    'inni_orfici|Saturno|Amore|settimana': 'Da oggi, sabato, Saturno guida sette giorni che invitano gli affetti alla pazienza. Guarda una fotografia di chi ami o di una persona cara, se sei senza legame. A mente ripeti due volte «Sempre fiorente, padre degli dèi beati e degli uomini» e lascia che il ricordo diventi gratitudine.',
    'inni_orfici|Saturno|Carriera|anno': 'Il compleanno ha consegnato il tuo anno a Saturno: nel lavoro e nello studio contano fondamenta solide. Adesso disegna su un foglio una scala e scrivi in cima il tuo traguardo. Pronuncia sottovoce «Sempre fiorente, padre degli dèi beati e degli uomini», poi sali un gradino con un\'azione semplice.',
    'inni_orfici|Saturno|Carriera|giorno': 'Nel giorno di Saturno il lavoro chiede lentezza e precisione. Prima di cominciare, metti in ordine un cassetto o una cartella. Pronuncia sottovoce «Sempre fiorente, padre degli dèi beati e degli uomini», poi porta a termine un compito lasciato a metà.',
    'inni_orfici|Saturno|Carriera|mese': 'Con il sabato di Saturno nasce oggi un mese di lavoro lento e preciso. Scegli il compito più lungo che hai e dividilo in quattro tappe, una per ogni sabato. Pronuncia sottovoce «Sempre fiorente, padre degli dèi beati e degli uomini», poi completa subito la prima tappa.',
    'inni_orfici|Saturno|Carriera|settimana': 'Comincia oggi, sabato, una settimana di Saturno in cui il lavoro chiede fondamenta solide. Su un foglio disegna una linea retta e scrivi sopra il traguardo dei sette giorni. Recita tre volte «Sempre fiorente, padre degli dèi beati e degli uomini» e procedi un passo alla volta.',
    'inni_orfici|Saturno|Fortuna|anno': 'Dal compleanno Saturno fa maturare il tuo anno: le occasioni arrivano a chi sa attendere. Adesso guarda le venature di una pietra o di un pezzo di legno. Ripeti a voce bassa «Sempre fiorente, padre degli dèi beati e degli uomini», poi lascia andare una fretta inutile.',
    'inni_orfici|Saturno|Fortuna|giorno': 'Sotto Saturno, oggi, le occasioni maturano con lentezza. Tocca il tronco di un albero o un muro antico, se ne trovi uno vicino. Ripeti a voce bassa «Sempre fiorente, padre degli dèi beati e degli uomini» e accogli ciò che arriva al momento giusto.',
    'inni_orfici|Saturno|Fortuna|mese': 'Oggi, sabato di Saturno, si avvia un mese in cui le occasioni maturano piano. Prendi un sasso liscio e tienilo sul comodino. Ripeti a voce bassa «Sempre fiorente, padre degli dèi beati e degli uomini» e ogni sabato, per trenta giorni, ricorda un\'occasione arrivata col tempo.',
    'inni_orfici|Saturno|Fortuna|settimana': 'Questa settimana nasce oggi, nel sabato di Saturno, sotto il segno della costanza. Conserva in un vasetto un pugno di terra o di sabbia. Sussurra «Sempre fiorente, padre degli dèi beati e degli uomini» e ricorda che le occasioni migliori spesso chiedono attesa.',
    'inni_orfici|Saturno|Generale|anno': 'Il tempo di Saturno guida il tuo anno, nato al compleanno in un sabato: chiede costanza. Adesso osserva per un minuto un orologio, seguendo la lancetta in silenzio. Recita lentamente «Sempre fiorente, padre degli dèi beati e degli uomini», poi scegli una cosa da costruire con pazienza lungo l\'anno.',
    'inni_orfici|Saturno|Generale|giorno': 'Oggi è il giorno di Saturno, il pianeta del tempo e della pazienza. Siediti in silenzio e appoggia le mani su una superficie di pietra o di legno. Recita lentamente «Sempre fiorente, padre degli dèi beati e degli uomini» e lascia che il tempo rallenti.',
    'inni_orfici|Saturno|Generale|mese': 'Il mese che si apre oggi, sabato, porta la costanza di Saturno. Scegli un piccolo impegno da mantenere ogni giorno per trenta giorni e scrivilo su un foglio. Recita lentamente «Sempre fiorente, padre degli dèi beati e degli uomini», poi metti il foglio sotto una pietra.',
    'inni_orfici|Saturno|Generale|settimana': 'La settimana si apre oggi, sabato, nel giorno di Saturno, che chiede costanza. Accendi una candela scura o guarda un sasso per un minuto intero. Ripeti tre volte «Sempre fiorente, padre degli dèi beati e degli uomini» e scegli una sola abitudine da custodire per sette giorni.',
    'inni_orfici|Sole|Amore|anno': 'Sotto il Sole è nato il tuo anno, dal compleanno: chiede calore negli affetti. Accendi adesso una candela e pensa a chi ami, o a chi vorresti accanto. Sussurra due volte «Occhio della giustizia, luce della vita», poi fai un gesto gentile verso qualcuno che ti è vicino.',
    'inni_orfici|Sole|Amore|giorno': 'Il Sole, che scalda senza chiedere niente in cambio, governa questa giornata. Porta una mano sul petto e pensa a chi ami, o a chi desideri incontrare. Sussurra una volta «Occhio della giustizia, luce della vita» e lascia che quel pensiero si riscaldi in silenzio.',
    'inni_orfici|Sole|Amore|mese': 'Il mese degli affetti nasce oggi nel giorno del Sole, la domenica. Metti alla luce della finestra un oggetto che ti ricorda chi ami o, se sei senza legame, un simbolo dell\'incontro che cerchi. Sussurra tre volte «Occhio della giustizia, luce della vita» e lascialo lì a prendere luce.',
    'inni_orfici|Sole|Amore|settimana': 'Sette giorni per gli affetti cominciano oggi, domenica, nel giorno del Sole. Scrivi su un foglio il nome di chi ami, o una parola per chi desideri incontrare, poi leggi piano, due volte, «Occhio della giustizia, luce della vita». Conserva il foglio in un libro che apri spesso.',
    'inni_orfici|Sole|Carriera|anno': 'Dal compleanno il tuo anno porta il segno del Sole, che dà chiarezza al lavoro e allo studio. Adesso metti sul tavolo un oggetto dorato e recita sottovoce «Occhio della giustizia, luce della vita» tre volte. Poi scrivi il compito che merita più luce e svolgine una parte.',
    'inni_orfici|Sole|Carriera|giorno': 'Nel giorno del Sole il lavoro chiede chiarezza. Prima di cominciare, apri la finestra o esci un istante all\'aperto. Ripeti a mente tre volte «Occhio della giustizia, luce della vita», poi scegli il compito più limpido della giornata e affrontalo prima degli altri.',
    'inni_orfici|Sole|Carriera|mese': 'Da questa domenica del Sole partono trenta giorni di lavoro e di studio. Scrivi in cima a un quaderno il risultato che vuoi rendere visibile, poi ripeti a mente «Occhio della giustizia, luce della vita» tre volte. Ogni domenica rileggi quella riga alla luce del giorno.',
    'inni_orfici|Sole|Carriera|settimana': 'Comincia oggi, nel giorno del Sole, una settimana in cui ogni impegno si mostra per quello che è. Sul tavolo di lavoro sistema un oggetto dorato o giallo, poi recita sottovoce «Occhio della giustizia, luce della vita» tre volte. Lascia l\'oggetto lì per sette giorni, come un piccolo segno.',
    'inni_orfici|Sole|Fortuna|anno': 'Il compleanno ha dato al tuo anno la luce del Sole, che rende visibili le occasioni. Adesso esci un momento all\'aperto o affacciati alla finestra. Pronuncia una volta «Occhio della giustizia, luce della vita», poi guarda intorno con calma e accogli la prima buona occasione che si presenta.',
    'inni_orfici|Sole|Fortuna|giorno': 'Sotto il Sole di oggi la luce rende visibili le porte aperte. Cammina qualche passo all\'aperto, guardandoti intorno con calma. Pronuncia a voce bassa «Occhio della giustizia, luce della vita» una volta sola, poi nota la prima occasione che ti viene incontro, anche minima.',
    'inni_orfici|Sole|Fortuna|mese': 'Oggi, sotto il segno del Sole, si apre un mese di occasioni da riconoscere. Metti sul davanzale un sasso chiaro raccolto da te, dove la luce lo tocchi. Pronuncia una volta «Occhio della giustizia, luce della vita»; per trenta giorni, ogni volta che lo guardi, cerca un\'occasione nuova.',
    'inni_orfici|Sole|Fortuna|settimana': 'Questa settimana nasce di domenica, oggi, nel giorno del Sole, che invita a riconoscere le occasioni. Bevi adesso un bicchiere d\'acqua alla luce del giorno, poi ripeti tre volte «Occhio della giustizia, luce della vita». Per sette giorni tieni gli occhi aperti sulle opportunità che si affacciano.',
    'inni_orfici|Sole|Generale|anno': 'Il tuo anno, dal compleanno, è nato nel giorno del Sole: porta con sé una luce che orienta. Adesso fermati dove il giorno entra più chiaro e ripeti tre volte «Occhio della giustizia, luce della vita». Poi nomina a voce bassa una cosa che vuoi vedere con più chiarezza.',
    'inni_orfici|Sole|Generale|giorno': 'Oggi è il giorno del Sole: mettiti vicino a una finestra, con il viso verso la luce. Respira piano e recita a voce bassa, per tre volte, «Occhio della giustizia, luce della vita». Poi lascia che la giornata cominci col passo che le appartiene.',
    'inni_orfici|Sole|Generale|mese': 'Trenta giorni partono oggi, domenica, sotto il Sole. Apri le tende o esci sulla soglia e lascia che la luce ti tocchi il viso. Recita due volte «Occhio della giustizia, luce della vita», poi scegli un proposito da tenere limpido in questi trenta giorni.',
    'inni_orfici|Sole|Generale|settimana': 'La settimana si apre oggi, domenica, nel giorno del Sole: da qui prende il suo primo respiro. Accendi una candela o cerca un raggio di luce, poi ripeti tre volte a mezza voce «Occhio della giustizia, luce della vita». Resta un momento in quella luce prima di muoverti.',
    'inni_orfici|Venere|Amore|anno': 'Di venerdì, nel giorno di Venere, è nato il tuo anno dal compleanno: gli affetti chiedono dolcezza. Adesso scrivi su un foglio una parola d\'amore pensando a chi ami o a chi desideri incontrare. Sussurra tre volte «Celeste, molto cantata, Afrodite amante del sorriso» e piega il foglio.',
    'inni_orfici|Venere|Amore|giorno': 'Venere, signora degli affetti, regge questa giornata. Guardati allo specchio con gentilezza, poi pensa a chi ami o a chi desideri incontrare. Sussurra «Celeste, molto cantata, Afrodite amante del sorriso» tre volte e regala un sorriso vero alla prima persona che vedi.',
    'inni_orfici|Venere|Amore|mese': 'Venere apre oggi un mese in cui gli affetti cercano dolcezza. Metti un fiore rosa in un bicchiere accanto al letto e pensa a chi ami o, se sei senza legame, all\'incontro che desideri. Sussurra «Celeste, molto cantata, Afrodite amante del sorriso» tre volte e cambia l\'acqua ogni venerdì.',
    'inni_orfici|Venere|Amore|settimana': 'Sette giorni di Venere cominciano oggi, venerdì: mettono gli affetti al centro. Scegli un nastro rosa e fai un nodo leggero. A mente ripeti «Celeste, molto cantata, Afrodite amante del sorriso» pensando a chi ami, o a chi speri di incontrare, poi tieni il nodo con te.',
    'inni_orfici|Venere|Carriera|anno': 'Venere accompagna il tuo anno dal compleanno e chiede armonia nel lavoro e nello studio. Adesso riordina il piano dove lavori e lascia un solo oggetto bello. Pronuncia sottovoce «Celeste, molto cantata, Afrodite amante del sorriso», poi scrivi un ringraziamento a chi ti ha dato una mano.',
    'inni_orfici|Venere|Carriera|giorno': 'Nel giorno di Venere, oggi, anche il lavoro si fa meglio nell\'armonia. Riordina lo spazio dove lavori e aggiungi qualcosa di bello. Pronuncia sottovoce «Celeste, molto cantata, Afrodite amante del sorriso», poi cura il rapporto con un collega con una parola cortese.',
    'inni_orfici|Venere|Carriera|mese': 'Trenta giorni di lavoro in armonia nascono oggi nel venerdì di Venere. Scrivi su un biglietto una frase gentile per chi lavora o studia con te e consegnala oggi. Recita sottovoce «Celeste, molto cantata, Afrodite amante del sorriso» due volte, poi cura ogni venerdì un piccolo gesto di collaborazione.',
    'inni_orfici|Venere|Carriera|settimana': 'Comincia oggi, venerdì, sotto Venere, una settimana in cui il lavoro chiede collaborazione e buon gusto. Sul tavolo metti un piccolo vaso con un fiore fresco. Recita due volte «Celeste, molto cantata, Afrodite amante del sorriso» e scegli con chi collaborare in modo più sereno.',
    'inni_orfici|Venere|Fortuna|anno': 'Nel segno della grazia di Venere è nato il tuo anno, dal compleanno: le occasioni passano dalla gentilezza. Adesso regala un complimento sincero a qualcuno. Ripeti a voce bassa «Celeste, molto cantata, Afrodite amante del sorriso», poi tieni con te un piccolo oggetto rosa come promemoria.',
    'inni_orfici|Venere|Fortuna|giorno': 'Sotto Venere, oggi, le porte si aprono con la gentilezza. Indossa un colore che ti piace, anche solo in un dettaglio. Ripeti a voce bassa «Celeste, molto cantata, Afrodite amante del sorriso» e accogli con un sorriso le occasioni che arrivano dagli altri.',
    'inni_orfici|Venere|Fortuna|mese': 'Sotto la grazia di Venere nasce oggi un mese di occasioni gentili. Regala oggi un fiore o un piccolo dono a qualcuno, senza motivo. Ripeti a voce bassa «Celeste, molto cantata, Afrodite amante del sorriso» e per trenta giorni nota le gentilezze che tornano verso di te.',
    'inni_orfici|Venere|Fortuna|settimana': 'Questa settimana nasce oggi, nel venerdì di Venere, sotto il segno della grazia. Raccogli un petalo o una foglia e mettila tra le pagine di un libro. Sussurra tre volte «Celeste, molto cantata, Afrodite amante del sorriso»; poi lascia che la grazia accompagni il tuo sguardo sulle occasioni.',
    'inni_orfici|Venere|Generale|anno': 'Venere ha dato al tuo anno, dal compleanno, il segno della grazia. Adesso cerca con lo sguardo la cosa più bella intorno a te e resta a guardarla. Recita a mezza voce «Celeste, molto cantata, Afrodite amante del sorriso» due volte, poi scegli un gesto armonioso da ripetere spesso.',
    'inni_orfici|Venere|Generale|giorno': 'Oggi è il giorno di Venere, il giorno della grazia e dell\'armonia. Metti un fiore o un oggetto bello dove lo vedi spesso. Recita a mezza voce «Celeste, molto cantata, Afrodite amante del sorriso» due volte e concediti un momento di bellezza senza scopo.',
    'inni_orfici|Venere|Generale|mese': 'Il mese che comincia oggi, venerdì, porta la grazia di Venere. Scegli un angolo di casa e rendilo bello con un fiore, una stoffa o una luce. Recita due volte «Celeste, molto cantata, Afrodite amante del sorriso», poi torna in quell\'angolo ogni venerdì per trenta giorni.',
    'inni_orfici|Venere|Generale|settimana': 'Oggi, venerdì, si apre nel giorno di Venere una settimana sotto il segno dell\'armonia. Profuma una stanza con un fiore, un\'erba o un po\' d\'incenso. Ripeti tre volte, piano, «Celeste, molto cantata, Afrodite amante del sorriso»; poi lascia aperta la porta perché il profumo circoli.',
    'mantra_navagraha|Budha|Amore|anno': 'Il tuo anno porta, dal compleanno, la parola di Budha, nato com\'è di mercoledì. Pensa a chi ami o a chi desideri incontrare: scrivi tre parole che vorresti sentirti dire. Sussurra sette volte «Om Budhaya namah» e dille anche tu, appena trovi l\'occasione.',
    'mantra_navagraha|Budha|Amore|giorno': 'Budha, il graha della parola, governa questo mercoledì: negli affetti contano le parole scelte con cura. Pensa a una cosa non detta alla persona amata, o a chi desideri conoscere meglio. Sussurra sette volte «Om Budhaya namah», poi cerca il modo più semplice e gentile per dirla.',
    'mantra_navagraha|Budha|Amore|mese': 'Il mese che si apre oggi, di mercoledì, porta negli affetti la parola di Budha. Scrivi una lettera breve a chi ami, o a chi desideri incontrare, anche senza spedirla. Sussurra sette volte «Om Budhaya namah» e rileggila fra trenta giorni, per vedere che cosa è cambiato.',
    'mantra_navagraha|Budha|Amore|settimana': 'La settimana degli affetti, nata oggi nel giorno di Budha, invita al dialogo. Scrivi su un biglietto una domanda che vorresti fare a chi ami o a chi vorresti conoscere. A mente, ripeti nove volte «Om Budhaya namah», poi tieni il biglietto con te finché arriva il momento giusto.',
    'mantra_navagraha|Budha|Carriera|anno': 'Sotto Budha è nato il tuo anno, nel mercoledì del compleanno: un anno di studio e di scambi. Scegli adesso un argomento del tuo lavoro che vuoi capire meglio. Pronuncia sottovoce nove volte «Om Budhaya namah» e scrivi a chi può spiegartelo.',
    'mantra_navagraha|Budha|Carriera|giorno': 'Il mercoledì di Budha è adatto ai messaggi, allo studio e all\'organizzazione. Prima di aprire la posta di lavoro, metti in ordine la scrivania. Pronuncia sottovoce undici volte «Om Budhaya namah» e rispondi con calma al messaggio che richiede più attenzione.',
    'mantra_navagraha|Budha|Carriera|mese': 'Nel mese di lavoro che comincia oggi, mercoledì, Budha chiede ordine e studio. Riordina la cartella o l\'archivio che usi più spesso. Pronuncia undici volte «Om Budhaya namah» e scegli un momento fisso, ogni mercoledì, per imparare qualcosa di nuovo nel tuo mestiere.',
    'mantra_navagraha|Budha|Carriera|settimana': 'Budha guida da oggi una settimana di lavoro fatta di idee, scambi e apprendimento. Sul calendario evidenzia in verde l\'impegno che richiede più studio. Recita nove volte «Om Budhaya namah» a voce bassa e dedica a quell\'impegno il primo momento libero.',
    'mantra_navagraha|Budha|Fortuna|anno': 'In qualunque punto dell\'anno ti trovi, Budha ne custodisce il segno: il compleanno da cui è nato cadeva di mercoledì. Leggi adesso una pagina di un libro aperto a caso. Ripeti a mente sette volte «Om Budhaya namah» e cerca lì una parola che indichi un\'occasione.',
    'mantra_navagraha|Budha|Fortuna|giorno': 'Con Budha, signore del giorno, le occasioni passano spesso per una conversazione. Prendi un percorso diverso dal solito o saluta qualcuno che vedi di rado. Ripeti a mente sette volte «Om Budhaya namah» e ascolta con attenzione ciò che ti viene raccontato.',
    'mantra_navagraha|Budha|Fortuna|mese': 'Le occasioni del mese che nasce oggi, nel giorno di Budha, passano dalle parole. Saluta qualcuno che non senti da tempo o fai una domanda a chi sa più di te. Ripeti a mente nove volte «Om Budhaya namah» e annota le idee che ricevi.',
    'mantra_navagraha|Budha|Fortuna|settimana': 'In questi sette giorni, nati di mercoledì sotto Budha, conta la curiosità. Tieni in tasca un piccolo oggetto verde, una foglia o un nastro. Sussurra undici volte «Om Budhaya namah» toccandolo; poi resta in ascolto delle opportunità che arrivano dalle parole degli altri.',
    'mantra_navagraha|Budha|Generale|anno': 'Budha, signore del mercoledì, ha visto nascere il tuo anno nel giorno del compleanno. Prendi adesso un quaderno e scrivi una cosa che hai capito di recente. Recita nove volte «Om Budhaya namah» e lascia accanto una riga vuota per la prossima scoperta.',
    'mantra_navagraha|Budha|Generale|giorno': 'Oggi è il giorno di Budha, il graha dell\'intelligenza e della parola. Siediti con un quaderno aperto e una penna in mano. Recita a voce bassa nove volte «Om Budhaya namah», poi scrivi tre pensieri chiari che vuoi tenere presenti nella giornata.',
    'mantra_navagraha|Budha|Generale|mese': 'Budha, signore di questo mercoledì, dà al mese che nasce il passo della mente curiosa. Su una pagina bianca scrivi la domanda che vuoi esplorare nei trenta giorni. Recita nove volte «Om Budhaya namah» e lascia sotto la domanda lo spazio per le risposte.',
    'mantra_navagraha|Budha|Generale|settimana': 'Mercoledì di Budha: la settimana che nasce oggi sta sotto il segno dello studio e degli scambi. Metti una foglia verde tra le pagine di un libro che stai leggendo. Ripeti undici volte «Om Budhaya namah» e lascia la foglia lì come segnalibro della settimana.',
    'mantra_navagraha|Chandra|Amore|anno': 'Chandra custodisce l\'anno nato dal tuo compleanno, che cadde di lunedì. Scrivi su un foglio bianco il nome di chi ami o, se sei senza legame, una parola per l\'amore che cerchi: piegalo in quattro. Sussurra sette volte «Om Chandraya namah» e conservalo vicino al luogo dove dormi.',
    'mantra_navagraha|Chandra|Amore|giorno': 'Chandra, la Luna di questo lunedì, scioglie le parole trattenute. Prima di dormire, pensa alla persona amata o a chi desideri incontrare. Sussurra sette volte «Om Chandraya namah» con dolcezza, poi scrivi, se vuoi, una frase gentile per chi occupa quel pensiero, anche senza mandarla.',
    'mantra_navagraha|Chandra|Amore|mese': 'Chandra, la Luna, governa il lunedì da cui nasce questo mese di affetti. Metti un sasso bianco sotto il cuscino e lascialo lì per trenta giorni. Prima di dormire, sussurra sette volte «Om Chandraya namah» pensando a chi ami, o a chi vorresti incontrare, con la stessa dolcezza.',
    'mantra_navagraha|Chandra|Amore|settimana': 'Questa settimana, nata oggi nel giorno di Chandra, chiede agli affetti tenerezza. Accendi una candela bianca e lascia che la stanza si faccia quieta. A mente, ripeti nove volte «Om Chandraya namah» pensando a chi ami o a chi vorresti accanto, poi spegni la candela con un gesto lento.',
    'mantra_navagraha|Chandra|Carriera|anno': 'Dal compleanno il tuo anno porta il segno di Chandra, nato di lunedì. Nel lavoro di adesso, prima di una decisione, chiudi gli occhi e conta nove respiri. Pronuncia cinque volte «Om Chandraya namah» e dai spazio all\'intuizione che la Luna custodisce.',
    'mantra_navagraha|Chandra|Carriera|giorno': 'Il giorno di Chandra è adatto ad ascoltare prima di decidere. Prima di una riunione o di una scelta di lavoro, bevi un bicchiere d\'acqua fresca con calma. Pronuncia sottovoce cinque volte «Om Chandraya namah» e lascia parlare l\'intuizione prima del ragionamento.',
    'mantra_navagraha|Chandra|Carriera|mese': 'Trenta giorni di lavoro e di studio nascono oggi nel segno di Chandra. Rinnova l\'acqua di un bicchiere sulla scrivania e bevine un sorso lento. Pronuncia undici volte «Om Chandraya namah» e scegli un impegno da seguire con costanza paziente, ascoltando chi lavora con te.',
    'mantra_navagraha|Chandra|Carriera|settimana': 'Chandra governa questo lunedì e la settimana di lavoro che nasce oggi: servono flessibilità e attenzione agli altri. Accanto al primo impegno dell\'agenda disegna una piccola luna crescente. Recita undici volte «Om Chandraya namah» a voce bassa e affronta quell\'impegno con animo quieto.',
    'mantra_navagraha|Chandra|Fortuna|anno': 'Nato nel giorno di Chandra, il tuo anno dal compleanno ha il passo della Luna. Metti in una tasca una conchiglia o un sasso chiaro. Ripeti a mente undici volte «Om Chandraya namah» toccandolo e lascia che le occasioni dell\'anno trovino la loro marea.',
    'mantra_navagraha|Chandra|Fortuna|giorno': 'Sotto Chandra le occasioni si accolgono come la marea, senza forzare. Dopo il tramonto affacciati alla finestra e cerca la Luna nel cielo. Ripeti a mente nove volte «Om Chandraya namah» e lascia che ciò che deve venire trovi la sua strada.',
    'mantra_navagraha|Chandra|Fortuna|mese': 'Questo lunedì di Chandra dà vita a un mese di occasioni che vanno e vengono come le maree. Lascia un chicco di riso bianco in un piattino vicino alla finestra. Ripeti a mente nove volte «Om Chandraya namah» e accogli senza fretta ciò che arriva.',
    'mantra_navagraha|Chandra|Fortuna|settimana': 'Per sette giorni da oggi, lunedì di Chandra, la luce cresce e cala come la Luna. Tieni in tasca un piccolo oggetto bianco, una conchiglia o un sasso. Sussurra sette volte «Om Chandraya namah» toccandolo; ricorda che ogni fase della Luna porta con sé le sue occasioni.',
    'mantra_navagraha|Chandra|Generale|anno': 'Il tuo anno è nato, dal compleanno, nel giorno di Chandra: un anno che ascolta la mente e i sentimenti. Guarda adesso la Luna, se è in cielo, o una luce riflessa nell\'acqua. Recita nove volte «Om Chandraya namah» e lascia che i pensieri si posino come acqua ferma.',
    'mantra_navagraha|Chandra|Generale|giorno': 'Oggi è il giorno di Chandra, la Luna, custode della mente e dei sentimenti. La sera versa dell\'acqua fresca in una ciotola bianca. Recita a voce bassa nove volte «Om Chandraya namah», guardando la superficie che riflette la luce, poi offri l\'acqua a una pianta.',
    'mantra_navagraha|Chandra|Generale|mese': 'Il mese nasce oggi di lunedì, sotto Chandra: segue come lei un ritmo che cresce e cala. Riempi d\'acqua una ciotola chiara e posala dove stanotte la Luna può specchiarsi. Recita nove volte «Om Chandraya namah», poi annota come ti senti, per rileggerlo fra trenta giorni.',
    'mantra_navagraha|Chandra|Generale|settimana': 'Lunedì, giorno di Chandra: la settimana parte oggi col ritmo delle fasi lunari. Metti accanto al letto una pietra bianca o un piccolo oggetto d\'argento. Questa sera ripeti undici volte «Om Chandraya namah» a mezza voce, poi tocca la pietra prima di dormire, ogni sera fino alla fine della settimana.',
    'mantra_navagraha|Guru|Amore|anno': 'L\'anno nato dal tuo compleanno, di giovedì, sta sotto Guru, che allarga il cuore. Scrivi una qualità che ammiri in chi ami, o che cerchi in chi desideri incontrare. Sussurra sette volte «Om Gurave namah» e tieni il foglio fra le pagine di un libro.',
    'mantra_navagraha|Guru|Amore|giorno': 'Guru, che allarga il cuore e la pazienza, governa questo giovedì. Pensa alla persona amata o a chi desideri incontrare e ricorda una qualità che ammiri, o che cerchi. Sussurra sette volte «Om Gurave namah» e trova parole semplici per nominare quella qualità, a voce o per iscritto.',
    'mantra_navagraha|Guru|Amore|mese': 'Guru, signore del giovedì, allarga gli affetti del mese che nasce oggi. Ogni sera, per trenta giorni, annota una gentilezza ricevuta o data. Sussurra sette volte «Om Gurave namah» pensando a chi ami o a chi desideri incontrare, poi scrivi la prima riga.',
    'mantra_navagraha|Guru|Amore|settimana': 'Generosità negli affetti: la chiede Guru alla settimana che nasce oggi, giovedì. Prepara una tazza di tè o un dolce da condividere con chi ami, o con chi vorresti conoscere meglio. A mente, ripeti nove volte «Om Gurave namah» mentre lo prepari, poi offrilo senza aspettare niente in cambio.',
    'mantra_navagraha|Guru|Carriera|anno': 'Il segno di Guru accompagna il tuo anno, nato di giovedì: un anno per crescere nel lavoro e nello studio. Scegli adesso una cosa che vuoi imparare bene e scrivila. Pronuncia undici volte «Om Gurave namah» e dedicale un\'ora in questi giorni.',
    'mantra_navagraha|Guru|Carriera|giorno': 'Guardare lontano e chiedere consiglio: è il dono di Guru in questo giorno. Prima di lavorare, scrivi una domanda sul tuo percorso. Pronuncia sottovoce undici volte «Om Gurave namah» e porta quella domanda a una persona esperta di cui ti fidi.',
    'mantra_navagraha|Guru|Carriera|mese': 'Per il mese di lavoro e di studio che nasce oggi, Guru chiede di guardare lontano. Scrivi il nome di una persona da cui puoi imparare. Pronuncia undici volte «Om Gurave namah» e chiedile, entro i trenta giorni, un consiglio sul tuo percorso.',
    'mantra_navagraha|Guru|Carriera|settimana': 'Questa settimana di lavoro, nata nel giorno di Guru, invita a crescere con onestà. Metti sulla scrivania un libro che ha contato nella tua formazione o un oggetto giallo. Recita nove volte «Om Gurave namah» a voce bassa e fissa un traguardo di studio per questi sette giorni.',
    'mantra_navagraha|Guru|Fortuna|anno': 'Giovedì, giorno di Guru, è nato il tuo anno, quello che parte dal compleanno. Annaffia adesso una pianta, anche piccola, con acqua pulita. Ripeti a mente sette volte «Om Gurave namah» e accogli con fiducia l\'invito buono che arriva, da qualunque parte venga.',
    'mantra_navagraha|Guru|Fortuna|giorno': 'Con lo sguardo largo di Guru, signore del giorno, le occasioni si riconoscono. Esci all\'aperto e osserva per un momento il cielo più ampio che vedi. Ripeti a mente sette volte «Om Gurave namah» e accetta con fiducia un invito che ti sembra buono.',
    'mantra_navagraha|Guru|Fortuna|mese': 'Oggi è giovedì: Guru porta crescita al mese che nasce. Metti un pugno di chicchi di grano o di riso in una ciotola gialla. Ripeti a mente nove volte «Om Gurave namah» e aggiungi un chicco per ogni occasione buona che riconosci nei trenta giorni da oggi.',
    'mantra_navagraha|Guru|Fortuna|settimana': 'Il giovedì di Guru dà alla settimana che nasce il segno della crescita. Annaffia una pianta o semina qualcosa in un vaso. Sussurra undici volte «Om Gurave namah» mentre versi l\'acqua, poi osserva nei sette giorni le occasioni che crescono lentamente come quel seme.',
    'mantra_navagraha|Guru|Generale|anno': 'Guru, il maestro degli dèi, governa il tuo anno: il compleanno da cui è nato era un giovedì. Accendi adesso una lampada e mettici accanto un fiore giallo o un libro caro. Recita nove volte «Om Gurave namah» e ringrazia chi, anche da lontano, ti ha insegnato qualcosa.',
    'mantra_navagraha|Guru|Generale|giorno': 'Oggi è il giorno di Guru, il maestro degli dèi, segno di saggezza e di larghezza. Offri un fiore giallo o qualche chicco di riso davanti a una lampada. Recita a voce bassa nove volte «Om Gurave namah» e ricorda con gratitudine chi ti ha insegnato qualcosa.',
    'mantra_navagraha|Guru|Generale|mese': 'Un mese di larghezza e di saggezza nasce oggi nel giorno di Guru. Scegli un libro che parla di ciò che vuoi capire e mettilo in vista. Recita nove volte «Om Gurave namah», poi leggine qualche pagina ogni giovedì dei trenta giorni da oggi.',
    'mantra_navagraha|Guru|Generale|settimana': 'Sotto il segno della saggezza di Guru nasce oggi, giovedì, la settimana. Indossa un dettaglio giallo, un nastro o una sciarpa. Ripeti undici volte «Om Gurave namah», con le mani giunte davanti al petto, poi scegli una cosa nuova da imparare in questi sette giorni.',
    'mantra_navagraha|Mangala|Amore|anno': 'Mangala governa il martedì da cui è nato il tuo anno, quello del compleanno: nell\'amore chiede ardore senza urti. Annoda un filo rosso al polso pensando a chi ami, o a chi desideri incontrare. Sussurra sette volte «Om Mangalaya namah» e tieni il filo finché si consuma.',
    'mantra_navagraha|Mangala|Amore|giorno': 'Mangala governa questo martedì: la passione chiede di essere guidata con cura. Se c\'è stata tensione con la persona amata, o se sei senza legame e un desiderio ti agita, respira tre volte. Sussurra nove volte «Om Mangalaya namah» e scegli una parola che ripara, non una che ferisce.',
    'mantra_navagraha|Mangala|Amore|mese': 'Il mese degli affetti che nasce oggi porta l\'ardore di Mangala, nel suo martedì. Lega un nastro rosso alla maniglia della tua stanza. Sussurra sette volte «Om Mangalaya namah» pensando a chi ami o a chi vorresti incontrare, poi cerca un modo coraggioso e gentile di mostrare ciò che senti.',
    'mantra_navagraha|Mangala|Amore|settimana': 'Nella settimana che nasce oggi, martedì di Mangala, il desiderio è vivo e impaziente. Offri un fiore rosso in un bicchiere d\'acqua sul davanzale. A mente, ripeti sette volte «Om Mangalaya namah» pensando a chi ami o a chi desideri incontrare; poi cambia l\'acqua finché il fiore resta fresco.',
    'mantra_navagraha|Mangala|Carriera|anno': 'Nato di martedì, nel giorno di Mangala, il tuo anno chiede al lavoro decisione. Scegli adesso il compito che rimandi da più tempo e scrivine il primo passo. Pronuncia undici volte «Om Mangalaya namah», poi fai quel passo prima di ogni altra cosa.',
    'mantra_navagraha|Mangala|Carriera|giorno': 'Mangala, signore del martedì, sostiene l\'iniziativa e il lavoro che chiede energia. Prima di cominciare, alzati in piedi e stringi i pugni, poi apri le mani. Pronuncia sottovoce undici volte «Om Mangalaya namah» e metti la tua energia nel compito che rimandi da tempo.',
    'mantra_navagraha|Mangala|Carriera|mese': 'Oggi, martedì di Mangala, il mese di lavoro nasce sotto il segno della decisione. Scrivi su un foglio tre azioni concrete, con un inchiostro rosso se puoi. Pronuncia undici volte «Om Mangalaya namah» e compi oggi la prima, lasciando le altre ai giorni che seguono.',
    'mantra_navagraha|Mangala|Carriera|settimana': 'Mangala apre oggi la settimana di lavoro, che chiede decisione senza durezza. Scrivi in cima all\'agenda l\'obiettivo più impegnativo di questi sette giorni. Recita nove volte «Om Mangalaya namah» a voce bassa e sottolinea il primo passo concreto che porta verso quell\'obiettivo.',
    'mantra_navagraha|Mangala|Fortuna|anno': 'Il compleanno che ha fatto nascere il tuo anno cadeva nel giorno di Mangala. Esci e cammina per qualche minuto con passo deciso, respirando a fondo. Ripeti a mente sette volte «Om Mangalaya namah» e lascia che il coraggio guidi i tuoi passi verso le occasioni di quest\'anno.',
    'mantra_navagraha|Mangala|Fortuna|giorno': 'Nel giorno di Mangala le occasioni chiedono un passo deciso. Esci e cammina con passo svelto per qualche minuto, respirando a fondo. Ripeti a mente sette volte «Om Mangalaya namah» e rispondi senza esitare a un\'opportunità che oggi ti incuriosisce davvero.',
    'mantra_navagraha|Mangala|Fortuna|mese': 'Mangala dà slancio al mese che nasce oggi, nel suo martedì. Tieni in tasca un sassolino rosso o un pezzetto di mattone. Ripeti a mente nove volte «Om Mangalaya namah» toccandolo e rispondi con prontezza alle occasioni dei trenta giorni da oggi.',
    'mantra_navagraha|Mangala|Fortuna|settimana': 'Oggi, martedì, Mangala dà alla settimana un segno di slancio. Tocca una pietra rossa, un mattone o un pugno di terra. Sussurra undici volte «Om Mangalaya namah» e lascia che il coraggio accompagni i tuoi passi verso le occasioni di questa settimana.',
    'mantra_navagraha|Mangala|Generale|anno': 'Il tuo anno, nato dal compleanno nel giorno di Mangala, chiede coraggio guidato. Adesso stringi forte i pugni per tre respiri, poi apri le mani. Recita nove volte «Om Mangalaya namah» a voce ferma e scegli una prova da affrontare con calma, senza rimandarla.',
    'mantra_navagraha|Mangala|Generale|giorno': 'Oggi è il giorno di Mangala, il graha del coraggio e dell\'energia. Accendi una lampada con un fiore rosso accanto, oppure guarda un oggetto rosso. Recita a voce ferma nove volte «Om Mangalaya namah», poi scegli una cosa difficile e affrontala prima delle altre.',
    'mantra_navagraha|Mangala|Generale|mese': 'Con Mangala, signore di questo martedì, nasce un mese di energia da guidare. Accendi una candela rossa e guarda la fiamma restare dritta. Recita nove volte «Om Mangalaya namah» con voce ferma, poi scegli una sola battaglia che valga la pena nei trenta giorni da oggi.',
    'mantra_navagraha|Mangala|Generale|settimana': 'Martedì, giorno di Mangala: oggi parte una settimana con una forza che cerca direzione. Su un foglio scrivi l\'energia che vuoi usare bene in questi sette giorni. Ripeti sette volte «Om Mangalaya namah» toccando il foglio con il dito, poi ripiegalo e tienilo vicino.',
    'mantra_navagraha|Shani|Amore|anno': 'L\'anno che il compleanno ti ha dato è nato sotto Shani, che custodisce ciò che dura. Scrivi su un foglio una promessa di pazienza verso chi ami o, se sei senza legame, verso l\'amore che aspetti. Sussurra sette volte «Om Shanaishcharaya namah» e conserva il foglio in un cassetto.',
    'mantra_navagraha|Shani|Amore|giorno': 'Shani, che custodisce i legami capaci di durare, governa questo sabato. Pensa alla persona amata o a un affetto antico, oppure a chi desideri incontrare con calma. Sussurra sette volte «Om Shanaishcharaya namah» e rendi grazie per la pazienza che ogni legame vero richiede.',
    'mantra_navagraha|Shani|Amore|mese': 'Pazienza negli affetti: Shani la chiede al mese che nasce oggi. Accendi una candela scura e ricorda un legame che ha resistito al tempo. Sussurra sette volte «Om Shanaishcharaya namah» pensando a chi ami o a chi desideri incontrare, senza fretta di risposte.',
    'mantra_navagraha|Shani|Amore|settimana': 'Fedeltà e calma negli affetti: le chiede Shani alla settimana nata oggi, sabato. Riguarda una fotografia di chi ami, o di un affetto se sei senza legame: nota i segni del tempo condiviso. Ripeti nove volte «Om Shanaishcharaya namah», poi scegli un gesto paziente da offrire in questi giorni.',
    'mantra_navagraha|Shani|Carriera|anno': 'Sotto Shani, nel sabato del compleanno, è nato il tuo anno di lavoro paziente. Rimetti adesso in ordine una cartella o un archivio trascurato. Pronuncia undici volte «Om Shanaishcharaya namah» e porta avanti con costanza il compito più lungo che hai davanti.',
    'mantra_navagraha|Shani|Carriera|giorno': 'Il sabato di Shani è adatto al lavoro serio, lento e ben fatto. Prima di cominciare, riordina un cassetto o un archivio trascurato. Pronuncia sottovoce undici volte «Om Shanaishcharaya namah» e porta a termine un compito che aspetta da tempo.',
    'mantra_navagraha|Shani|Carriera|mese': 'Shani governa il sabato da cui nasce questo mese di lavoro lento e solido. Scegli un progetto lungo e dividilo in quattro passi, uno per settimana. Pronuncia undici volte «Om Shanaishcharaya namah» e compi oggi il primo, con cura e senza fretta.',
    'mantra_navagraha|Shani|Carriera|settimana': 'Per la settimana di lavoro che nasce oggi Shani chiede fondamenta e perseveranza. Su un foglio scrivi un traguardo lontano e, sotto, il primo passo. Recita nove volte «Om Shanaishcharaya namah» a voce bassa e fai quel passo prima di sera.',
    'mantra_navagraha|Shani|Fortuna|anno': 'Da un sabato, quello del tuo compleanno, l\'anno porta il segno di Shani. Offri qualche seme agli uccelli, o un piccolo aiuto a chi ne ha bisogno, come vuole l\'usanza. Ripeti a mente sette volte «Om Shanaishcharaya namah» e lascia crescere le occasioni con il loro passo.',
    'mantra_navagraha|Shani|Fortuna|giorno': 'Shani, signore del sabato, insegna che le occasioni chiedono attesa e attenzione. Offri qualche seme di sesamo nero agli uccelli, come vuole l\'usanza, o un piccolo aiuto a chi ne ha bisogno. Ripeti a mente sette volte «Om Shanaishcharaya namah» e lascia maturare ciò che ha bisogno di tempo.',
    'mantra_navagraha|Shani|Fortuna|mese': 'Nel mese che nasce sotto Shani le occasioni maturano piano. Metti un sasso scuro sul davanzale e lascialo lì per i trenta giorni. Ripeti a mente nove volte «Om Shanaishcharaya namah» toccandolo e accogli con pazienza le occasioni che chiedono tempo.',
    'mantra_navagraha|Shani|Fortuna|settimana': 'Sette giorni sotto Shani, da questo sabato: le occasioni crescono piano. Conserva in una ciotola scura un pugno di sesamo o di riso. Sussurra undici volte «Om Shanaishcharaya namah» sfiorandolo con le dita; ricorda che le occasioni più solide hanno bisogno di pazienza.',
    'mantra_navagraha|Shani|Generale|anno': 'Shani governa il tuo anno: il compleanno da cui è nato cadeva di sabato. Accendi adesso una candela scura o una lampada a olio. Recita lentamente nove volte «Om Shanaishcharaya namah» e scegli una cosa da fare con costanza, giorno dopo giorno, senza fretta.',
    'mantra_navagraha|Shani|Generale|giorno': 'Oggi è il giorno di Shani, il graha del tempo, della disciplina e della pazienza. Accendi una lampada a olio o una candela scura al calare del sole. Recita lentamente nove volte «Om Shanaishcharaya namah» e lascia andare una fretta che non ti serve.',
    'mantra_navagraha|Shani|Generale|mese': 'Un mese di costanza nasce oggi, sabato, nel giorno di Shani. Scegli un\'abitudine piccola e utile da tenere per trenta giorni e scrivila su un foglio. Recita nove volte «Om Shanaishcharaya namah», poi fai oggi la prima croce accanto al suo nome.',
    'mantra_navagraha|Shani|Generale|settimana': 'Sabato, giorno di Shani: la settimana che nasce oggi chiede costanza più che slancio. Scegli un piccolo impegno quotidiano da mantenere per sette giorni. Ripeti undici volte «Om Shanaishcharaya namah» a voce bassa, con le mani giunte, poi comincia subito quell\'impegno.',
    'mantra_navagraha|Shukra|Amore|anno': 'Shukra, signore degli affetti, governa l\'anno nato dal tuo compleanno. Scrivi su un biglietto rosa il nome di chi ami, o il desiderio di un incontro se sei senza legame. Sussurra sette volte «Om Shukraya namah» e conserva il biglietto in un luogo profumato.',
    'mantra_navagraha|Shukra|Amore|giorno': 'Shukra, signore degli affetti e del piacere di stare insieme, governa questo venerdì. Pensa con un sorriso alla persona amata o a chi desideri accanto. Sussurra sette volte «Om Shukraya namah» e prepara un piccolo gesto di cura: un fiore, un messaggio, un tempo condiviso.',
    'mantra_navagraha|Shukra|Amore|mese': 'Shukra, che governa questo venerdì, porta dolcezza al mese degli affetti. Profuma un fazzoletto con un\'essenza delicata e tienilo con te. Sussurra sette volte «Om Shukraya namah» pensando a chi ami o a chi desideri incontrare; poi concediti ogni venerdì un momento di tenerezza.',
    'mantra_navagraha|Shukra|Amore|settimana': 'Venerdì di Shukra: per sette giorni gli affetti stanno nella luce della dolcezza. Annoda un filo bianco o rosa intorno al polso, senza stringere. A mente, ripeti nove volte «Om Shukraya namah» pensando a chi ami o a chi vorresti incontrare; poi porta il filo con te.',
    'mantra_navagraha|Shukra|Carriera|anno': 'Dal venerdì del compleanno il tuo anno porta la grazia di Shukra, anche nel lavoro. Metti sulla scrivania un oggetto bello, scelto con cura. Pronuncia undici volte «Om Shukraya namah» e rendi più gentile una collaborazione difficile, con una parola o un gesto.',
    'mantra_navagraha|Shukra|Carriera|giorno': 'Nel lavoro, il venerdì di Shukra insegna che la gentilezza apre più porte della fretta. Rendi più bello il posto dove lavori con un dettaglio curato. Pronuncia sottovoce undici volte «Om Shukraya namah» e scegli una collaborazione da coltivare con una parola cortese.',
    'mantra_navagraha|Shukra|Carriera|mese': 'Collaborare con grazia: è il compito che Shukra dà al mese di lavoro nato oggi. Scegli un collega o un compagno di studio e offrigli un aiuto concreto. Pronuncia undici volte «Om Shukraya namah» e coltiva quella collaborazione nei trenta giorni.',
    'mantra_navagraha|Shukra|Carriera|settimana': 'La settimana di lavoro nata oggi nel giorno di Shukra chiede armonia, creatività e buone relazioni. Tieni sulla scrivania qualcosa di bianco o d\'argento. Recita nove volte «Om Shukraya namah» a voce bassa e dedica qualche minuto a un\'idea creativa rimasta in disparte.',
    'mantra_navagraha|Shukra|Fortuna|anno': 'Nel segno di Shukra è nato il tuo anno, dal compleanno di venerdì. Indossa adesso un dettaglio che ti piace, anche piccolo. Ripeti a mente sette volte «Om Shukraya namah» e accogli gli incontri che arrivano: spesso portano con sé le occasioni.',
    'mantra_navagraha|Shukra|Fortuna|giorno': 'Gli incontri, nel giorno di Shukra, portano spesso le occasioni. Indossa qualcosa che ti fa sentire a tuo agio, anche un solo dettaglio. Ripeti a mente sette volte «Om Shukraya namah» e accogli con gentilezza chi oggi ti viene incontro per strada.',
    'mantra_navagraha|Shukra|Fortuna|mese': 'Oggi nasce un mese di incontri, nel giorno di Shukra. Metti un fiore rosa o bianco vicino alla porta di casa. Ripeti a mente nove volte «Om Shukraya namah» e accogli con gentilezza le persone che bussano nei trenta giorni da oggi.',
    'mantra_navagraha|Shukra|Fortuna|settimana': 'Armonia per sette giorni: è il segno di Shukra su questo venerdì. Metti un petalo bianco in una busta e conservala in un cassetto. Sussurra undici volte «Om Shukraya namah» mentre la chiudi, poi lascia spazio alle occasioni che arrivano con grazia.',
    'mantra_navagraha|Shukra|Generale|anno': 'Il tuo anno ha il volto di Shukra: è nato, dal compleanno, di venerdì. Concediti adesso un momento di bellezza, una musica o un profumo che ti fanno bene. Recita nove volte «Om Shukraya namah» e lascia che quella grazia ti accompagni fino a sera.',
    'mantra_navagraha|Shukra|Generale|giorno': 'Oggi è il giorno di Shukra, il graha della bellezza e dell\'armonia. Profuma la stanza con un fiore bianco, un po\' d\'incenso o un\'essenza delicata. Recita a voce bassa nove volte «Om Shukraya namah» e concediti un momento di bellezza: una musica, un colore, un silenzio.',
    'mantra_navagraha|Shukra|Generale|mese': 'Trenta giorni di bellezza da coltivare: oggi è venerdì, giorno di Shukra. Scegli un angolo della casa e rendilo più bello con un oggetto, un colore o un fiore. Recita nove volte «Om Shukraya namah» e tieni curato quell\'angolo per tutto il mese.',
    'mantra_navagraha|Shukra|Generale|settimana': 'Shukra, con la sua grazia, governa questo venerdì e la settimana che nasce oggi. Metti un fiore bianco in un vaso nel punto più luminoso della casa. Ripeti undici volte «Om Shukraya namah» guardandolo; poi cambia l\'acqua ogni mattina finché resta fresco.',
    'mantra_navagraha|Surya|Amore|anno': 'Surya governa il giorno da cui è nato il tuo anno, quello del compleanno. Porta alla mente chi ami o chi desideri incontrare: lascia che la luce ti scaldi le mani aperte. Sussurra sette volte «Om Suryaya namah» per gli affetti che l\'anno custodisce.',
    'mantra_navagraha|Surya|Amore|giorno': 'Surya, che illumina senza distinzione, governa questo giorno. Siediti alla luce e porta alla mente la persona amata o chi desideri incontrare. Sussurra sette volte «Om Suryaya namah» e immagina quella luce posarsi anche su quel volto, vicino o ancora sconosciuto, con lo stesso calore.',
    'mantra_navagraha|Surya|Amore|mese': 'Per i trenta giorni che si aprono oggi, domenica di Surya, gli affetti cercano calore e sincerità. Metti un fiore giallo in un bicchiere d\'acqua vicino alla finestra. Recita sette volte «Om Suryaya namah» pensando a chi ami o a chi desideri incontrare, poi rinnova l\'acqua quando serve.',
    'mantra_navagraha|Surya|Amore|settimana': 'Questa settimana nasce oggi nel giorno di Surya, la domenica, che porta negli affetti il calore della luce. Offri un fiore rosso o arancione davanti a una finestra soleggiata. A mente, ripeti nove volte «Om Suryaya namah» pensando a chi ami o a chi vorresti accanto.',
    'mantra_navagraha|Surya|Carriera|anno': 'Nel giorno di Surya è nato il tuo anno, dal compleanno: un anno che chiede al lavoro dignità e chiarezza. Metti in vista sulla scrivania una cosa che hai fatto bene. Pronuncia sottovoce undici volte «Om Suryaya namah» e riconosci quel merito senza falsa modestia.',
    'mantra_navagraha|Surya|Carriera|giorno': 'Nel giorno di Surya ogni compito trova il suo posto nella luce. Prima di lavorare, apri le tende e respira tre volte con il viso verso il sole. Pronuncia sottovoce undici volte «Om Suryaya namah», poi affronta il compito che richiede più chiarezza.',
    'mantra_navagraha|Surya|Carriera|mese': 'Surya, che governa questa domenica, dà il tono al mese di lavoro e di studio che nasce oggi. Scrivi su un foglio l\'obiettivo dei trenta giorni e mettilo dove batte la luce. Pronuncia nove volte «Om Suryaya namah», poi rileggilo ogni mattina prima di cominciare.',
    'mantra_navagraha|Surya|Carriera|settimana': 'Da oggi, domenica, la settimana di lavoro sta sotto Surya, che chiede dignità e chiarezza. Sulla scrivania metti un oggetto rosso o dorato come segno di questi sette giorni. Recita nove volte «Om Suryaya namah» a voce bassa, toccando l\'oggetto, poi lascialo lì per tutta la settimana.',
    'mantra_navagraha|Surya|Fortuna|anno': 'Il compleanno da cui è nato il tuo anno cadeva di domenica, nel giorno di Surya. Versa un filo d\'acqua in un vaso di fiori rivolto al sole. Ripeti a mente nove volte «Om Suryaya namah» e tieni gli occhi aperti alle occasioni che la luce rende visibili.',
    'mantra_navagraha|Surya|Fortuna|giorno': 'La luce di Surya, signore di questo giorno, mostra ciò che era in ombra. Esci all\'aperto e fai qualche passo verso oriente. Ripeti a mente sette volte «Om Suryaya namah» e accogli con occhi limpidi le occasioni che si mostrano lungo la strada.',
    'mantra_navagraha|Surya|Fortuna|mese': 'Oggi è domenica e il mese che nasce sta sotto la luce di Surya. Prendi un piccolo oggetto dorato, un anello o un bottone: tienilo con te. Ripeti a mente dodici volte «Om Suryaya namah» toccandolo, poi lascia che ti ricordi di guardare le occasioni in piena luce.',
    'mantra_navagraha|Surya|Fortuna|settimana': 'Surya, il Sole che sorge, governa questa domenica e i sette giorni che nascono con lei. Adesso bevi un sorso d\'acqua guardando il cielo. Sussurra undici volte «Om Suryaya namah» e in questa settimana tieni lo sguardo aperto alle opportunità che si presentano alla luce del giorno.',
    'mantra_navagraha|Surya|Generale|anno': 'Il tuo anno, dal compleanno, è nato nel giorno di Surya, la domenica. Adesso, in qualunque punto dell\'anno ti trovi, esci alla luce e alza il viso verso il sole. Recita nove volte «Om Suryaya namah» e ringrazia per un giorno luminoso già vissuto.',
    'mantra_navagraha|Surya|Generale|giorno': 'Oggi è il giorno di Surya, il Sole che rischiara ogni cosa. Versa un filo d\'acqua da un bicchiere guardando la luce, come nell\'offerta tradizionale. Recita a voce bassa nove volte «Om Suryaya namah», poi unisci le mani davanti al petto e porta quella luce nel resto della giornata.',
    'mantra_navagraha|Surya|Generale|mese': 'Il mese che nasce oggi porta il segno di Surya: è domenica, il giorno del Sole. Esci alla luce e guarda per un momento il cielo verso oriente. Recita undici volte «Om Suryaya namah», poi apri le finestre di una stanza rimasta in ombra e lascia entrare il giorno.',
    'mantra_navagraha|Surya|Generale|settimana': 'La settimana nasce oggi, domenica, nel giorno di Surya: prende avvio dalla sua luce. Accendi una piccola lampada o una candela verso oriente. Ripeti dodici volte «Om Suryaya namah», con calma, a voce bassa, poi lascia la fiamma accesa per qualche minuto mentre respiri piano.',
    'salmi_martini|10|Aladiah': 'Quando un vecchio errore torna a pesare, leggi a voce «Sia sopra di noi, o Signore, la tua misericordia, conforme noi in te abbiamo sperato». Fallo tre volte ricordando quello che è successo senza cancellarlo. Lascia che smetta di dire chi sei. Ricominciare è un gesto piccolo.',
    'salmi_martini|11|Lauviah': 'Pensa a un progetto lungo che stai portando avanti. Leggi in piedi «Viva il Signore, e diasi benedizione al mio Dio, e sia glorificato il Dio di mia salute». Due letture bastano, con voce piena. Chiediti che cosa ti fa continuare quando l\'entusiasmo dei primi giorni è passato.',
    'salmi_martini|12|Hahaiah': 'La sera, prima di dormire, leggi sottovoce «E perchè, o Signore, ti se\' ritirato in lontananza, ci hai negletti nel maggior uopo, nella tribolazione?». Ripetilo due volte e poi resta in silenzio al buio. Se nella notte arriva un sogno o un\'intuizione, accoglilo senza pretendere spiegazioni.',
    'salmi_martini|13|Iezalel': 'Pensa alle persone che tieni insieme. Leggi con voce piena «Canti con giubbilo laude a Dio tutta quanta la terra: cantate ed esultate al suono de\' musicali strumenti». Tre volte, anche cantando se ti viene. Ricorda un nome che altri dimenticano. Fedeltà qui vuol dire memoria viva.',
    'salmi_martini|14|Mebahel': 'Quando devi dire una cosa scomoda, leggi prima «E il Signore è stato rifugio al povero, aiutatore al tempo opportuno, nella tribolazione». Pronuncialo due volte senza alzare il tono. Chiediti se la verità che porti protegge qualcuno senza diventare un\'arma. Applica la stessa misura prima di tutto a te.',
    'salmi_martini|15|Hariel': 'Riordina il tavolo o la stanza dove lavori. Poi leggi a voce «Ma il Signore è stato mio rifugio, e il mio Dio il sostegno di mia speranza». Ripetilo tre volte mentre guardi lo spazio che hai sistemato. Lascia che le idee prendano ordine come le cose intorno a te.',
    'salmi_martini|16|Hakamiah': 'Nel momento in cui vorresti sparire da una situazione difficile, leggi «Signore Dio di mia salute, di giorno e di notte alzai le mie grida dinanzi a te». Dillo due volte restando al tuo posto per tutto il tempo della lettura. Poi parla chiaro, anche se la franchezza costa qualcosa.',
    'salmi_martini|17|Lauviah II': 'Quando un\'intuizione arriva di notte, leggi «Signore, Signor nostro, quanto ammirabile è il nome tuo per tutta quanta la terra! Perocchè la tua maestà è elevata fin sopra dei cieli». Una volta sola basta. Poi annota l\'intuizione su un foglio e trattala come un dato da verificare.',
    'salmi_martini|18|Caliel': 'Prima di prendere posizione su una questione, leggi «Il Signore fa giudizio dei popoli. Fammi ragione, o Signore, secondo la mia giustizia, e secondo l\'innocenza che è in me». Ripetilo due volte con la voce bassa. Separa il fatto dall\'opinione. Poi decidi senza bisogno di alzare il tono.',
    'salmi_martini|19|Leuviah': 'Ripensa a una questione rimasta aperta nel tuo passato. Leggi con calma «Aspettai ansiosamente il Signore, ed egli a me si rivolse». Ripetilo tre volte lasciando fra una lettura e l\'altra il tempo di un respiro. Ricorda per capire. Non serve rinfacciare niente a nessuno.',
    'salmi_martini|1|Vehuiah': 'Al mattino, prima di cominciare, leggi a voce «Tu però, o Signore, tu se\' mio scudo, mia gloria, e tu rinnalzi il mio capo». Ripetilo tre volte pensando a una cosa che rimandi da tempo. Il versetto non sceglie al posto tuo: accompagna il primo passo.',
    'salmi_martini|20|Pahaliah': 'Pensa a un\'abitudine che ti blocca da tempo. Leggi con voce chiara «Signore, libera l\'anima mia dalle labbra inique e dalla lingua ingannatrice». Ripeti il versetto tre volte. Decidi una sola cosa che consideri non negoziabile. Cambiare direzione è una scelta da rinnovare ogni giorno.',
    'salmi_martini|21|Nelchael': 'Apri il libro o il quaderno che stai studiando. Prima di leggere, pronuncia «Io però in te sperai, o Signore; io dissi: Tu se\' il mio Dio». Dillo due volte e accetta di non capire subito. Il sapere serve a costruire qualcosa, non ad avere ragione.',
    'salmi_martini|22|Ieiaiel': 'Prima di presentare un lavoro agli altri, fermati e leggi «Il Signore ti custodisce: il Signore è tua difesa al tuo destro fianco». Tre letture, lente. Chiediti se ciò che consegni regge nel tempo. L\'applauso conta meno della solidità di quello che fai.',
    'salmi_martini|23|Melahel': 'Mentre annaffi una pianta o versi un bicchiere d\'acqua, leggi «Il Signore ti custodisca all\'entrare e all\'uscire, da questo punto, e per sempre». Ripetilo ogni sera per una settimana. La costanza di questo gesto piccolo vale più di un gesto grande fatto una volta.',
    'salmi_martini|24|Haheuiah': 'Pensa a chi oggi si sente fuori posto, anche a te. Leggi «Ecco gli occhi del Signore sopra coloro che lo temono, e sopra coloro, che confidano nella sua misericordia». Ripetilo due volte tenendo in mente quella persona. Stai accanto a quella condizione con fermezza più che con pietà.',
    'salmi_martini|25|Nithhaiah': 'Concediti qualche minuto di silenzio prima di parlare. Poi leggi «Te io loderò o Signore, con tutto il mio cuore: racconterò tutte le tue meraviglie». Ripetilo tre volte e torna al silenzio. Le intuizioni arrivano spesso quando smetti di cercarle. Lascia che la parola venga dopo.',
    'salmi_martini|26|Haaiah': 'Prima di un confronto in cui le posizioni si irrigidiscono, leggi «Gridai con tutto il mio cuore: esaudiscimi, o Signore: fa\' ch\'io cerchi le tue giustificazioni». Ripetilo due volte cercando dentro di te il punto di incontro. Pensa alla cosa giusta da dire senza alzare la voce.',
    'salmi_martini|27|Ierathel': 'Quando senti una pressione ingiusta su di te o su qualcuno che stimi, leggi a voce ferma «Liberami, o Signore, dall\'uomo cattivo: liberami dall\'uomo iniquo». Ripetilo tre volte. Chiediti dove puoi portare chiarezza. Usa la fermezza per difendere chi ne ha bisogno. Mai per colpire.',
    'salmi_martini|28|Seheiah': 'Prima di una decisione presa di corsa, rallenta e leggi «Non ti dilungare, o Dio, da me; Dio mio, volgiti ad aiutarmi». Dillo tre volte con un respiro lungo fra le letture. Guarda la strada davanti a te. Scegli un passo che puoi sostenere.',
    'salmi_martini|29|Reiiel': 'Pensa a una credenza ricevuta che ormai ti sta stretta. Leggi piano «Ecco però, che Dio mi aiuta, e il Signore ha presa a difendere la mia vita». Ripetilo due volte, poi lascia andare un legame che trattiene, senza rancore verso chi te l\'ha dato.',
    'salmi_martini|2|Ieliel': 'Trova un momento di quiete e pronuncia «Signore, non allontanar da me il tuo soccorso; accorri in mia difesa». Dillo due volte pensando a un legame che ti sta a cuore. Chiediti che cosa lo tiene insieme dopo un disaccordo. Lascia un silenzio prima di tornare alle tue cose.',
    'salmi_martini|30|Omael': 'Nei giorni in cui nulla sembra muoversi, leggi piano «Imperocchè tu se\', o Signore, la mia aspettazione: Signore, tu mia speranza fin dalla mia gioventù». Ripetilo tre volte senza forzare il raccolto. Pensa a come preparare il terreno per ciò che matura lentamente.',
    'salmi_martini|31|Lecabel': 'Prima di un lavoro di precisione, leggi «Perchè io non ho cognizione di lettere m\'internerò nella possanza del Signore; della sola giustizia tua, o Signore, io mi ricorderò». Basta una lettura lenta. Poi guarda il dettaglio senza perdere l\'insieme del progetto.',
    'salmi_martini|32|Vasariah': 'Quando stai per giudicare qualcuno, leggi «Perocchè diritta ell\'è la parola del Signore, e tutte le opere di lui sono nella fedeltà». Dillo due volte prima di aprire bocca. Separa l\'errore dalla persona che l\'ha commesso. Misura con calma prima di pronunciarti.',
    'salmi_martini|33|Iehuiah': 'Prima di entrare al lavoro o in una riunione, leggi in silenzio e poi a voce «Il Signore conosce i pensieri degli uomini, e come son vani». Due letture bastano. Distingui il ruolo dalla persona che lo occupa. Tieni la promessa che hai fatto anche quando costa.',
    'salmi_martini|34|Lehahiah': 'Quando senti salire la collera, fermati. Respira tre volte e leggi «Nel Signore speri Israele da questo punto, e pei secoli». Ripetilo finché la voce torna piana. La calma che cerchi non è debolezza: è una forza che sceglie di non esplodere. Riprendi poi la conversazione.',
    'salmi_martini|35|Chavakhiah': 'Pensa a una persona di famiglia con cui il filo si è spezzato. Leggi a mezza voce «Ho amato, perchè esaudirà il Signore la voce della mia orazione». Ripetilo tre volte e chiediti quale primo passo è possibile. Scegliere il legame non significa dare ragione all\'altro.',
    'salmi_martini|36|Menadel': 'All\'inizio della giornata di lavoro, leggi «Signore, io ho amato lo splendore della tua casa, e il luogo dove abita la tua gloria». Ripetilo due volte guardando il luogo dove ti trovi. Chiediti che cosa ha ancora da insegnarti il posto che occupi oggi.',
    'salmi_martini|37|Aniel': 'Quando ti accorgi di girare intorno alla stessa cosa, leggi «Dio degli eserciti, convertici, e mostraci la tua faccia, e sarem salvi». Ripetilo tre volte e dai un nome al cerchio che si ripete. Poi decidi con lucidità il primo gesto per uscirne.',
    'salmi_martini|38|Haamiah': 'Scegli un\'ora fissa del giorno per questo gesto. Leggi «(E dirai): Tu se\', o Signore, la mia speranza: e che per tuo rifugio hai scelto l\'Altissimo». Ripetilo tre volte alla stessa ora per alcuni giorni. Il rito non serve a ottenere: ricorda chi sei mentre lo compi.',
    'salmi_martini|39|Rehael': 'Pensa a un genitore o a un figlio. Leggi a voce «Il Signore mi udì, ed ebbe pietà di me: il Signore si fe\' mio aiuto». Ripetilo due volte con quel volto davanti agli occhi. Prova a guardare quella persona senza il conto aperto degli anni passati.',
    'salmi_martini|3|Sitael': 'Richiama alla mente una promessa che hai fatto. Leggi a voce «Egli dirà al Signore: Mio difensore sei tu, e mio asilo: egli è il mio Dio, in lui spererò». Fallo tre volte. Guarda quanto tempo vuoi ancora dare a quella parola, anche ora che costa di più.',
    'salmi_martini|40|Ieiazel': 'Quando qualcuno accanto a te attraversa la tristezza, leggi per te «E perchè, o Signore, rigetti tu la mia orazione, e rivolgi da me la tua faccia?». Una lettura sola, a bassa voce. Poi resta accanto senza spiegare. Il dolore chiede presenza, non fretta.',
    'salmi_martini|41|Hahahel': 'Prima di parlare in pubblico o di insegnare, leggi «Signore, libera l\'anima mia dalle labbra inique e dalla lingua ingannatrice». Ripetilo due volte con lentezza. Chiediti se quello che dici corrisponde a quello che fai quando nessuno guarda. La fiducia degli altri resta nelle tue mani.',
    'salmi_martini|42|Mikael': 'Prima di una trattativa o di un viaggio, leggi con voce tranquilla «Il Signore ti custodisce da ogni male: custodisca il Signore l\'anima tua». Ripetilo tre volte mettendo ordine nei pensieri. Guarda le cose come stanno prima di prendere posizione. La responsabilità resta tua.',
    'salmi_martini|43|Veualiah': 'Al mattino, davanti a un compito da portare a termine, leggi «Ma io alzai a te le grida, o Signore, e la mia orazione al mattino ti preverrà». Due volte, poi scrivi il prossimo passo verificabile. La disciplina conta più dell\'entusiasmo.',
    'salmi_martini|44|Ielahiah': 'Quando mantenere la parola data costa, leggi «Sien graditi a te, o Signore, i volontari sacrifizi della mia bocca: e insegnami i tuoi giudizi». Ripetilo due volte ricordando che cosa hai promesso e a chi. Chiediti come restare coerente anche sotto pressione.',
    'salmi_martini|45|Sealiah': 'Dopo una caduta, anche piccola, leggi «Se io diceva a te: il mio piede vacilla; la tua misericordia, o Signore, veniva in mio soccorso». Ripetilo tre volte con calma. Rimetti in moto una sola cosa che si era fermata. Non pretendere che accada tutto subito.',
    'salmi_martini|46|Ariel': 'Prima di indagare su un dettaglio che ti incuriosisce, leggi «Il Signore con tutti è benefico, e in tutte le opere di lui han luogo le sue misericordie». Due letture, poi verifica con pazienza quello che hai notato invece di innamorartene.',
    'salmi_martini|47|Asaliah': 'Prima di dire una parola che pesa sulla vita di altri, leggi «Quanto grandiose son le opere tue, o Signore! ogni cosa hai tu fatto con sapienza: la terra è piena di tue ricchezze». Una lettura lenta basta. Cerca il vero prima del comodo.',
    'salmi_martini|48|Mihael': 'Pensa al legame che ti è più vicino. Leggi, anche insieme all\'altra persona, «Il Signore ha manifestata la sua salute: ha rivelata la sua giustizia agli occhi delle nazioni». Ripetilo due volte. Resta presente anche nei giorni in cui il legame restituisce poco.',
    'salmi_martini|49|Vehuel': 'Prima di valutare il lavoro di qualcuno, leggi «Grande il Signore, e laudabile oltre modo: e la grandezza di lui non ha termine». Ripetilo tre volte con voce piana. Usa il tuo metro alto per riconoscere il valore di chi hai davanti. Non per pesarti addosso.',
    'salmi_martini|4|Elemiah': 'Quando una strada sembra inceppata, fermati un istante e leggi «Volgiti, o Signore, e libera l\'anima mia: per tua misericordia dammi salute». Ripeti il versetto due volte prima di muoverti. Prova a distinguere l\'ostacolo vero dal tumulto che senti dentro. Non cercare subito una soluzione: per ora basta vedere meglio.',
    'salmi_martini|50|Daniel': 'Davanti a una scelta rimandata troppo a lungo, siediti e leggi «Il Signore misericordioso e benigno: paziente e misericordioso grandemente». Ripetilo tre volte senza correre. Ascolta le ragioni di chi la pensa diversamente. Poi passa dal dubbio alla scelta, sapendo che una decisione può costare qualcosa.',
    'salmi_martini|51|Hahasiah': 'Prima di metterti al lavoro su una cosa nuova, leggi «Sia celebrata pei secoli la gloria del Signore: si allegrerà il Signore nelle opere sue». Ripetilo due volte e chiediti come funziona davvero quello che hai davanti. Tieni il metodo, lascia la pretesa di sapere tutto.',
    'salmi_martini|52|Imamiah': 'Quando riconosci un tuo errore, leggi a voce «Glorificherò il Signore per la sua giustizia, e al nome del Signore altissimo canterò inni di laude». Due volte, senza trasformarlo in condanna. Scegli un fatto concreto con cui cominciare a riparare.',
    'salmi_martini|53|Nanael': 'Nel silenzio di un momento di studio, leggi «Ho conosciuto, o Signore, che i giudizi tuoi sono equità; e che secondo la tua verità tu mi hai umiliato». Ripetilo una volta. Pensa a come trasmettere ciò che sai senza umiliare chi ascolta.',
    'salmi_martini|54|Nithael': 'Davanti a una cosa bella che altri non notano, leggi «Il Signore ha preparato in cielo il suo trono, e al regno di lui tutti saranno soggetti». Ripetilo due volte mentre la guardi. Chiediti che cosa di quello che fai può durare oltre te.',
    'salmi_martini|55|Mebahiah': 'Pensa a un principio in cui credi. Leggi «Ma tu, o Signore, duri in eterno, e di generazione in generazione va la ricordanza di te». Dillo due volte e poi scegli un gesto di oggi che lo renda visibile. Le parole dichiarate contano meno dei fatti.',
    'salmi_martini|56|Poyel': 'Quando qualcosa cede, la fiducia o un progetto, leggi «Il Signore sostenta tutti que\', che stan per cadere, e rialza tutti que\' che si sono infranti». Ripetilo tre volte e chiedi soltanto quello che serve davvero. Rialzarsi viene prima di salire.',
    'salmi_martini|57|Nemamiah': 'Prima di una decisione rapida, leggi «Nel Signore hanno sperato quelli, che temono: egli è loro aiuto e lor protettore». Ripetilo due volte separando la sostanza dall\'apparenza. Decidi in fretta solo dopo aver nominato a voce alta ciò che hai capito davvero.',
    'salmi_martini|58|Ieialel': 'Quando la fatica di un lavoro lungo si fa sentire, leggi «E l\'anima mia è grandemente turbata: ma tu, o Signore, fino a quando?». Ripetilo due volte e poi torna sulla cosa che stai facendo. Guardala finché non ne vedi la causa.',
    'salmi_martini|59|Harahel': 'Prima di riordinare carte, appunti o archivi, leggi a voce «Dall\'oriente fino all\'occaso ha da lodarsi il nome del Signore». Ripetilo tre volte, all\'inizio e alla fine del lavoro. Chiediti che cosa di quello che conservi merita di passare a qualcun altro. Giudica con misura.',
    'salmi_martini|5|Mahasiah': 'Prima di studiare o di parlare con una persona che si è allontanata, leggi piano «Cercai il Signore, e mi esaudì: e mi trasse fuori di tutte le mie tribolazioni». Ripetilo tre volte respirando con calma. Osserva il clima che porti nella stanza ancora prima di dire una parola.',
    'salmi_martini|60|Mitzrael': 'Pensa a qualcosa che si è rotto dentro di te o fra te e un\'altra persona. Leggi «Giusto il Signore in tutte le sue vie, e santo in tutte le opere sue». Tre letture, una dopo l\'altra. Scegli la pazienza al posto della rivincita.',
    'salmi_martini|61|Umabel': 'Pensa a un\'amicizia che ti è cara. Leggi a voce, con calma, «Sia benedetto il nome del Signore, da questo punto fino ne\' secoli». Ripetilo due volte sentendo la vicinanza dell\'altra persona. Ricorda però dove finisci tu e dove comincia lei.',
    'salmi_martini|62|Iahhel': 'Prima di rispondere a una domanda difficile, ritirati per un momento e leggi «Mira, o Signore, com\'io ho amati i tuoi precetti: per tua misericordia dammi la vita». Basta una volta. Il silenzio scelto prepara una parola misurata, che arriva al momento giusto.',
    'salmi_martini|63|Anauel': 'Quando due interessi sembrano opposti, leggi «Canti con giubbilo le lodi di Dio tutta quanta la terra: servite il Signore con allegrezza». Ripetilo tre volte cercando il punto in cui le due parti possono incontrarsi. Comincia da lì, con un passo piccolo.',
    'salmi_martini|64|Mehiel': 'Prima di scrivere o di parlare in pubblico, leggi «Ecco gli occhi del Signore sopra coloro che lo temono, e sopra coloro, che confidano nella sua misericordia». Una sola lettura, con tutta l\'attenzione. Unisci quello che senti a quello che ragioni, senza sacrificare nessuno dei due.',
    'salmi_martini|65|Damabiah': 'Vicino a un\'acqua che scorre, anche quella di un rubinetto, leggi «Volgiti a noi, o Signore: e fino a quando (sarai sdegnato)? placati coi servi tuoi». Ripetilo due volte ascoltando il suono dell\'acqua. Ascolta prima di parlare. Attingi alla sorgente che hai dentro.',
    'salmi_martini|66|Manakel': 'La sera, quando la giornata si chiude, leggi sottovoce «Non abbandonarmi, Signore Dio mio, non ti allontanare da me». Ripetilo tre volte prima di dormire. Pensa a ciò che hai lasciato indietro. Lascia che le cose vive crescano col loro ritmo, senza forzarle.',
    'salmi_martini|67|Eiael': 'In un momento di solitudine scelta, in un angolo quieto, leggi «Metti la tua consolazione nel Signore, ed ei ti darà quello, che il tuo cuore domanda». Ripetilo due volte lentamente. Allena lo sguardo: cerca una cosa bella dove di solito passi oltre.',
    'salmi_martini|68|Habuhiah': 'Prima di un gesto generoso, piccolo e concreto, leggi «Date lode al Signore, perchè egli è buono, perchè eterna ell\'è la sua misericordia». Ripetilo tre volte, poi dai senza contare e senza aspettarti un ritorno. Lascia che il gesto parli prima delle parole.',
    'salmi_martini|69|Rochel': 'Quando cerchi chiarezza su qualcosa che è andato perso, leggi «Il Signore è la porzione di mio retaggio e del mio calice: tu se\' quegli, che a me restituirai la mia eredità». Una lettura, poi un respiro lungo. Non avere fretta di giudicare.',
    'salmi_martini|6|Lelahel': 'Tieni in mente una tua capacità. Recita a voce chiara «Cantate inni al Signore, che abita in Sion, annunziate i consigli di lui tralle nazioni». Ripetilo due volte guardando le tue mani. Domandati per chi altro puoi usare quel talento questa settimana. La risposta può arrivare piano: lasciale spazio.',
    'salmi_martini|70|Iabamiah': 'In un passaggio della vita, quando qualcosa finisce e altro comincia, leggi a voce «Al principio creò Dio il cielo e la terra». Tre volte, con pause lunghe. Guarda la forma che cambia. Resta al tuo lavoro mentre accade: la trasformazione si costruisce giorno per giorno.',
    'salmi_martini|71|Haiaiel': 'Quando devi dire no per difendere qualcuno, leggi «Celebrerò altamente colla mia bocca il Signore: e nella numerosa adunanza a lui darò lode». Ripetilo due volte con la mente fredda. Prendi la decisione senza impulso. Non cercare applausi in cambio.',
    'salmi_martini|72|Mumiah': 'Alla fine di un lavoro, prima di passare al successivo, leggi «Torna, o anima mia, nella tua requie: perocchè il Signore ti ha fatto del bene». Ripetilo tre volte e chiudi davvero ciò che è finito. Così ricominci senza trascinarti dietro il vecchio.',
    'salmi_martini|7|Achaiah': 'Scegli una domanda che ti accompagna da tempo e che hai smesso di guardare. Leggi a voce bassa «Il Signore misericordioso e benigno: paziente e misericordioso grandemente». Ripetilo sette volte senza fretta. Ogni ripetizione è un ritorno alla stessa cosa: così la pazienza continua a osservare anche quando l\'interesse cala.',
    'salmi_martini|8|Cahethel': 'Prima di un pasto o a fine lavoro, leggi «Venite, adoriamolo e prostriamoci, e spargiamo lacrime dinanzi al Signore, di cui siamo fattura». Dillo due volte con le mani aperte. Nomina in silenzio una cosa che hai ricevuto e da dove viene. Lascia che quel ricordo guidi il gesto successivo.',
    'salmi_martini|9|Haziel': 'Pensa a un torto che porti ancora con te. Leggi lentamente «Ricordati di tue misericordie, o Signore, delle tue misericordie, che furono nei secoli addietro». A ognuna delle tre letture chiediti se quel peso ti serve ancora. Perdonare resta una scelta tua, da fare senza fretta.',
  };

